window.UNIFIED_QUESTIONS=[{"id":"w1","major":"词汇与综合","minor":"字音字形","question":"下列词语中，加点字的书写和注音完全正确的一项是（ ）。","options":[{"key":"A","text":"星宿（xiù） 赈灾（zhèng） 解剖（pōu） 悲怆（chuàng）"},{"key":"B","text":"忌讳（huì） 脑髓（suǐ） 酝酿（niàng） 漂悍（piāo）"},{"key":"C","text":"纨绔（kù） 磐石（pán） 恻隐（chè） 提防（dī）"},{"key":"D","text":"烙铁（lào） 亵渎（dú） 啮齿（niè） 御聘（pìn）"}],"answer":"D","explanation":"D项书写和读音均正确。A项“赈灾”的“赈”读zhèn；B项应为“剽悍”；C项“恻隐”的“恻”读cè。","source":"word #1","bad":false,"notice":""},{"id":"w2","major":"词汇与综合","minor":"易错字","question":"下列词语中，没有错别字的一项是（ ）。","options":[{"key":"A","text":"兴高彩烈 烟雾弥漫"},{"key":"B","text":"言简意赅 骇人听闻"},{"key":"C","text":"来势凶凶 天迸地裂"},{"key":"D","text":"歧视 绫辱 内含深邃"}],"answer":"B","explanation":"B项书写正确。A项“兴高彩烈”应为“兴高采烈”；C项“来势凶凶”应为“来势汹汹”，“天迸地裂”应为“天崩地裂”；D项“绫辱”应为“凌辱”。","source":"word #2","bad":false,"notice":""},{"id":"w3","major":"词汇与综合","minor":"易错字","question":"下列各组词语中，书写完全正确的一项是（ ）。","options":[{"key":"A","text":"原野 气魄 赞歌 高山之颠"},{"key":"B","text":"狂澜 浊流 婉转 惊涛膨湃"},{"key":"C","text":"连环 奔腾 摇蓝 发扬滋长"},{"key":"D","text":"屏障 臂膀 哺育 一泻万丈"}],"answer":"D","explanation":"D项书写正确。A项“高山之颠”应为“高山之巅”；B项“惊涛膨湃”应为“惊涛澎湃”；C项“摇蓝”应为“摇篮”。","source":"word #3","bad":false,"notice":""},{"id":"w4","major":"词汇与综合","minor":"易错字","question":"下列词语中，书写有误的一项是（ ）。","options":[{"key":"A","text":"汇合 燃烧 喷涌"},{"key":"B","text":"泛滥 惊醒 跳跃"},{"key":"C","text":"嗥鸣 孤仙 碧绿"},{"key":"D","text":"呼唤 皮鞭 土壤"}],"answer":"C","explanation":"C项“孤仙”应为“孤山”。其余各项书写正确。","source":"word #4","bad":false,"notice":""},{"id":"w5","major":"词汇与综合","minor":"易错字","question":"选出没有错别字的一项（ ）。","options":[{"key":"A","text":"瞳仁 晦暗 明析 谴责"},{"key":"B","text":"振撼 耳绊 辐射 悬涯"},{"key":"C","text":"恬静 颤栗 充沛 燥热"},{"key":"D","text":"束缚 凝聚 敲垂 锻炼"}],"answer":"C","explanation":"C项书写正确。A项“明析”应为“明晰”；B项应为“震撼、耳畔、悬崖”；D项“敲垂”应为“敲击”或依语境改为其他正确词语。","source":"word #5","bad":false,"notice":""},{"id":"w6","major":"词汇与综合","minor":"易错字","question":"下列词语中，没有别字的一组是（ ）。","options":[{"key":"A","text":"魁梧 无精打采 循序渐进"},{"key":"B","text":"防碍 抑扬顿挫 大事渲染"},{"key":"C","text":"停滞 狼狈不堪 相题并论"},{"key":"D","text":"贫瘠 敝帚自珍 杏无消息"}],"answer":"A","explanation":"A项书写正确。B项“防碍”应为“妨碍”；C项“相题并论”应为“相提并论”；D项“杏无消息”应为“杳无消息”。","source":"word #6","bad":false,"notice":""},{"id":"w7","major":"词汇与综合","minor":"易错字","question":"下列词语中，没有错别字的一项是（ ）。","options":[{"key":"A","text":"更胜一筹 义愤填膺 销声匿迹 正襟危坐"},{"key":"B","text":"相形见绌 格守尽职 因地制宜 无精打采"},{"key":"C","text":"突如奇来 莫衷一是 语无伦次 迫不及待"},{"key":"D","text":"顾名思意 一筹莫展 怨天尤人 相辅相成"}],"answer":"A","explanation":"A项书写正确。B项“格守尽职”应为“恪守尽职”；C项“突如奇来”应为“突如其来”；D项“顾名思意”应为“顾名思义”。","source":"word #7","bad":false,"notice":""},{"id":"w8","major":"词汇与综合","minor":"字音","question":"下列词语中，加点字的读音正确的一项是（ ）。","options":[{"key":"A","text":"自怨自艾（yì）"},{"key":"B","text":"刚愎自用（fù）"},{"key":"C","text":"暴殄天物（zhēn）"},{"key":"D","text":"刚正不阿（ā）"}],"answer":"A","explanation":"“自怨自艾”的“艾”在此读yì，意为改正。B项“愎”读bì；C项“殄”读tiǎn；D项“阿”读ē。","source":"word #8","bad":false,"notice":""},{"id":"w9","major":"词汇与综合","minor":"词语辨析","question":"“离开了世俗的纷扰，离开了利益的纷争，人的内心会逐渐归于清静。”句中“清静”使用不当，应改为（ ）。","options":[{"key":"A","text":"清净"},{"key":"B","text":"寂静"},{"key":"C","text":"安静"},{"key":"D","text":"幽静"}],"answer":"A","explanation":"“清净”可形容人的内心没有杂念或不受外界干扰；“清静”通常侧重环境安静。此处修饰“内心”，应改为“清净”。","source":"word #9","bad":false,"notice":""},{"id":"w10","major":"词汇与综合","minor":"语境填空","question":"在下面一段话的空缺处依次填入词语，最恰当的一组是（ ）。国学经典数量众多，____，虽然是很多古人杰出智慧的成果，但也存在不合理、不科学的成分。正是这种____的状况，使得国学阅读尤其要注重甄别、择善而读。国学经典蕴含着丰富的知识与深刻的哲理，唯有____，才能慢慢领悟。","options":[{"key":"A","text":"凤毛麟角 良莠不一 融会贯通"},{"key":"B","text":"汗牛充栋 良莠不一 囫囵吞枣"},{"key":"C","text":"汗牛充栋 参差不齐 细嚼慢咽"},{"key":"D","text":"浩如烟海 参差不齐 浅尝辄止"}],"answer":"C","explanation":"“汗牛充栋”形容书籍很多；“参差不齐”可形容内容水平不一；“细嚼慢咽”比喻慢慢体会。三者与语境均吻合。","source":"word #10","bad":false,"notice":""},{"id":"w11","major":"词汇与综合","minor":"成语辨析","question":"古人有“闻过则喜”之说，而今天有些人则不然，总是____，对比之下，实在天差地别。填入横线最恰当的一项是（ ）。","options":[{"key":"A","text":"瑕不掩瑜"},{"key":"B","text":"讳疾忌医"},{"key":"C","text":"刚愎自用"},{"key":"D","text":"好大喜功"}],"answer":"B","explanation":"“讳疾忌医”比喻怕人批评而掩饰自己的缺点和错误，与“闻过则喜”形成直接对比。","source":"word #11","bad":false,"notice":""},{"id":"w12","major":"词汇与综合","minor":"语境填空","question":"报刊、广播、电视和网络等媒介为公众提供了表达渠道，普通人也能成为主动的发声者，既可以____，也可能传播不实之词、____，直接影响社会和谐。依次填入最恰当的一项是（ ）。","options":[{"key":"A","text":"各抒己见 捕风捉影"},{"key":"B","text":"慷慨陈词 集思广益"},{"key":"C","text":"集思广益 风言风语"},{"key":"D","text":"畅所欲言 博采众长"}],"answer":"A","explanation":"“各抒己见”符合公众表达意见的语境；“捕风捉影”比喻说话做事毫无根据，与“不实之词”衔接恰当。","source":"word #12","bad":false,"notice":""},{"id":"w13","major":"词汇与综合","minor":"语境填空","question":"城市并不是一个____的系统，它要进行资源输入、废物排出以及内部运转。所有生态流都可以定量计算。城市设计必须根据周围的生态承载力确定城市规模，与生态环境形成良好的____关系。依次填入最恰当的一项是（ ）。","options":[{"key":"A","text":"循环 支持"},{"key":"B","text":"封闭 匹配"},{"key":"C","text":"机械 符合"},{"key":"D","text":"动态 平衡"}],"answer":"D","explanation":"城市处于持续变化和交换之中，应用“动态”；城市规模与生态承载力之间应形成“平衡”关系。","source":"word #13","bad":false,"notice":""},{"id":"w14","major":"词汇与综合","minor":"成语辨析","question":"下面成语中，意思比较接近的一组是（ ）。","options":[{"key":"A","text":"顺水推舟—顺藤摸瓜"},{"key":"B","text":"桃李不言—瓜田李下"},{"key":"C","text":"三人成虎—众口铄金"},{"key":"D","text":"一蹴而就—一劳永逸"}],"answer":"C","explanation":"“三人成虎”和“众口铄金”都强调流言或众人的言论反复传播会造成强大影响。其余各组含义差异较大。","source":"word #14","bad":false,"notice":""},{"id":"w15","major":"词汇与综合","minor":"词语辨析","question":"大学生活即将结束，老师的____给我留下了深刻的印象。填入横线最恰当的一项是（ ）。","options":[{"key":"A","text":"告诉"},{"key":"B","text":"告诫"},{"key":"C","text":"劝诫"},{"key":"D","text":"忠告"}],"answer":"D","explanation":"“忠告”指诚恳地劝告，也可作名词，能够自然充当句子的主语。“告诉”通常作动词；“告诫、劝诫”在此搭配不如“忠告”自然。","source":"word #15","bad":false,"notice":""},{"id":"w16","major":"词汇与综合","minor":"关联词","question":"依次填入下列句中横线处的关联词，最恰当的一项是（ ）。①上千吨的轮船碰上这样大的风浪也得上下颠簸，____这么一条小船。②挖这样的井，占地多，不合算，____井的四周都是沙土，很容易塌陷。③改革后，产品质量提高了，款式新颖了，____更加受到群众欢迎。","options":[{"key":"A","text":"何况 而且 因而"},{"key":"B","text":"况且 何况 而且"},{"key":"C","text":"何况 因而 而且"},{"key":"D","text":"而且 何况 因而"}],"answer":"A","explanation":"①由大轮船推及小船，用“何况”；②补充另一个不利条件，用“而且”；③前因后果，用“因而”。","source":"word #16","bad":false,"notice":""},{"id":"w17","major":"词汇与综合","minor":"词语辨析","question":"交流是复杂的艺术。有声语言不是表达意义的唯一方式，形体语言同样重要。各民族间的形体语言有的形式和意义相同，有的虽然形式相同，意义却____。填入横线最恰当的一项是（ ）。","options":[{"key":"A","text":"南辕北辙"},{"key":"B","text":"针锋相对"},{"key":"C","text":"背道而驰"},{"key":"D","text":"截然相反"}],"answer":"D","explanation":"这里比较的是同一形式在不同文化中的意义完全不同，“截然相反”最准确。“南辕北辙、背道而驰”多形容行动与目的相反，“针锋相对”多形容双方观点或行动对立。","source":"word #17","bad":false,"notice":""},{"id":"w18","major":"词汇与综合","minor":"词语辨析","question":"在下列各句横线处依次填入词语，正确的一组是（ ）。①误会产生之后，人们并没有给他____的机会。②这两个问题之间没有什么关联，应当____处理。③大家的力量____在一起，就没有克服不了的困难。","options":[{"key":"A","text":"分辩 各别 会合"},{"key":"B","text":"分辩 分别 汇合"},{"key":"C","text":"分辨 各别 会合"},{"key":"D","text":"分辨 分别 汇合"}],"answer":"B","explanation":"“分辩”指辩白；“分别”指按不同情况处理；“汇合”指聚集到一起。三处依次选“分辩、分别、汇合”。","source":"word #18","bad":false,"notice":""},{"id":"w19","major":"词汇与综合","minor":"虚词辨析","question":"查韦斯认为，新自由主义发展的模式不适合拉美国家。他试图建立一种以人为中心、结合市场机制和国家调节作用的社会发展道路。这种道路____“不现实”的共产主义，____“野蛮”的资本主义，____一种有合理市场竞争的社会主义；____要适当加入全球化，____要确保自己的民族特性。依次填入最恰当的一项是（ ）。","options":[{"key":"A","text":"既是 又是 还是 而且 但是"},{"key":"B","text":"既不是 也不是 而是 而且 还"},{"key":"C","text":"不是 就是 而是 虽然 但是"},{"key":"D","text":"既是 也是 不是 虽然 但是"}],"answer":"B","explanation":"前两空并列否定，第三空转入肯定，应用“既不是……也不是……而是……”；后两层语意递进，用“而且……还……”。","source":"word #19","bad":false,"notice":""},{"id":"w20","major":"词汇与综合","minor":"实词辨析","question":"“你怎么啦？”这句话在不同语境中可以表示____、____、____、____等不同情绪。离开语境，就不能真正理解语言的意义。依次填入最恰当的一项是（ ）。","options":[{"key":"A","text":"怀疑 焦急 紧张 激动"},{"key":"B","text":"担心 沮丧 询问 痛苦"},{"key":"C","text":"不解 惊奇 关切 责备"},{"key":"D","text":"惊惶 喜悦 询问 关切"}],"answer":"C","explanation":"同一句话可随语境表达疑惑、惊讶、关心或责备。C项四个词都能与“你怎么啦”形成自然语境。","source":"word #20","bad":false,"notice":""},{"id":"w21","major":"词汇与综合","minor":"成语辨析","question":"定义的使命是抽象、概括某类事物的本质特征。定义应当根据实践不断修正，而有人却常常“开除”那些概括不了的同类事物，以维护定义的纯洁性，这无疑是（ ）。","options":[{"key":"A","text":"指鹿为马"},{"key":"B","text":"掩耳盗铃"},{"key":"C","text":"本末倒置"},{"key":"D","text":"削足适履"}],"answer":"D","explanation":"“削足适履”比喻不合理地迁就现成条件，或生搬硬套。为了维护定义而排除真实事物，正是让事实迁就定义。","source":"word #21","bad":false,"notice":""},{"id":"w22","major":"词汇与综合","minor":"语境填空","question":"敦煌壁画共有五万多平方米，若按一米高排列，有五十多公里长；若要____地浏览一遍，即使每幅只停留一秒，也要夜以继日。敦煌壁画的价值不只在数量之巨，更在其内涵的____。依次填入最恰当的一项是（ ）。","options":[{"key":"A","text":"浮光掠影 异彩纷呈"},{"key":"B","text":"一目十行 源远流长"},{"key":"C","text":"细致入微 独树一帜"},{"key":"D","text":"走马观花 博大精深"}],"answer":"D","explanation":"“每幅只停留一秒”对应粗略浏览的“走马观花”；形容文化内涵丰富深厚，应用“博大精深”。","source":"word #22","bad":false,"notice":""},{"id":"w23","major":"词汇与综合","minor":"语境填空","question":"作为公司领导，不需要也不可能事必躬亲，但一定要____，能够从细节中发现问题；在工作安排上要____，使团队形成执行力；面对推诿时不能一味____。依次填入最恰当的一项是（ ）。","options":[{"key":"A","text":"明察秋毫 周密 搪塞"},{"key":"B","text":"明辨是非 周详 推脱"},{"key":"C","text":"抓大放小 透彻 塞责"},{"key":"D","text":"高瞻远瞩 严密 敷衍"}],"answer":"A","explanation":"“明察秋毫”强调观察细微；“周密”可形容工作安排；“搪塞”指敷衍应付。三者与语境衔接最自然。","source":"word #23","bad":false,"notice":""},{"id":"w24","major":"词汇与综合","minor":"词语辨析","question":"该地区对环境保护采取了强有力的措施，使水土流失现象得到____，生态环境向良性循环转变。填入横线最恰当的一项是（ ）。","options":[{"key":"A","text":"制止"},{"key":"B","text":"遏制"},{"key":"C","text":"截止"},{"key":"D","text":"终止"}],"answer":"B","explanation":"“遏制”指控制、阻止某种趋势继续发展，常与“现象、势头”搭配。","source":"word #24","bad":false,"notice":""},{"id":"w25","major":"词汇与综合","minor":"病句辨析","question":"下列各句中，没有语病的一项是（ ）。","options":[{"key":"A","text":"孟非是近年来深受观众喜爱的电视节目主持人，他常常妙语连珠，拥有广泛的支持者，有很高的收视率。"},{"key":"B","text":"为了提高同学们的语文素养，我校团委积极开展“读经典作品，建书香校园”。"},{"key":"C","text":"盛夏，龙虾成了食客们的首选。请记住，吃龙虾切忌同时服用维生素C。"},{"key":"D","text":"“五四”的火炬传到了当代青年的手中，如何点燃和照亮自己的青春，是每个当代青年都要思考和面对的问题。"}],"answer":"C","explanation":"C项表意完整。A项“主持人”与“有很高的收视率”搭配不当；B项缺少“活动”作“开展”的宾语；D项“点燃青春”搭配不当，且“思考和面对问题”语序不当。","source":"word #25","bad":false,"notice":""},{"id":"w26","major":"词汇与综合","minor":"病句辨析","question":"下列各句中，没有语病的一句是（ ）。","options":[{"key":"A","text":"听了校长的报告，使我受到了极大的鼓舞。"},{"key":"B","text":"她做了两个丈夫喜欢的菜。"},{"key":"C","text":"敦煌艺术宝库的保存，使我们有可能了解一千五六百年来中国艺术成长发展的情况。"},{"key":"D","text":"在这次高交会上，各公司对网络信息交换了广泛的意见。"}],"answer":"C","explanation":"C项结构完整、搭配恰当。A项滥用介词导致主语残缺；B项有歧义；D项语序和搭配不当，应改为“各公司就网络信息交换问题广泛交换了意见”。","source":"word #26","bad":false,"notice":""},{"id":"w27","major":"词汇与综合","minor":"病句辨析","question":"下列各句中，没有语病的一项是（ ）。","options":[{"key":"A","text":"这篇作文真难写，我用了整整两个小时左右的时间，才写好交卷。"},{"key":"B","text":"我们应当认真解决和研究同学们提出的问题。"},{"key":"C","text":"张老师的一席话把我先前的顾虑全赶跑了。"},{"key":"D","text":"几个学校的中层干部就近期的德育工作发表了很好的意见。"}],"answer":"C","explanation":"C项表达通顺。A项“整整”与“左右”矛盾；B项应先“研究”再“解决”；D项“几个学校的中层干部”存在范围歧义。","source":"word #27","bad":false,"notice":""},{"id":"w28","major":"词汇与综合","minor":"病句辨析","question":"下列各句中，没有语病的一项是（ ）。","options":[{"key":"A","text":"营造健康文明的网络文化环境，清除不健康信息已成为新时期精神文明建设的迫切需要。"},{"key":"B","text":"在阅读文学名著的过程中，常常能够使我们明白许多做人的道理，悟出人生的真谛。"},{"key":"C","text":"会不会用心观察，能不能重视积累，是提高写作水平的基础。"},{"key":"D","text":"他上课认真听讲，下课一有工夫不是看语文、数学等书，就是看报纸，全班同学没有一个不说他学习不积极。"}],"answer":"A","explanation":"A项正确。B项滥用“在……过程中”和“使”导致主语残缺；C项两面对一面；D项“没有一个不说他学习不积极”与本意相反。","source":"word #28","bad":false,"notice":""},{"id":"w29","major":"词汇与综合","minor":"病句辨析","question":"下列各句中，没有语病的一项是（ ）。","options":[{"key":"A","text":"北京市将在大力发展首都经济、促进国民经济持续快速健康发展和社会全面进步的基础上，继续围绕广大人民群众普遍关心和反映强烈的问题办一批实事。"},{"key":"B","text":"秦山核电站每年的发电量，除了供本地使用外，还向上海、南京等地输送。"},{"key":"C","text":"尽管设计师们精心打造，将呈现出各种各样的几何构思，但建筑官员和建筑行家们更想了解公众更喜欢哪一种设计。"},{"key":"D","text":"今年春节期间，这个市的2100辆警车、3000多名民警、武警放弃休假，始终坚守在自己的岗位上。"}],"answer":"A","explanation":"A项结构和搭配正确。B项“发电量”不能“输送”，应改为“电力”；C项前一分句缺少主语；D项“警车”不能“放弃休假、坚守岗位”。","source":"word #29","bad":false,"notice":""},{"id":"w30","major":"词汇与综合","minor":"病句辨析","question":"下列各句中，没有语病的一句是（ ）。","options":[{"key":"A","text":"终身教育制度的建立，不仅为那些因各种原因未能完成学业的人打开了一扇大门，也为那些对知识有着更高需求的人提供了机会。"},{"key":"B","text":"报告团成员结合亲身的经历，深情地讲述了罗阳同志生前刻苦攻关的事迹，感人肺腑，催人泪下，深深打动了现场的听众。"},{"key":"C","text":"“蛟龙”号潜海成功，对于完善我国海洋科学研究和海洋装备制造业发展，提升我国开发海洋的能力，将产生重大而深远的影响。"},{"key":"D","text":"长期以来我国为钓鱼岛及其周边海域提供天气预报服务，为渔民生产、海上搜救提供了气象保障服务。"}],"answer":"A","explanation":"A项正确。B项“事迹”后连续使用“感人肺腑、催人泪下、打动听众”造成结构杂糅；C项“完善……发展”搭配不当；D项“提供……提供服务”表意重复。","source":"word #30","bad":false,"notice":""},{"id":"w31","major":"词汇与综合","minor":"病句辨析","question":"从下列句子中选出没有语病的一句（ ）。","options":[{"key":"A","text":"阅读理解与否，是衡量阅读能力好坏的重要标志。"},{"key":"B","text":"阅读与理解，是衡量阅读能力好坏的重要标志。"},{"key":"C","text":"阅读是否理解，是衡量阅读能力的重要标志。"},{"key":"D","text":"阅读能力好坏的标志是理解。"}],"answer":"A","explanation":"A项“理解与否”与“能力好坏”前后照应。B、D项表意不完整；C项两面对一面。","source":"word #31","bad":false,"notice":""},{"id":"w32","major":"词汇与综合","minor":"病句类型","question":"“今天，在纪念毛泽东同志‘向雷锋同志学习’题词发表周年之际，推荐广大青年读一读《雷锋日记》这本好书。”这句话的主要语病是（ ）。","options":[{"key":"A","text":"成分残缺"},{"key":"B","text":"主谓搭配不当"},{"key":"C","text":"虚词误用"},{"key":"D","text":"比喻不当"}],"answer":"A","explanation":"介词结构“在……之际”不能充当主语，后面的“推荐”缺少施事主语。可在“推荐”前补上“我们”。","source":"word #32","bad":false,"notice":""},{"id":"w33","major":"词汇与综合","minor":"病句修改","question":"原句：“不断改善并切实保障民生，才能真正保持社会的和谐与稳定，进一步提高国民的幸福指数，实现长治久安的目标。”下列修改最恰当的一项是（ ）。","options":[{"key":"A","text":"切实保障并不断改善民生，进一步提高国民的幸福指数，才能真正保持社会的和谐与稳定，实现长治久安的目标。"},{"key":"B","text":"不断改善并切实保障民生，才能进一步保持社会和谐，真正提高稳定指数。"},{"key":"C","text":"切实保障民生并改善，才能保持和提高社会和谐与国民幸福。"},{"key":"D","text":"不断保障并切实改善民生，实现社会稳定以后提高国民幸福指数。"}],"answer":"A","explanation":"应先“保障”再“改善”民生；“提高幸福指数”是保持社会和谐稳定的条件之一，应置于“才能”之前。A项语序和搭配均恰当。","source":"word #33","bad":false,"notice":""},{"id":"w34","major":"词汇与综合","minor":"歧义辨析","question":"下面四句话中，有歧义的一句是（ ）。","options":[{"key":"A","text":"各地根据实际情况，把几大块内容组合在一起。"},{"key":"B","text":"据报道，今年许多应届大学毕业生参加了研究生入学考试。"},{"key":"C","text":"满面春风的关大爷的儿子，兴冲冲地走了进来。"},{"key":"D","text":"接受教育是每个公民的权利，也是每个公民的义务。"}],"answer":"C","explanation":"“满面春风”既可能修饰“关大爷”，也可能修饰“关大爷的儿子”，修饰对象不明确。","source":"word #34","bad":false,"notice":""},{"id":"w35","major":"词汇与综合","minor":"歧义辨析","question":"下列句子中，有歧义的一句是（ ）。","options":[{"key":"A","text":"接受教育是每个公民的权利，也是每个公民的义务。"},{"key":"B","text":"本市火车站的客流量，平均每天都在5万人以上。"},{"key":"C","text":"解放军指战员日夜奋战，终于筑好了防洪大坝。"},{"key":"D","text":"小兰哭了很久，终于感到累了，便趴在桌子上睡着了。"}],"answer":"B","explanation":"“平均每天都在5万人以上”可理解为平均数超过5万人，也可理解为每天的数量都超过5万人，统计口径含混。","source":"word #35","bad":false,"notice":""},{"id":"w36","major":"词汇与综合","minor":"歧义辨析","question":"下面四句话中，有歧义的一句是（ ）。","options":[{"key":"A","text":"夜晚的天空总使人看不厌。"},{"key":"B","text":"她从书架上取下那本书递给我。"},{"key":"C","text":"今年全县粮食总产量超过历史最高水平两万吨。"},{"key":"D","text":"那是一条农民自发修筑的路。"}],"answer":"C","explanation":"“超过历史最高水平两万吨”既可理解为“比历史最高水平多两万吨”，也可被误解为“历史最高水平是两万吨”。应改为“比历史最高水平多两万吨”。","source":"word #36","bad":false,"notice":""},{"id":"w37","major":"词汇与综合","minor":"语句排序","question":"将下列句子重新排列，语序正确的一项是（ ）。①地理环境的各个要素不是孤立存在和发展的。②每个要素的发展变化都会影响整个地理环境。③地理环境各要素之间存在相互配合、相互影响、相互渗透、相互制约的依存关系。④一个环节紧扣另一个环节，一个过程向另一个过程转化。⑤并直接或间接地影响人类的生存和发展。⑥最后必然导致整个地理环境由量变发展到质变。","options":[{"key":"A","text":"①③②④⑤⑥"},{"key":"B","text":"③①②⑥⑤④"},{"key":"C","text":"③①②④⑤⑥"},{"key":"D","text":"①②④⑥⑤③"}],"answer":"A","explanation":"①先提出总观点；③解释各要素的依存关系；②承接说明要素变化的影响；④、⑤写影响传导过程；⑥以结果收束。","source":"word #37","bad":false,"notice":""},{"id":"w38","major":"词汇与综合","minor":"语言理解","question":"海明威的作品表现人在困境中不可被打败的尊严，福克纳则提醒人们记住勇气、荣誉、希望、同情、怜悯和牺牲精神。人在遭受苦难、陷入迷惘时，只有具有这种精神力量的作家，才能给人们以鼓舞。下列理解正确的一项是（ ）。","options":[{"key":"A","text":"两位作家的作品都集中展现人在苦难面前的迷惘。"},{"key":"B","text":"两位作家的作品都只表达了乐观主义主题。"},{"key":"C","text":"两位作家都过分夸大了人的精神力量。"},{"key":"D","text":"两位作家都强调文学作品应当振奋人心、给人以精神力量。"}],"answer":"D","explanation":"文段共同强调文学在苦难中给予人勇气和精神支撑。D项概括准确；A、B缩小或偏离文意，C属于无依据评价。","source":"word #38","bad":false,"notice":""},{"id":"w39","major":"词汇与综合","minor":"语言理解","question":"我国科普工作虽有进步，但科普读物的数量和质量与发达国家仍有差距。在一些社会关注的重大问题上，科学家更应主动站出来，把科学语言转化为公众听得懂的语言，实事求是地讲真话。否则，真相缺失、谣言扩散，可能引起公众恐慌和困惑。文段意在强调（ ）。","options":[{"key":"A","text":"科普读物都应当通俗化。"},{"key":"B","text":"我国科普读物数量少、质量差。"},{"key":"C","text":"科学家应主动承担科普责任，求真务实地发声。"},{"key":"D","text":"公众应提高辨别谣言的能力。"}],"answer":"C","explanation":"文段先交代背景，随后以“科学家更应该”提出中心观点，末句说明不发声的后果。C项最全面。","source":"word #39","bad":false,"notice":""},{"id":"w40","major":"词汇与综合","minor":"语言理解","question":"近年来，家委会成为许多学校的标配，发挥着促进家校沟通的作用，但也出现家长拼背景、比资源、违规收费等问题。这些问题背离了家委会设置的初衷，也在一定程度上加剧了教育不公平。文段意在强调（ ）。","options":[{"key":"A","text":"应当给家委会正名"},{"key":"B","text":"家委会不是学校的标配"},{"key":"C","text":"家委会应回归角色本位"},{"key":"D","text":"家委会应完全退出学校管理"}],"answer":"C","explanation":"文段肯定家委会的沟通作用，同时指出其偏离初衷的问题，落点是使其回归应有职能。","source":"word #40","bad":false,"notice":""},{"id":"w41","major":"词汇与综合","minor":"语言理解","question":"在生产力不发达的时代，战争是争夺资源的重要方式。青年是战争中最重要的参与者，要赢得战争，青年必须具有强健体魄；人口越多，青年比重越高，城邦越能在竞争中居于优势。文段强调的是（ ）。","options":[{"key":"A","text":"青年在城邦竞争中起着重要作用"},{"key":"B","text":"获取资源只能依靠战争"},{"key":"C","text":"人口多寡是衡量城市发展的唯一指标"},{"key":"D","text":"竞争主要依赖人的身体素质"}],"answer":"A","explanation":"文段围绕青年作为战争参与者及其对城邦竞争力的影响展开。B、C、D都把文意绝对化或片面化。","source":"word #41","bad":false,"notice":""},{"id":"w42","major":"词汇与综合","minor":"语言理解","question":"对微生物进行科学研究时，显微镜只适合观察；如果进行生化分析，琼脂更重要。细菌可在琼脂表面形成肉眼可见的菌群，琼脂的半固态性质能固定细菌位置，从而便于克隆、培养并进行生化分析。这段文字主要说明（ ）。","options":[{"key":"A","text":"显微镜在微生物研究中的作用有限"},{"key":"B","text":"琼脂在微生物生化分析中发挥重要作用"},{"key":"C","text":"克隆技术使所有生化分析都更容易"},{"key":"D","text":"微生物实验室最常用的工具是显微镜"}],"answer":"B","explanation":"文段通过对比显微镜和琼脂，重点解释琼脂如何帮助培养细菌并服务于生化分析，B项最准确。","source":"word #42","bad":false,"notice":""},{"id":"w43","major":"词汇与综合","minor":"语言理解","question":"19世纪以前，人类速度的提升主要依赖火车和轮船，仍受机械运动范围限制。电气设备出现后，信息传递不再受原有空间限制，空间和时间的关系发生了决定性改变。文段意在说明（ ）。","options":[{"key":"A","text":"电气设备的诞生是近代科技革命的唯一标志"},{"key":"B","text":"科学技术的发展常常难以理解"},{"key":"C","text":"新型交通工具改变了人们的生活方式"},{"key":"D","text":"电给人类交流速度带来了根本性改变"}],"answer":"D","explanation":"转折后的“由于电的发现”是中心，强调电对空间、时间关系和交流速度的根本改变。","source":"word #43","bad":false,"notice":""},{"id":"w44","major":"词汇与综合","minor":"语言理解","question":"中小成本电影近年脱颖而出，但其辉煌并非完全是自身自然发展的结果。国产商业大片长期沿袭以华丽阵容、恢弘气势和视觉冲击为主的模式，观众逐渐产生审美疲劳，因而需要质朴、清新、接地气的中小成本电影作为“差异化补偿”。文段意在说明（ ）。","options":[{"key":"A","text":"中小成本电影发展潜力无限"},{"key":"B","text":"中小成本电影脱颖而出并非全是自身之功"},{"key":"C","text":"国产商业大片已经没有观众"},{"key":"D","text":"中小成本电影已经成为市场唯一主流"}],"answer":"B","explanation":"首句提出观点，后文说明商业大片造成的审美疲劳为中小成本电影提供了外部机会。B项与中心一致。","source":"word #44","bad":false,"notice":""},{"id":"w45","major":"词汇与综合","minor":"语言理解","question":"现代社会中，很多人虽重视健康，却仍沿用陈旧的健康观念，忽视“亚健康”是从健康向疾病转变的危险阶段。等疾病发生后再治疗，往往为时已晚。文段的中心观点是（ ）。","options":[{"key":"A","text":"应抽出时间调理，杜绝一切危险"},{"key":"B","text":"亚健康一定会发展成疾病"},{"key":"C","text":"应更新健康观念，重视预防和亚健康管理"},{"key":"D","text":"只要提高体检频率就能防患未然"}],"answer":"C","explanation":"文段批评“生病后再治疗”的陈旧观念，强调关注亚健康和预防。A、B、D均表述绝对或片面。","source":"word #45","bad":false,"notice":""},{"id":"w46","major":"词汇与综合","minor":"语言理解","question":"软科学的研究对象涉及经济、管理、社会等复杂领域。随着社会系统日益复杂，决策对综合知识和系统分析的需求不断增加，软科学将在广泛领域发挥越来越重要的作用。文段主要强调（ ）。","options":[{"key":"A","text":"人们对软科学的认识不断提高"},{"key":"B","text":"软科学当前发展速度非常快"},{"key":"C","text":"软科学发展的原因和前景"},{"key":"D","text":"人们重视软科学的单一原因"}],"answer":"C","explanation":"文段既说明社会复杂化和决策需求是软科学发展的原因，也指出其未来作用，C项概括最全面。","source":"word #46","bad":false,"notice":""},{"id":"w47","major":"词汇与综合","minor":"语言理解","question":"大学研究固然应为经济发展作出贡献，大学教育也应帮助学生从事有益而令人满意的工作。然而，最好的教育还有无法用金钱衡量的方面：它使人更有创造性、更善于深思熟虑，更有理想和洞察力。对“最好的教育”理解最恰当的一项是（ ）。","options":[{"key":"A","text":"只为经济发展服务的教育"},{"key":"B","text":"只帮助学生获得工作的教育"},{"key":"C","text":"只重视专业技能的教育"},{"key":"D","text":"兼顾职业能力与人的完整发展的教育"}],"answer":"D","explanation":"文段先承认经济和职业功能，随后用“然而”强调人格、思考和创造力的发展，因此应理解为二者兼顾。","source":"word #47","bad":false,"notice":""},{"id":"w48","major":"词汇与综合","minor":"语境填空","question":"一个拥有工匠精神的国家和民族，必然会少一些浮躁，多一些纯粹；少一些投机取巧，多一些____；少一些____，多一些专注持久；少一些____，多一些优品精品。依次填入最恰当的一项是（ ）。","options":[{"key":"A","text":"实事求是 好高骛远 偷工减料"},{"key":"B","text":"兢兢业业 口是心非 花里胡哨"},{"key":"C","text":"稳扎稳打 杀鸡取卵 敷衍了事"},{"key":"D","text":"脚踏实地 急功近利 粗制滥造"}],"answer":"D","explanation":"三组都要求与后面的积极品质形成反向对照：“投机取巧—脚踏实地”“急功近利—专注持久”“粗制滥造—优品精品”。","source":"word #48","bad":false,"notice":""},{"id":"w49","major":"词汇与综合","minor":"文化常识","question":"《资治通鉴》书名的含义是（ ）。","options":[{"key":"A","text":"鉴于往事，有资于治道"},{"key":"B","text":"记录天下奇闻，以供娱乐"},{"key":"C","text":"汇集历代诗文，以资鉴赏"},{"key":"D","text":"研究兵法谋略，以助征战"}],"answer":"A","explanation":"“资治”意为帮助治理，“通鉴”意为贯通古今、作为借鉴。书名通常解释为“鉴于往事，有资于治道”。","source":"word #49","bad":false,"notice":""},{"id":"w50","major":"词汇与综合","minor":"法律常识","question":"有关规定要求其他车辆对使用特种音响警报器和红色回转警灯的特种车辆予以避让。这主要体现了行政职权的（ ）。","options":[{"key":"A","text":"优益性"},{"key":"B","text":"单方性"},{"key":"C","text":"强制性"},{"key":"D","text":"执行性"}],"answer":"A","explanation":"行政优益权是国家为保障行政主体有效行使职权而赋予的职务优先条件。特种车辆执行公务时享有道路优先，体现行政职权的优益性。","source":"word #50","bad":false,"notice":""},{"id":"w51","major":"词汇与综合","minor":"语言文字法规","question":"下列情形中，可以依法保留或使用繁体字、异体字的是（ ）。","options":[{"key":"A","text":"姓氏中的异体字"},{"key":"B","text":"机关公文"},{"key":"C","text":"企业名称的普通用字"},{"key":"D","text":"面向社会的广告用字"}],"answer":"A","explanation":"国家通用语言文字法允许姓氏中的异体字等法定特殊情形保留使用；机关公文、企业普通名称和广告原则上应使用规范汉字。","source":"word #51","bad":false,"notice":""},{"id":"w52","major":"词汇与综合","minor":"科学常识","question":"在一个与外界没有热交换的密闭房间内打开冰箱门，并让冰箱持续正常工作。一段时间后，房间内的平均温度将（ ）。","options":[{"key":"A","text":"升高"},{"key":"B","text":"降低"},{"key":"C","text":"不变"},{"key":"D","text":"先降低后保持不变"}],"answer":"A","explanation":"冰箱把箱内热量转移到室内，同时压缩机消耗的电能最终也转化为热量。房间总体得到额外热量，因此平均温度升高。","source":"word #52","bad":false,"notice":""},{"id":"w53","major":"词汇与综合","minor":"哲学常识","question":"“众人皆知利利而病病也，唯圣人知病之为利，利之为病也。”这句话主要说明利与弊之间存在（ ）。","options":[{"key":"A","text":"绝对同一关系"},{"key":"B","text":"在一定条件下相互转化的关系"},{"key":"C","text":"彼此排斥、永不联系的关系"},{"key":"D","text":"由主观意志任意决定的关系"}],"answer":"B","explanation":"材料指出利可能成为害、害也可能转化为利，强调矛盾双方在一定条件下可以相互转化。","source":"word #53","bad":false,"notice":""},{"id":"w54","major":"词汇与综合","minor":"科学常识","question":"生态系统不断与外界进行物质、能量和信息交换，因此生态系统是一个（ ）。","options":[{"key":"A","text":"完全封闭的系统"},{"key":"B","text":"开放的系统"},{"key":"C","text":"静止不变的系统"},{"key":"D","text":"与环境无关的系统"}],"answer":"B","explanation":"能够同外界持续进行物质、能量和信息交换的系统属于开放系统。","source":"word #54","bad":false,"notice":""},{"id":"w55","major":"词汇与综合","minor":"教育学","question":"推进义务教育改革和发展的战略性任务是（ ）。","options":[{"key":"A","text":"扩大考试规模"},{"key":"B","text":"均衡发展"},{"key":"C","text":"延长在校时间"},{"key":"D","text":"取消学校差异"}],"answer":"B","explanation":"义务教育的战略性任务是推进均衡发展，重点是合理配置资源、缩小区域和校际差距。","source":"word #55","bad":false,"notice":""},{"id":"w56","major":"词汇与综合","minor":"教育法规","question":"义务教育阶段学生因故不能按期入学，按资料所示一般请假不得超过（ ）。","options":[{"key":"A","text":"一周"},{"key":"B","text":"两周"},{"key":"C","text":"一个月"},{"key":"D","text":"一学期"}],"answer":"B","explanation":"资料给出的办理规则是一般请假不超过两周；超过规定期限通常需要按休学等程序另行办理。","source":"word #56","bad":false,"notice":""},{"id":"w57","major":"词汇与综合","minor":"教育学","question":"原始社会教育的突出特点是（ ）。","options":[{"key":"A","text":"具有鲜明的阶级性"},{"key":"B","text":"形成了完备的学校制度"},{"key":"C","text":"教育没有阶级性"},{"key":"D","text":"教育与生产劳动完全分离"}],"answer":"C","explanation":"原始社会尚未形成阶级和专门学校，教育没有阶级性，并与生产劳动和社会生活紧密结合。","source":"word #57","bad":false,"notice":""},{"id":"w58","major":"词汇与综合","minor":"教育学","question":"狭义的教育通常指（ ）。","options":[{"key":"A","text":"家庭教育"},{"key":"B","text":"学校教育"},{"key":"C","text":"社会教育"},{"key":"D","text":"自我教育"}],"answer":"B","explanation":"狭义教育是有目的、有计划、有组织地影响受教育者的学校教育。","source":"word #58","bad":false,"notice":""},{"id":"w59","major":"词汇与综合","minor":"教育学","question":"课外、校外教育与课堂教学的共同之处是二者都具有（ ）。","options":[{"key":"A","text":"自发性和随机性"},{"key":"B","text":"目的性、计划性和组织性"},{"key":"C","text":"强制性和封闭性"},{"key":"D","text":"娱乐性和随意性"}],"answer":"B","explanation":"二者都是学校教育体系中的有意识教育活动，均有明确目的，并按一定计划和组织实施。","source":"word #59","bad":false,"notice":""},{"id":"w60","major":"词汇与综合","minor":"教育研究","question":"下列关于教育实验研究特点的表述，正确的一组是（ ）。","options":[{"key":"A","text":"可控制条件、检验假设并揭示变量关系"},{"key":"B","text":"只能自然观察，不能控制变量"},{"key":"C","text":"不需要研究假设，也不能重复验证"},{"key":"D","text":"只适合描述现象，不能解释因果"}],"answer":"A","explanation":"教育实验以假设为先导，通过控制条件考察变量关系，并可在一定条件下重复验证。","source":"word #60","bad":false,"notice":""},{"id":"w61","major":"词汇与综合","minor":"心理学","question":"同时写字、听讲并注意课堂变化，主要体现了注意的（ ）。","options":[{"key":"A","text":"稳定性"},{"key":"B","text":"分配"},{"key":"C","text":"转移"},{"key":"D","text":"广度"}],"answer":"B","explanation":"注意的分配是人在同一时间内把注意指向两种或两种以上活动的能力，俗称“一心二用”。","source":"word #61","bad":false,"notice":""},{"id":"w62","major":"词汇与综合","minor":"教育学","question":"教育活动必须遵循的两条基本规律是（ ）。","options":[{"key":"A","text":"教育与人口、教育与考试的关系"},{"key":"B","text":"教育与社会发展、教育与人的身心发展的关系"},{"key":"C","text":"教育与教材、教育与作业的关系"},{"key":"D","text":"教育与教师、教育与校舍的关系"}],"answer":"B","explanation":"教育一方面受社会政治、经济、文化等制约并反作用于社会，另一方面受人的身心发展规律制约并促进人的发展。","source":"word #62","bad":false,"notice":""},{"id":"w63","major":"词汇与综合","minor":"教育研究","question":"教育调查常用的方法包括（ ）。","options":[{"key":"A","text":"观察、测验、问卷、查阅资料和谈话"},{"key":"B","text":"只做实验，不接触被调查者"},{"key":"C","text":"只查阅统计年鉴"},{"key":"D","text":"只使用课堂测验"}],"answer":"A","explanation":"教育调查可综合采用观察、测验、问卷、文献资料和访谈等方法收集信息。","source":"word #63","bad":false,"notice":""},{"id":"w64","major":"词汇与综合","minor":"教育研究","question":"与实验法相比，调查法较突出的优势是（ ）。","options":[{"key":"A","text":"能够完全控制变量"},{"key":"B","text":"适用范围较广、实施较灵活"},{"key":"C","text":"一定能证明因果关系"},{"key":"D","text":"不需要样本和资料"}],"answer":"B","explanation":"调查法便于在较大范围内收集现实资料，具有实用性和广泛性；但对变量控制和因果推断通常弱于实验法。","source":"word #64","bad":false,"notice":""},{"id":"w65","major":"词汇与综合","minor":"教育学","question":"赫尔巴特传统教育理论的“三中心”是（ ）。","options":[{"key":"A","text":"教师、课堂、书本"},{"key":"B","text":"学生、经验、活动"},{"key":"C","text":"问题、合作、探究"},{"key":"D","text":"生活、社会、劳动"}],"answer":"A","explanation":"传统教育的“三中心”通常概括为教师中心、课堂中心和书本中心。","source":"word #65","bad":false,"notice":""},{"id":"w66","major":"词汇与综合","minor":"教育法规","question":"我国义务教育的管理体制是（ ）。","options":[{"key":"A","text":"国务院领导，省级统筹规划实施，县级人民政府为主管理"},{"key":"B","text":"中央直接管理所有学校"},{"key":"C","text":"省级领导，乡镇为主管理"},{"key":"D","text":"学校自主决定、政府不参与"}],"answer":"A","explanation":"《义务教育法》规定，义务教育实行国务院领导，省、自治区、直辖市人民政府统筹规划实施，县级人民政府为主管理的体制。","source":"word #66","bad":false,"notice":""},{"id":"w67","major":"词汇与综合","minor":"教育学","question":"1970年，保罗·朗格朗在国际教育领域重点倡导的理念是（ ）。","options":[{"key":"A","text":"终身教育"},{"key":"B","text":"精英教育"},{"key":"C","text":"程序教学"},{"key":"D","text":"要素教育"}],"answer":"A","explanation":"保罗·朗格朗是终身教育思想的重要倡导者，其报告推动了终身教育理念的传播。","source":"word #67","bad":false,"notice":""},{"id":"w68","major":"词汇与综合","minor":"教育史","question":"西方最早专门论述教学方法、被视为早期系统教学法著作的是（ ）。","options":[{"key":"A","text":"《理想国》"},{"key":"B","text":"《雄辩术原理》"},{"key":"C","text":"《大教学论》"},{"key":"D","text":"《普通教育学》"}],"answer":"B","explanation":"古罗马昆体良的《雄辩术原理》（又译《论演说家的教育》）系统讨论了教育和教学问题。","source":"word #68","bad":false,"notice":""},{"id":"w69","major":"词汇与综合","minor":"教育史","question":"我国古代私学兴起于（ ）。","options":[{"key":"A","text":"夏朝"},{"key":"B","text":"春秋时期"},{"key":"C","text":"隋朝"},{"key":"D","text":"明朝"}],"answer":"B","explanation":"春秋时期社会变革、文化下移，私人讲学兴起，孔子私学具有代表性。","source":"word #69","bad":false,"notice":""},{"id":"w70","major":"词汇与综合","minor":"教育学","question":"家庭教育在时间上的主要特点是（ ）。","options":[{"key":"A","text":"开始最晚、持续最短"},{"key":"B","text":"开始最早、持续时间最长"},{"key":"C","text":"只发生在学龄前"},{"key":"D","text":"只发生在义务教育阶段"}],"answer":"B","explanation":"家庭是儿童最早接触的教育环境，家庭影响通常贯穿人的较长生命历程。","source":"word #70","bad":false,"notice":""},{"id":"w71","major":"词汇与综合","minor":"教育学","question":"学校体育与自发体育活动相比，一个显著特点是（ ）。","options":[{"key":"A","text":"随意性"},{"key":"B","text":"系统性"},{"key":"C","text":"娱乐性"},{"key":"D","text":"偶然性"}],"answer":"B","explanation":"学校体育依据培养目标和课程计划组织实施，具有明确目的、规范内容和系统过程。","source":"word #71","bad":false,"notice":""},{"id":"w72","major":"词汇与综合","minor":"教育法规","question":"制定《中华人民共和国义务教育法》的直接法律依据是（ ）。","options":[{"key":"A","text":"宪法和教育法"},{"key":"B","text":"刑法和民法"},{"key":"C","text":"教师法和劳动法"},{"key":"D","text":"未成年人保护法和行政处罚法"}],"answer":"A","explanation":"《义务教育法》依据宪法和教育法制定。","source":"word #72","bad":false,"notice":""},{"id":"w73","major":"词汇与综合","minor":"教育法规","question":"修订后的《中华人民共和国义务教育法》自（ ）起施行。","options":[{"key":"A","text":"1986年7月1日"},{"key":"B","text":"1995年9月1日"},{"key":"C","text":"2006年9月1日"},{"key":"D","text":"2017年10月1日"}],"answer":"C","explanation":"2006年修订的《义务教育法》自2006年9月1日起施行。","source":"word #73","bad":false,"notice":""},{"id":"w74","major":"词汇与综合","minor":"教育法规","question":"学校附近网吧违规接纳未成年人，未成年人的家人据以维护其权益的主要法律是（ ）。","options":[{"key":"A","text":"《中华人民共和国未成年人保护法》"},{"key":"B","text":"《中华人民共和国反家庭暴力法》"},{"key":"C","text":"《中华人民共和国义务教育法》"},{"key":"D","text":"《中华人民共和国公司法》"}],"answer":"A","explanation":"未成年人保护法对营业性娱乐场所、互联网上网服务营业场所保护未成年人的义务作出规定。","source":"word #74","bad":false,"notice":""},{"id":"w75","major":"词汇与综合","minor":"教育史","question":"夸美纽斯在《大教学论》中系统论述并推动的教育主张是（ ）。","options":[{"key":"A","text":"普及教育和班级授课制"},{"key":"B","text":"设计教学法和道尔顿制"},{"key":"C","text":"程序教学和掌握学习"},{"key":"D","text":"发现学习和结构课程"}],"answer":"A","explanation":"夸美纽斯系统论述普及教育、班级授课制等，被视为近代教育学的重要奠基者。","source":"word #75","bad":false,"notice":""},{"id":"w76","major":"词汇与综合","minor":"教师制度","question":"教师聘任合同通常约定的聘任期限为（ ）。","options":[{"key":"A","text":"一年以下"},{"key":"B","text":"三至五年"},{"key":"C","text":"十至十五年"},{"key":"D","text":"终身固定"}],"answer":"B","explanation":"资料中的教师聘任制度题给出的常见聘期为三至五年。","source":"word #76","bad":false,"notice":""},{"id":"w77","major":"词汇与综合","minor":"教育学","question":"杜威现代教育理论的“三中心”是（ ）。","options":[{"key":"A","text":"教师、教材、课堂"},{"key":"B","text":"儿童（学生）、经验、活动"},{"key":"C","text":"考试、分数、升学"},{"key":"D","text":"学校、家庭、社会"}],"answer":"B","explanation":"杜威反对传统教育的教师、课堂、书本中心，强调儿童、经验和活动。","source":"word #77","bad":false,"notice":""},{"id":"w78","major":"词汇与综合","minor":"教育学","question":"发现学习的主要倡导者是（ ）。","options":[{"key":"A","text":"赫尔巴特"},{"key":"B","text":"布鲁纳"},{"key":"C","text":"凯洛夫"},{"key":"D","text":"巴班斯基"}],"answer":"B","explanation":"布鲁纳强调学科基本结构和发现学习，主张学生通过主动探索形成知识结构。","source":"word #78","bad":false,"notice":""},{"id":"w79","major":"词汇与综合","minor":"德育","question":"德育过程的基本矛盾是（ ）。","options":[{"key":"A","text":"教师人数与学生人数之间的矛盾"},{"key":"B","text":"社会提出的道德要求与学生已有品德水平之间的矛盾"},{"key":"C","text":"教材篇幅与课时之间的矛盾"},{"key":"D","text":"学校教育与家庭作业之间的矛盾"}],"answer":"B","explanation":"德育旨在把社会道德要求转化为学生品德，二者之间的差距构成德育过程的基本矛盾。","source":"word #79","bad":false,"notice":""},{"id":"w80","major":"词汇与综合","minor":"学生权利","question":"学校公开公布学生成绩和名次，可能直接侵犯学生的（ ）。","options":[{"key":"A","text":"受教育权"},{"key":"B","text":"隐私权"},{"key":"C","text":"财产权"},{"key":"D","text":"通信自由"}],"answer":"B","explanation":"学生成绩属于与个人学习状况密切相关的信息，未经合理授权公开排名可能侵犯学生隐私和人格尊严。","source":"word #80","bad":false,"notice":""},{"id":"w81","major":"词汇与综合","minor":"教育史","question":"世界上较早以马克思主义观点系统编写、并产生广泛影响的教育学著作是（ ）。","options":[{"key":"A","text":"凯洛夫主编的《教育学》"},{"key":"B","text":"赫尔巴特的《普通教育学》"},{"key":"C","text":"杜威的《民主主义与教育》"},{"key":"D","text":"斯宾塞的《教育论》"}],"answer":"A","explanation":"凯洛夫主编的《教育学》以马克思主义为指导，在苏联及中国教育界曾产生广泛影响。","source":"word #81","bad":false,"notice":""},{"id":"w82","major":"词汇与综合","minor":"教育史","question":"我国第一部以马克思主义观点系统论述教育问题的著作是（ ）。","options":[{"key":"A","text":"杨贤江的《新教育大纲》"},{"key":"B","text":"蔡元培的《对于教育方针之意见》"},{"key":"C","text":"陶行知的《中国教育改造》"},{"key":"D","text":"陈鹤琴的《家庭教育》"}],"answer":"A","explanation":"杨贤江的《新教育大纲》被普遍视为我国第一部运用马克思主义观点系统论述教育问题的著作。","source":"word #82","bad":false,"notice":""},{"id":"w83","major":"词汇与综合","minor":"教学原则","question":"教师根据学生的个别差异和发展水平采取不同教学要求，体现了（ ）。","options":[{"key":"A","text":"量力性与因材施教原则"},{"key":"B","text":"理论联系实际原则"},{"key":"C","text":"巩固性原则"},{"key":"D","text":"直观性原则"}],"answer":"A","explanation":"针对学生的能力、兴趣、基础和发展差异实施有区别的教学，体现因材施教。","source":"word #83","bad":false,"notice":""},{"id":"w84","major":"词汇与综合","minor":"教育学","question":"在全面发展教育中，培养学生感受美、鉴赏美和创造美能力的是（ ）。","options":[{"key":"A","text":"德育"},{"key":"B","text":"智育"},{"key":"C","text":"美育"},{"key":"D","text":"劳动技术教育"}],"answer":"C","explanation":"美育以培养正确审美观点以及感受美、鉴赏美和创造美的能力为主要任务。","source":"word #84","bad":false,"notice":""},{"id":"w85","major":"词汇与综合","minor":"未成年人保护","question":"互联网上网服务营业场所一般不得设在中小学校园周边（ ）范围内。","options":[{"key":"A","text":"50米"},{"key":"B","text":"100米"},{"key":"C","text":"200米"},{"key":"D","text":"500米"}],"answer":"C","explanation":"资料中的法规题以200米为标准，目的在于保护未成年人并维护学校周边环境。","source":"word #85","bad":false,"notice":""},{"id":"w86","major":"词汇与综合","minor":"教师申诉","question":"教师认为学校侵犯其进修学习权利而提出申诉，通常应向（ ）提出。","options":[{"key":"A","text":"当地县级教育行政部门"},{"key":"B","text":"人民银行"},{"key":"C","text":"市场监管部门"},{"key":"D","text":"学校家长委员会"}],"answer":"A","explanation":"教师对学校或其他教育机构侵犯其合法权益的行为可依法提出申诉，受理机关一般为主管教育行政部门。","source":"word #86","bad":false,"notice":""},{"id":"w87","major":"词汇与综合","minor":"教育史","question":"以美国“六三三制”为主要蓝本制定的我国现代学制是（ ）。","options":[{"key":"A","text":"壬寅学制"},{"key":"B","text":"癸卯学制"},{"key":"C","text":"壬子癸丑学制"},{"key":"D","text":"壬戌学制"}],"answer":"D","explanation":"1922年颁布的壬戌学制又称“六三三学制”，主要参照美国学制。","source":"word #87","bad":false,"notice":""},{"id":"w88","major":"词汇与综合","minor":"教育史","question":"我国第一个正式实施的现代学制是（ ）。","options":[{"key":"A","text":"壬寅学制"},{"key":"B","text":"癸卯学制"},{"key":"C","text":"壬子癸丑学制"},{"key":"D","text":"壬戌学制"}],"answer":"B","explanation":"壬寅学制是首次颁布但未实施；癸卯学制是我国第一个正式实施的现代学制。","source":"word #88","bad":false,"notice":""},{"id":"w89","major":"词汇与综合","minor":"儿童心理","question":"儿童能够比较稳定地区分自身左右方向，一般约在（ ）。","options":[{"key":"A","text":"3岁"},{"key":"B","text":"4岁"},{"key":"C","text":"5岁"},{"key":"D","text":"8岁"}],"answer":"C","explanation":"资料题所对应的儿童方位知觉发展节点为5岁左右能够辨别自身左右。","source":"word #89","bad":false,"notice":""},{"id":"w90","major":"词汇与综合","minor":"教师职业","question":"从历史时间看，教师成为一种社会职业与专门师范教育出现的先后关系是（ ）。","options":[{"key":"A","text":"教师职业早于专门师范教育"},{"key":"B","text":"二者同时出现"},{"key":"C","text":"师范教育早于教师职业"},{"key":"D","text":"无法比较"}],"answer":"A","explanation":"教育活动和教师职业早已存在，近代专门师范学校是在教师职业专业化过程中才出现的。","source":"word #90","bad":false,"notice":""},{"id":"w91","major":"词汇与综合","minor":"教育学","question":"赫尔巴特教育理论体系主要包括（ ）。","options":[{"key":"A","text":"儿童管理、教学和道德教育"},{"key":"B","text":"生产劳动、体育和军事训练"},{"key":"C","text":"课程开发、学校建筑和教育财政"},{"key":"D","text":"家庭教育、社区服务和职业培训"}],"answer":"A","explanation":"赫尔巴特的教育理论通常从儿童管理、教学和道德教育三个方面展开。","source":"word #91","bad":false,"notice":""},{"id":"w92","major":"词汇与综合","minor":"德育","question":"关于品德形成中知、情、意、行的关系，下列说法正确的是（ ）。","options":[{"key":"A","text":"必须从知开始并严格按固定顺序进行"},{"key":"B","text":"必须从行开始"},{"key":"C","text":"必须从情开始"},{"key":"D","text":"可根据具体情况从不同要素切入，几方面相互促进"}],"answer":"D","explanation":"知、情、意、行相互联系，德育可根据学生特点和具体问题选择不同开端，不宜机械规定唯一顺序。","source":"word #92","bad":false,"notice":""},{"id":"w93","major":"词汇与综合","minor":"教学论","question":"“范例教学”理论的主要代表人物是（ ）。","options":[{"key":"A","text":"瓦根舍因"},{"key":"B","text":"布卢姆"},{"key":"C","text":"布鲁纳"},{"key":"D","text":"赞科夫"}],"answer":"A","explanation":"德国教育家瓦根舍因是范例教学理论的重要代表。","source":"word #93","bad":false,"notice":""},{"id":"w94","major":"词汇与综合","minor":"教育研究","question":"实验教育学的重要代表人物之一是（ ）。","options":[{"key":"A","text":"梅伊曼"},{"key":"B","text":"赫尔巴特"},{"key":"C","text":"杜威"},{"key":"D","text":"孔子"}],"answer":"A","explanation":"梅伊曼和拉伊是实验教育学的代表人物，强调运用实验方法研究教育问题。","source":"word #94","bad":false,"notice":""},{"id":"w95","major":"词汇与综合","minor":"教育史","question":"柏拉图集中论述教育思想的代表作是（ ）。","options":[{"key":"A","text":"《理想国》"},{"key":"B","text":"《大教学论》"},{"key":"C","text":"《爱弥儿》"},{"key":"D","text":"《教育漫话》"}],"answer":"A","explanation":"柏拉图在《理想国》中系统讨论国家、社会分工和教育培养等问题。","source":"word #95","bad":false,"notice":""},{"id":"w96","major":"词汇与综合","minor":"学校管理","question":"民办学校的重大事项一般由（ ）依法决策。","options":[{"key":"A","text":"校长个人"},{"key":"B","text":"学校理事会、董事会或其他形式的决策机构"},{"key":"C","text":"任课教师轮流"},{"key":"D","text":"学生会"}],"answer":"B","explanation":"民办学校依法设立理事会、董事会或其他决策机构，校长负责教育教学和行政管理的日常执行。","source":"word #96","bad":false,"notice":""},{"id":"w97","major":"词汇与综合","minor":"学校管理","question":"民办学校日常教育教学和行政管理的主要负责人是（ ）。","options":[{"key":"A","text":"校长"},{"key":"B","text":"学生会主席"},{"key":"C","text":"家长委员会主任"},{"key":"D","text":"当地媒体负责人"}],"answer":"A","explanation":"校长依法负责学校的教育教学和行政管理工作。","source":"word #97","bad":false,"notice":""},{"id":"w98","major":"词汇与综合","minor":"教育研究","question":"教师和研究者针对实际教育问题开展合作研究，在行动中改进实践，这种方法是（ ）。","options":[{"key":"A","text":"行动研究法"},{"key":"B","text":"历史研究法"},{"key":"C","text":"纯理论演绎法"},{"key":"D","text":"文献计量法"}],"answer":"A","explanation":"行动研究以解决真实教育情境中的实际问题为目的，强调研究与改进行动相结合。","source":"word #98","bad":false,"notice":""},{"id":"w99","major":"词汇与综合","minor":"学校事故","question":"教师私自组织学生参加有偿课外辅导并提供食品，学生发生食物中毒。对该违法违规活动负主要责任的是（ ）。","options":[{"key":"A","text":"组织活动的教师"},{"key":"B","text":"其他未参加的教师"},{"key":"C","text":"学生家长"},{"key":"D","text":"学生本人"}],"answer":"A","explanation":"该活动由教师私自组织并实施，教师负有组织管理和安全保障义务，应对其过错承担相应责任。","source":"word #99","bad":false,"notice":""},{"id":"w100","major":"词汇与综合","minor":"教育史","question":"普及义务教育最早兴起于（ ）。","options":[{"key":"A","text":"原始社会"},{"key":"B","text":"奴隶社会"},{"key":"C","text":"资本主义社会"},{"key":"D","text":"未来社会"}],"answer":"C","explanation":"近代资本主义大工业发展需要具有基本文化知识的劳动者，国家普及义务教育由此逐步兴起。","source":"word #100","bad":false,"notice":""},{"id":"w101","major":"词汇与综合","minor":"教育目的","question":"确定教育目的的客观基础主要是（ ）。","options":[{"key":"A","text":"个人兴趣"},{"key":"B","text":"生产力和科学技术发展水平以及社会制度需要"},{"key":"C","text":"教师个人偏好"},{"key":"D","text":"教材篇幅"}],"answer":"B","explanation":"教育目的受社会生产力、政治经济制度和文化发展制约，同时要考虑人的身心发展规律。","source":"word #101","bad":false,"notice":""},{"id":"w102","major":"词汇与综合","minor":"教育目的","question":"衡量和评价教育实施效果的根本标准是（ ）。","options":[{"key":"A","text":"考试次数"},{"key":"B","text":"教育目的"},{"key":"C","text":"校舍面积"},{"key":"D","text":"作业数量"}],"answer":"B","explanation":"教育目的规定人才培养的总方向，是评价教育活动是否达到预期要求的根本标准。","source":"word #102","bad":false,"notice":""},{"id":"w103","major":"词汇与综合","minor":"素质教育","question":"现代教育与传统教育的重要区别之一，是现代教育更加重视培养学生的（ ）。","options":[{"key":"A","text":"机械记忆能力"},{"key":"B","text":"创新精神和实践能力"},{"key":"C","text":"服从意识"},{"key":"D","text":"重复训练速度"}],"answer":"B","explanation":"素质教育以培养创新精神和实践能力为重点，强调主动发展与综合素质。","source":"word #103","bad":false,"notice":""},{"id":"w104","major":"词汇与综合","minor":"素质教育","question":"素质教育的重点是培养学生的（ ）。","options":[{"key":"A","text":"应试技巧"},{"key":"B","text":"创新精神和实践能力"},{"key":"C","text":"单一学科分数"},{"key":"D","text":"机械模仿能力"}],"answer":"B","explanation":"创新精神和实践能力是素质教育的重点和鲜明特征。","source":"word #104","bad":false,"notice":""},{"id":"w105","major":"词汇与综合","minor":"教学论","question":"教学的根本目的在于（ ）。","options":[{"key":"A","text":"完成教材页数"},{"key":"B","text":"促进学生全面发展"},{"key":"C","text":"提高作业数量"},{"key":"D","text":"维持课堂安静"}],"answer":"B","explanation":"教学通过引导学生掌握知识技能、发展能力、形成品德，最终促进学生全面发展。","source":"word #105","bad":false,"notice":""},{"id":"w106","major":"词汇与综合","minor":"班主任工作","question":"做好班主任工作的前提和基础是（ ）。","options":[{"key":"A","text":"了解和研究学生"},{"key":"B","text":"增加考试次数"},{"key":"C","text":"统一学生个性"},{"key":"D","text":"只依靠班干部"}],"answer":"A","explanation":"只有全面了解学生的思想、学习、生活和个性特点，班主任才能有针对性地开展工作。","source":"word #106","bad":false,"notice":""},{"id":"w107","major":"词汇与综合","minor":"公民权利","question":"我国公民对受教育的法律地位是（ ）。","options":[{"key":"A","text":"只有权利，没有义务"},{"key":"B","text":"只有义务，没有权利"},{"key":"C","text":"既是权利，也是义务"},{"key":"D","text":"完全由家庭自行决定"}],"answer":"C","explanation":"宪法规定，中华人民共和国公民有受教育的权利和义务。","source":"word #107","bad":false,"notice":""},{"id":"w108","major":"词汇与综合","minor":"教育方针","question":"我国教育应当与（ ）相结合。","options":[{"key":"A","text":"生产劳动和社会实践"},{"key":"B","text":"商业广告"},{"key":"C","text":"娱乐竞赛"},{"key":"D","text":"个人消费"}],"answer":"A","explanation":"教育与生产劳动和社会实践相结合，是我国教育方针的重要内容。","source":"word #108","bad":false,"notice":""},{"id":"w109","major":"词汇与综合","minor":"义务教育","question":"我国现行义务教育年限为（ ）。","options":[{"key":"A","text":"六年"},{"key":"B","text":"八年"},{"key":"C","text":"九年"},{"key":"D","text":"十二年"}],"answer":"C","explanation":"我国实行九年义务教育制度。","source":"word #109","bad":false,"notice":""},{"id":"w110","major":"词汇与综合","minor":"教育法规","question":"教育活动（ ）符合国家和社会公共利益。","options":[{"key":"A","text":"应当"},{"key":"B","text":"必须"},{"key":"C","text":"可以"},{"key":"D","text":"偶尔"}],"answer":"B","explanation":"《教育法》强调教育活动必须符合国家和社会公共利益。","source":"word #110","bad":false,"notice":""},{"id":"w111","major":"词汇与综合","minor":"监护责任","question":"未成年人的父母或者其他监护人（ ）为其未成年子女或者其他被监护人受教育提供必要条件。","options":[{"key":"A","text":"应当"},{"key":"B","text":"可以"},{"key":"C","text":"无须"},{"key":"D","text":"仅在学校要求时"}],"answer":"A","explanation":"保障未成年人受教育是父母或其他监护人的法定义务，应当提供必要条件。","source":"word #111","bad":false,"notice":""},{"id":"w112","major":"词汇与综合","minor":"教育法规","question":"学校不履行法律法规规定的义务，情节严重或者造成严重后果时，依法承担相应法律责任的主体包括（ ）。","options":[{"key":"A","text":"仅校长"},{"key":"B","text":"学校负责人和有关直接责任人员"},{"key":"C","text":"仅学生"},{"key":"D","text":"仅家长"}],"answer":"B","explanation":"除学校承担相应责任外，对负有管理和直接责任的人员也可依法追究责任。","source":"word #112","bad":false,"notice":""},{"id":"w113","major":"词汇与综合","minor":"教育考试","question":"国家教育考试的种类由（ ）确定，并由国家批准的实施教育考试的机构承办。","options":[{"key":"A","text":"国务院教育行政部门"},{"key":"B","text":"任意学校"},{"key":"C","text":"地方行业协会"},{"key":"D","text":"考试培训机构"}],"answer":"A","explanation":"国家教育考试属于国家教育管理事项，由国务院教育行政部门依法确定种类。","source":"word #113","bad":false,"notice":""},{"id":"w114","major":"词汇与综合","minor":"教育法规","question":"明知校舍或者教育教学设施有危险而不采取措施，造成人员伤亡或者重大财产损失的，对直接负责人员依法追究（ ）。","options":[{"key":"A","text":"民事责任"},{"key":"B","text":"刑事责任"},{"key":"C","text":"一般责任"},{"key":"D","text":"道德责任"}],"answer":"B","explanation":"危害达到造成伤亡或重大财产损失的严重程度时，法律规定对直接负责人员依法追究刑事责任。","source":"word #114","bad":false,"notice":""},{"id":"w115","major":"词汇与综合","minor":"教育法规","question":"侵犯教师、受教育者或者学校及其他教育机构的合法权益，造成损失、损害的，应当依法承担（ ）。","options":[{"key":"A","text":"民事责任"},{"key":"B","text":"行政许可责任"},{"key":"C","text":"学术责任"},{"key":"D","text":"考试责任"}],"answer":"A","explanation":"造成民事权益损害的，应依法承担停止侵害、赔偿损失等民事责任；若另有行政或刑事违法，还可能承担相应责任。","source":"word #115","bad":false,"notice":""},{"id":"w116","major":"词汇与综合","minor":"教育收费","question":"学校及其他教育机构违反国家规定向受教育者收取费用的，教育行政部门应当责令其（ ）。","options":[{"key":"A","text":"退还所收费用"},{"key":"B","text":"双倍收费"},{"key":"C","text":"转为捐款"},{"key":"D","text":"自行保留"}],"answer":"A","explanation":"对违法收取的费用，教育行政部门应责令退还，并可依法处分有关责任人员。","source":"word #116","bad":false,"notice":""},{"id":"w117","major":"词汇与综合","minor":"教育经费","question":"各级人民政府教育财政拨款的增长（ ）高于财政经常性收入的增长。","options":[{"key":"A","text":"应当"},{"key":"B","text":"可以"},{"key":"C","text":"无须"},{"key":"D","text":"不得"}],"answer":"A","explanation":"教育法规定教育财政拨款的增长应当高于财政经常性收入的增长，并保障生均教育费用等逐步增长。","source":"word #117","bad":false,"notice":""},{"id":"w118","major":"词汇与综合","minor":"诉讼法","question":"被告人一方上诉，二审法院认为原判事实清楚、证据确凿但量刑畸轻。依照“上诉不加刑”原则，适当的处理是（ ）。","options":[{"key":"A","text":"直接加重刑罚"},{"key":"B","text":"为平衡而减轻刑罚"},{"key":"C","text":"不得因被告人一方上诉而加重，可依法维持原判"},{"key":"D","text":"追究一审法官刑事责任"}],"answer":"C","explanation":"仅由被告人一方提出上诉的案件，二审不得加重刑罚。题设没有检察机关抗诉等例外信息，因此不能直接加刑。","source":"word #118","bad":false,"notice":""},{"id":"w119","major":"词汇与综合","minor":"教育法","question":"国家在受教育者中进行的核心价值教育包括（ ）。","options":[{"key":"A","text":"个人主义、功利主义、消费主义"},{"key":"B","text":"爱国主义、集体主义、社会主义"},{"key":"C","text":"自由主义、无政府主义、享乐主义"},{"key":"D","text":"技术主义、实用主义、形式主义"}],"answer":"B","explanation":"《教育法》规定国家在受教育者中进行爱国主义、集体主义、社会主义教育，并开展理想、道德、纪律、法治等教育。","source":"word #119","bad":false,"notice":""},{"id":"w120","major":"词汇与综合","minor":"劳动与未成年人保护","question":"《禁止使用童工规定》的制定依据包括（ ）。","options":[{"key":"A","text":"宪法、劳动法和未成年人保护法"},{"key":"B","text":"公司法和证券法"},{"key":"C","text":"刑事诉讼法和仲裁法"},{"key":"D","text":"商标法和专利法"}],"answer":"A","explanation":"该规定旨在保护未成年人身心健康、促进义务教育实施和维护其合法权益，制定依据包括宪法、劳动法和未成年人保护法。","source":"word #120","bad":false,"notice":""},{"id":"w121","major":"词汇与综合","minor":"教育法规","question":"教师将扰乱课堂秩序的学生赶出教室并罚做俯卧撑，造成学生受伤。下列判断正确的是（ ）。","options":[{"key":"A","text":"教师行为合理，学生自行负责"},{"key":"B","text":"教师侵犯学生受教育权和人身权，学校应依法处理"},{"key":"C","text":"只侵犯财产权"},{"key":"D","text":"只要学生先违纪，教师就不承担任何责任"}],"answer":"B","explanation":"维护课堂秩序应采用合法、适当的教育惩戒方式。剥夺上课机会并实施造成伤害的体罚，侵害学生受教育权和人身权。","source":"word #121","bad":false,"notice":""},{"id":"w122","major":"词汇与综合","minor":"学校纪律","question":"学校对高中阶段学生实施纪律处分时，可以采用的方式是（ ）。","options":[{"key":"A","text":"警告、记过等校纪处分"},{"key":"B","text":"送劳动教养"},{"key":"C","text":"实施体罚"},{"key":"D","text":"随意没收个人合法财物"}],"answer":"A","explanation":"学校可依规给予警告、严重警告、记过等处分，但不得采用已废止或违法的人身强制、体罚等方式。","source":"word #122","bad":false,"notice":""},{"id":"w123","major":"词汇与综合","minor":"未成年人司法保护","question":"依资料所依据的规定，对未成年人犯罪一律不公开审理的年龄范围是（ ）。","options":[{"key":"A","text":"14周岁以下"},{"key":"B","text":"14周岁以上不满16周岁"},{"key":"C","text":"16周岁以上不满18周岁"},{"key":"D","text":"18周岁以上"}],"answer":"B","explanation":"资料采用当时题库口径：14周岁以上不满16周岁的未成年人犯罪案件一律不公开审理；相关法律条文后续可能调整，网页使用时宜标明题库年份。","source":"word #123","bad":false,"notice":""},{"id":"w124","major":"词汇与综合","minor":"未成年人保护","question":"父母让15周岁的未成年人脱离监护、单独居住，主要违反（ ）。","options":[{"key":"A","text":"《预防未成年人犯罪法》"},{"key":"B","text":"《公司法》"},{"key":"C","text":"《证券法》"},{"key":"D","text":"《专利法》"}],"answer":"A","explanation":"相关法律要求父母或其他监护人不得让未满规定年龄的未成年人脱离监护单独生活。","source":"word #124","bad":false,"notice":""},{"id":"w125","major":"词汇与综合","minor":"学生伤害事故","question":"寄宿学校校车司机停车后未清点人数即驶离，学生追车摔伤。对外承担主要责任的主体是（ ）。","options":[{"key":"A","text":"学生本人"},{"key":"B","text":"寄宿学校"},{"key":"C","text":"同车学生"},{"key":"D","text":"路边商户"}],"answer":"B","explanation":"接送学生属于学校组织管理活动。司机履职中的过错应由学校依法承担相应责任，学校可再依内部关系追责。","source":"word #125","bad":false,"notice":""},{"id":"w126","major":"词汇与综合","minor":"学生伤害事故","question":"学生陈某故意移开同学座椅，导致该同学尾椎骨裂。学校未尽到教育管理职责。依法应承担相应责任的是（ ）。","options":[{"key":"A","text":"只有任课教师"},{"key":"B","text":"陈某和学校"},{"key":"C","text":"只有受伤学生"},{"key":"D","text":"所有学生平均分担"}],"answer":"B","explanation":"陈某的行为直接导致损害；学校对在校学生负有教育、管理和保护职责，未尽职责的也应承担相应责任。","source":"word #126","bad":false,"notice":""},{"id":"w127","major":"词汇与综合","minor":"教师资格","question":"依法受理并认定中小学教师资格的机构通常是（ ）。","options":[{"key":"A","text":"县级以上人民政府教育行政部门"},{"key":"B","text":"任意培训机构"},{"key":"C","text":"学生家长委员会"},{"key":"D","text":"出版社"}],"answer":"A","explanation":"教师资格由依法具有认定权限的教育行政部门认定，培训机构不能自行颁发法定教师资格。","source":"word #127","bad":false,"notice":""},{"id":"w128","major":"词汇与综合","minor":"学生伤害事故","question":"自然课教师授课后让学生自由活动，未制止危险嬉闹，导致学生眼睛受伤致残。学校应（ ）。","options":[{"key":"A","text":"完全不承担责任"},{"key":"B","text":"因未尽教育管理职责承担相应责任"},{"key":"C","text":"只由任课教师个人对外承担全部责任"},{"key":"D","text":"由受伤学生承担全部责任"}],"answer":"B","explanation":"教师履行职务时未尽到必要的管理、告诫和制止义务，属于学校教育管理职责范围内的过错，学校应依法承担相应责任。","source":"word #128","bad":false,"notice":""},{"id":"w129","major":"词汇与综合","minor":"义务教育","question":"县级人民政府有关部门应均衡配置本行政区域内学校师资力量，组织校长、教师进行（ ）。","options":[{"key":"A","text":"培训和流动"},{"key":"B","text":"商业兼职"},{"key":"C","text":"自由停课"},{"key":"D","text":"校外收费补课"}],"answer":"A","explanation":"义务教育法要求通过培训和流动等方式促进师资均衡，加强薄弱学校建设。","source":"word #129","bad":false,"notice":""},{"id":"w130","major":"词汇与综合","minor":"法律解释","question":"学生手册规定“禁止男女生之间互访宿舍”，解释为“男女生不得无故进入异性宿舍”。这种解释主要属于（ ）。","options":[{"key":"A","text":"文义解释"},{"key":"B","text":"历史解释"},{"key":"C","text":"比较法解释"},{"key":"D","text":"目的解释"}],"answer":"A","explanation":"解释直接依据条文通常语义，把“互访”理解为进入异性宿舍，属于文义（文法）解释。","source":"word #130","bad":false,"notice":""},{"id":"w131","major":"词汇与综合","minor":"义务教育","question":"实施义务教育，学校依法不得收取（ ）。","options":[{"key":"A","text":"学费、杂费"},{"key":"B","text":"依法代收的自愿性校服费"},{"key":"C","text":"经批准的社会培训费"},{"key":"D","text":"大学学费"}],"answer":"A","explanation":"义务教育免收学费、杂费，保障适龄儿童少年平等接受义务教育。","source":"word #131","bad":false,"notice":""},{"id":"w132","major":"词汇与综合","minor":"义务教育","question":"符合义务教育免试就近入学原则的是（ ）。","options":[{"key":"A","text":"按户籍所在地和教育行政部门划定的学区入学"},{"key":"B","text":"必须选择全市排名最高的学校"},{"key":"C","text":"以竞赛成绩作为唯一入学条件"},{"key":"D","text":"由培训机构决定学校"}],"answer":"A","explanation":"义务教育阶段实行免试就近入学，教育行政部门根据适龄儿童少年数量、学校分布和规模等合理划定学区。","source":"word #132","bad":false,"notice":""},{"id":"w133","major":"词汇与综合","minor":"教育考试","question":"在国家教育考试中作弊的，依法宣布考试无效的机关是（ ）。","options":[{"key":"A","text":"教育行政部门"},{"key":"B","text":"考生所在社区"},{"key":"C","text":"任意培训机构"},{"key":"D","text":"新闻媒体"}],"answer":"A","explanation":"教育行政部门有权依法宣布有关国家教育考试无效，并对责任人员作出相应处理。","source":"word #133","bad":false,"notice":""},{"id":"w134","major":"词汇与综合","minor":"义务教育","question":"义务教育教学应注重培养学生的（ ）。","options":[{"key":"A","text":"独立思考能力、创新能力和实践能力"},{"key":"B","text":"机械背诵能力"},{"key":"C","text":"单一应试技巧"},{"key":"D","text":"服从性和依赖性"}],"answer":"A","explanation":"义务教育法强调面向全体学生，促进全面发展，注重培养独立思考、创新和实践能力。","source":"word #134","bad":false,"notice":""},{"id":"w135","major":"词汇与综合","minor":"教师资格","question":"曾因故意犯罪受到有期徒刑以上刑事处罚的人申请教师资格，下列判断正确的是（ ）。","options":[{"key":"A","text":"刑满后当然取得"},{"key":"B","text":"培训后即可取得"},{"key":"C","text":"五年后自动取得"},{"key":"D","text":"依法不能取得教师资格；已取得的，丧失教师资格"}],"answer":"D","explanation":"教师法规定，受到剥夺政治权利或者故意犯罪受到有期徒刑以上刑事处罚的，不能取得教师资格；已经取得的，丧失教师资格。","source":"word #135","bad":false,"notice":""},{"id":"w136","major":"词汇与综合","minor":"学校管理","question":"学校规定教师迟到一次罚款10元、缺勤一次罚款50元。该做法（ ）。","options":[{"key":"A","text":"正确，学校可任意罚款"},{"key":"B","text":"不正确，学校不具有行政罚款权"},{"key":"C","text":"正确，因为属于自主办学"},{"key":"D","text":"只有警告后才可罚款"}],"answer":"B","explanation":"罚款属于行政处罚种类，须有法定主体和依据。学校可以依规考核管理，但不能自行行使行政罚款权。","source":"word #136","bad":false,"notice":""},{"id":"w137","major":"词汇与综合","minor":"教育学","question":"传统教育与现代教育两个典型的对立代表人物是（ ）。","options":[{"key":"A","text":"赫尔巴特和杜威"},{"key":"B","text":"孔子和孟子"},{"key":"C","text":"夸美纽斯和洛克"},{"key":"D","text":"凯洛夫和赞科夫"}],"answer":"A","explanation":"教育学史上常以赫尔巴特代表传统教育、杜威代表现代教育。","source":"word #137","bad":false,"notice":""},{"id":"w138","major":"词汇与综合","minor":"教师法","question":"教师是履行教育教学职责的（ ）。","options":[{"key":"A","text":"专业人员"},{"key":"B","text":"行政处罚人员"},{"key":"C","text":"商业销售人员"},{"key":"D","text":"临时志愿者"}],"answer":"A","explanation":"教师法明确教师是履行教育教学职责的专业人员，承担教书育人、提高民族素质等使命。","source":"word #138","bad":false,"notice":""},{"id":"w139","major":"词汇与综合","minor":"教师义务","question":"下列属于教师法规定的教师义务的是（ ）。","options":[{"key":"A","text":"制止有害于学生的行为，并不断提高教育教学业务水平"},{"key":"B","text":"任意公开学生隐私"},{"key":"C","text":"随意停止学生上课"},{"key":"D","text":"以罚款代替教育"}],"answer":"A","explanation":"教师应关心爱护学生，制止有害于学生的行为，批评抵制不利于学生健康成长的现象，并不断提高业务水平。","source":"word #139","bad":false,"notice":""},{"id":"w140","major":"词汇与综合","minor":"德育","question":"学校有目的、有计划、系统地对学生进行德育的基本途径是（ ）。","options":[{"key":"A","text":"思想政治课与其他学科教学"},{"key":"B","text":"偶然的社会传闻"},{"key":"C","text":"学生自发活动"},{"key":"D","text":"单纯行政命令"}],"answer":"A","explanation":"课堂教学，特别是思想政治课与其他学科教学，是学校实施德育最基本、最经常的途径。","source":"word #140","bad":false,"notice":""},{"id":"w141","major":"词汇与综合","minor":"学校管理","question":"1993年《中国教育改革和发展纲要》明确，中等及中等以下学校实行（ ）。","options":[{"key":"A","text":"校长负责制"},{"key":"B","text":"书记个人负责制"},{"key":"C","text":"学生会负责制"},{"key":"D","text":"家长委员会负责制"}],"answer":"A","explanation":"纲要提出中等及中等以下各类学校实行校长负责制，校长全面贯彻教育方针并依靠教职工办学。","source":"word #141","bad":false,"notice":""},{"id":"w142","major":"词汇与综合","minor":"教师资格","question":"教师资格制度主要依据（ ）制定和实施。","options":[{"key":"A","text":"《中华人民共和国教师法》及配套法规"},{"key":"B","text":"《中华人民共和国公司法》"},{"key":"C","text":"《中华人民共和国证券法》"},{"key":"D","text":"《中华人民共和国海商法》"}],"answer":"A","explanation":"教师资格认定以教师法、教师资格条例及其实施办法等为依据。","source":"word #142","bad":false,"notice":""},{"id":"w143","major":"词汇与综合","minor":"未成年人保护","question":"收留夜不归宿的未成年人时，应征得其父母或其他监护人同意，或者在（ ）内及时通知、报告。","options":[{"key":"A","text":"12小时"},{"key":"B","text":"24小时"},{"key":"C","text":"48小时"},{"key":"D","text":"7日"}],"answer":"B","explanation":"资料题采用24小时的通知或报告时限。","source":"word #143","bad":false,"notice":""},{"id":"w144","major":"词汇与综合","minor":"德育原则","question":"马卡连柯提出的“平行教育原则”体现了（ ）。","options":[{"key":"A","text":"集体教育与个别教育相结合"},{"key":"B","text":"严格要求与尊重信任相结合"},{"key":"C","text":"正面教育与纪律约束相结合"},{"key":"D","text":"教育影响的一致性与连贯性"}],"answer":"A","explanation":"教师先影响集体，再通过集体影响个人，使集体和教师形成平行的教育力量。","source":"word #144","bad":false,"notice":""},{"id":"w145","major":"词汇与综合","minor":"特殊教育","question":"普通学校对具有接受普通教育能力的残疾适龄儿童、少年应当（ ）。","options":[{"key":"A","text":"接收其随班就读并提供学习、康复帮助"},{"key":"B","text":"一律拒收"},{"key":"C","text":"只允许旁听"},{"key":"D","text":"要求其放弃义务教育"}],"answer":"A","explanation":"义务教育坚持平等受教育，普通学校应接收具有接受普通教育能力的残疾儿童少年随班就读并给予帮助。","source":"word #145","bad":false,"notice":""},{"id":"w146","major":"词汇与综合","minor":"教学方法","question":"教师系统连贯地向学生传授知识、表达情感并培养价值观，主要采用的教学方法是（ ）。","options":[{"key":"A","text":"讲授法"},{"key":"B","text":"练习法"},{"key":"C","text":"实验法"},{"key":"D","text":"陶冶法"}],"answer":"A","explanation":"讲授法由教师通过语言系统传授知识，也可表达思想情感和价值判断。","source":"word #146","bad":false,"notice":""},{"id":"w147","major":"词汇与综合","minor":"学生伤害事故","question":"学校组织春游，教师已反复进行安全教育，学生仍违反明确警示攀爬假山而受伤。无其他管理过错时，主要责任应由（ ）。","options":[{"key":"A","text":"学生按其认知能力承担相应责任"},{"key":"B","text":"学校无条件承担全部责任"},{"key":"C","text":"教师个人承担全部责任"},{"key":"D","text":"公园其他游客承担"}],"answer":"A","explanation":"学校已履行合理教育、告知义务，而伤害主要源于学生违反明确警示的行为，应结合学生年龄和认知能力确定其自身责任。","source":"word #147","bad":false,"notice":""},{"id":"w148","major":"词汇与综合","minor":"教育史","question":"古代社会教育的典型特点之一是（ ）。","options":[{"key":"A","text":"完全没有阶级性"},{"key":"B","text":"具有阶级性"},{"key":"C","text":"教育与社会完全无关"},{"key":"D","text":"已经普及义务教育"}],"answer":"B","explanation":"进入阶级社会后，教育资源和培养目标受到阶级关系影响，古代学校教育具有鲜明阶级性。","source":"word #148","bad":false,"notice":""},{"id":"w149","major":"词汇与综合","minor":"扫盲教育","question":"按题库所引《扫除文盲工作条例》，农民个人脱盲应识读的汉字数量为（ ）。","options":[{"key":"A","text":"1000个"},{"key":"B","text":"1500个"},{"key":"C","text":"2000个"},{"key":"D","text":"2500个"}],"answer":"B","explanation":"资料题给出的农民个人脱盲识字标准为1500个汉字。","source":"word #149","bad":false,"notice":""},{"id":"w150","major":"词汇与综合","minor":"教学原则","question":"“君子之教，喻也：道而弗牵，强而弗抑，开而弗达。”体现的教学原则是（ ）。","options":[{"key":"A","text":"启发性原则"},{"key":"B","text":"量力性原则"},{"key":"C","text":"巩固性原则"},{"key":"D","text":"统一要求原则"}],"answer":"A","explanation":"教师应引导而不牵着走、激励而不强迫、启发而不把结论全部说尽，体现启发性。","source":"word #150","bad":false,"notice":""},{"id":"w151","major":"词汇与综合","minor":"义务教育","question":"适龄儿童、少年因身体状况需要延缓入学或者休学的，其监护人提出申请后，由（ ）批准。","options":[{"key":"A","text":"学校任意一名教师"},{"key":"B","text":"乡镇人民政府或者县级人民政府教育行政部门"},{"key":"C","text":"学生会"},{"key":"D","text":"培训机构"}],"answer":"B","explanation":"义务教育法规定，延缓入学或休学申请由当地乡镇人民政府或者县级人民政府教育行政部门批准。","source":"word #151","bad":false,"notice":""},{"id":"w152","major":"词汇与综合","minor":"宪法与行政法","question":"根据我国宪法，国务院有权制定和发布（ ）。","options":[{"key":"A","text":"教育行政法规"},{"key":"B","text":"教育法律"},{"key":"C","text":"地方性法规"},{"key":"D","text":"学校内部班规"}],"answer":"A","explanation":"国务院根据宪法和法律制定行政法规；法律由全国人大及其常委会制定。","source":"word #152","bad":false,"notice":""},{"id":"w153","major":"词汇与综合","minor":"教育学","question":"人类社会最早产生的教育学以（ ）作为研究对象。","options":[{"key":"A","text":"一般教育现象和教育问题"},{"key":"B","text":"仅高等教育"},{"key":"C","text":"仅特殊教育"},{"key":"D","text":"仅职业教育"}],"answer":"A","explanation":"教育学是研究教育现象和教育问题、揭示教育规律的科学。","source":"word #153","bad":false,"notice":""},{"id":"w154","major":"词汇与综合","minor":"教育史","question":"“教学相长”等教育思想最早集中见于（ ）。","options":[{"key":"A","text":"《学记》"},{"key":"B","text":"《理想国》"},{"key":"C","text":"《大教学论》"},{"key":"D","text":"《教育漫话》"}],"answer":"A","explanation":"《学记》是我国古代系统论述教育教学问题的著作，其中提出“教学相长”等思想。","source":"word #154","bad":false,"notice":""},{"id":"w155","major":"词汇与综合","minor":"教学原则","question":"下列成语中，最能体现启发式教学思想的是（ ）。","options":[{"key":"A","text":"举一反三"},{"key":"B","text":"循规蹈矩"},{"key":"C","text":"墨守成规"},{"key":"D","text":"按部就班"}],"answer":"A","explanation":"“举一反三”强调由已知启发未知、触类旁通，体现启发式教学。","source":"word #155","bad":false,"notice":""},{"id":"w156","major":"词汇与综合","minor":"科学阅读","question":"有些动物身体透明，从光学角度看，主要原因是其身体组织（ ）。","options":[{"key":"A","text":"能吸收全部可见光"},{"key":"B","text":"几乎不能吸收可见光，且散射较弱"},{"key":"C","text":"只反射红光"},{"key":"D","text":"不断主动发光"}],"answer":"B","explanation":"物体呈现颜色通常与选择性吸收、反射可见光有关。组织对可见光吸收和散射都很弱时，会表现得较透明。","source":"word #156","bad":false,"notice":""},{"id":"w157","major":"词汇与综合","minor":"教育心理","question":"布卢姆把教育目标分为（ ）三个领域。","options":[{"key":"A","text":"认知、情感、动作技能"},{"key":"B","text":"知识、纪律、考试"},{"key":"C","text":"德育、智育、体育"},{"key":"D","text":"教师、学生、教材"}],"answer":"A","explanation":"布卢姆教育目标分类体系通常分为认知、情感和动作技能三个领域。","source":"word #157","bad":false,"notice":""},{"id":"w158","major":"词汇与综合","minor":"教学论","question":"教学活动的本质是一种（ ）。","options":[{"key":"A","text":"特殊的认识活动"},{"key":"B","text":"单纯的体力活动"},{"key":"C","text":"商业交换活动"},{"key":"D","text":"行政处罚活动"}],"answer":"A","explanation":"学生的学习是在教师引导下，以间接经验为主、兼有直接经验的特殊认识活动。","source":"word #158","bad":false,"notice":""},{"id":"w159","major":"词汇与综合","minor":"教育与社会","question":"教育对政治经济制度的影响，主要通过（ ）。","options":[{"key":"A","text":"培养所需要的人才并形成社会舆论"},{"key":"B","text":"改变自然气候"},{"key":"C","text":"增加商品库存"},{"key":"D","text":"替代全部法律制度"}],"answer":"A","explanation":"教育通过培养人才、传播政治思想和形成社会舆论作用于政治经济制度。","source":"word #159","bad":false,"notice":""},{"id":"w160","major":"词汇与综合","minor":"教育学","question":"“强调学生的一般发展，并要求教学走在发展前面”的教育家是（ ）。","options":[{"key":"A","text":"赞科夫"},{"key":"B","text":"凯洛夫"},{"key":"C","text":"赫尔巴特"},{"key":"D","text":"斯金纳"}],"answer":"A","explanation":"赞科夫的发展性教学理论强调以高难度、高速度等原则促进学生的一般发展。","source":"word #160","bad":false,"notice":""},{"id":"w161","major":"词汇与综合","minor":"心理学","question":"妄想的基本特征是（ ）。","options":[{"key":"A","text":"以事实为基础且可随证据立即改变"},{"key":"B","text":"内容完全客观"},{"key":"C","text":"脱离现实的病理性信念，虽与事实不符仍坚信不疑"},{"key":"D","text":"只是普通想象"}],"answer":"C","explanation":"妄想是一种病理性的歪曲信念，内容与事实不符，患者仍坚信不疑，且常与自身密切相关。","source":"word #161","bad":false,"notice":""},{"id":"w162","major":"词汇与综合","minor":"社会心理","question":"“维特效应”主要指（ ）。","options":[{"key":"A","text":"知名人物或媒体报道自杀事件后，短期内模仿性自杀增加"},{"key":"B","text":"运动后学习效率提高"},{"key":"C","text":"群体合作必然降低效率"},{"key":"D","text":"阅读小说使记忆永久增强"}],"answer":"A","explanation":"“维特效应”指自杀事件及其传播可能诱发模仿行为，媒体报道需要遵循负责任原则。","source":"word #162","bad":false,"notice":""},{"id":"w163","major":"词汇与综合","minor":"文化常识","question":"“人生自古谁无死，留取丹心照汗青”出自文天祥的（ ）。","options":[{"key":"A","text":"《过零丁洋》"},{"key":"B","text":"《正气歌》"},{"key":"C","text":"《岳阳楼记》"},{"key":"D","text":"《赤壁赋》"}],"answer":"A","explanation":"该名句出自南宋文天祥《过零丁洋》，表达舍生取义、忠贞报国之志。","source":"word #163","bad":false,"notice":""},{"id":"w164","major":"词汇与综合","minor":"文学常识","question":"“世上本没有路，走的人多了，也便成了路”出自鲁迅的（ ）。","options":[{"key":"A","text":"《故乡》"},{"key":"B","text":"《孔乙己》"},{"key":"C","text":"《阿Q正传》"},{"key":"D","text":"《祝福》"}],"answer":"A","explanation":"这句话出自鲁迅小说《故乡》，以“路”比喻希望与实践开辟的新方向。","source":"word #164","bad":false,"notice":""},{"id":"w165","major":"词汇与综合","minor":"实词辨析","question":"一些媒体越来越被市场____，不再具有公共属性，自然也很难提供有价值的公共产品；公共价值也逐渐____了踪迹。依次填入最恰当的一项是（ ）。","options":[{"key":"A","text":"利用；消失"},{"key":"B","text":"裹挟；隐匿"},{"key":"C","text":"主导；收敛"},{"key":"D","text":"解释；显现"}],"answer":"B","explanation":"“裹挟”强调媒体受到市场力量影响而被带动；“隐匿踪迹”搭配自然。其余搭配或语义不合。","source":"word #165","bad":false,"notice":""},{"id":"w166","major":"词汇与综合","minor":"实词辨析","question":"除夕夜，高耸入云的海心塔在灯光映照下不断变色，整体变色效果为新春增添了一道____的风景。填入最恰当的一项是（ ）。","options":[{"key":"A","text":"壮丽"},{"key":"B","text":"绮丽"},{"key":"C","text":"华丽"},{"key":"D","text":"艳丽"}],"answer":"C","explanation":"“华丽”侧重美丽而有光彩，适合形容灯光映照下不断变幻、光彩华美的城市景观。","source":"word #166","bad":false,"notice":""},{"id":"w167","major":"词汇与综合","minor":"教育理念","question":"“每个学生都是____的，怎样让每个学生得到发展，教师会遇到很多无法预料的问题。”填入最恰当的一项是（ ）。","options":[{"key":"A","text":"相互联系"},{"key":"B","text":"变化发展"},{"key":"C","text":"举世无双"},{"key":"D","text":"独一无二"}],"answer":"D","explanation":"语境强调学生之间存在个体差异，“独一无二”最准确，也能与因材施教的教育要求衔接。","source":"word #167","bad":false,"notice":""},{"id":"w168","major":"词汇与综合","minor":"实词辨析","question":"政协委员们不约而同地指出，社会上的种种腐败现象正在____社会肌体。填入最恰当的一项是（ ）。","options":[{"key":"A","text":"侵害"},{"key":"B","text":"侵蚀"},{"key":"C","text":"腐蚀"},{"key":"D","text":"吞噬"}],"answer":"B","explanation":"“侵蚀”常比喻坏的思想或事物逐渐损害事物基础，与“腐败现象”“社会肌体”搭配贴切。","source":"word #168","bad":false,"notice":""},{"id":"w169","major":"词汇与综合","minor":"时政常识","question":"科学发展观的第一要义、核心和基本要求依次是（ ）。","options":[{"key":"A","text":"发展；以人为本；全面协调可持续"},{"key":"B","text":"改革；经济建设；共同富裕"},{"key":"C","text":"开放；依法治国；科技创新"},{"key":"D","text":"稳定；增强国力；统筹城乡"}],"answer":"A","explanation":"科学发展观的第一要义是发展，核心是以人为本，基本要求是全面协调可持续。","source":"word #169","bad":false,"notice":""},{"id":"w170","major":"词汇与综合","minor":"阅读理解","question":"中国传统学术较重书画、较轻雕塑，这种历史惯性影响了近现代收藏审美；新兴收藏者多关注铜鎏金佛像的艺术表象，却对更能体现雕塑文化和历史岁月的高古石雕举棋不定。文段主要说明（ ）。","options":[{"key":"A","text":"高古石雕制作工艺已经失传"},{"key":"B","text":"高古石雕不受重视的历史与审美原因"},{"key":"C","text":"所有铜鎏金佛像都没有史料价值"},{"key":"D","text":"雕塑收藏价格必然等于历史价值"}],"answer":"B","explanation":"文段先追溯传统学术轻视雕塑的历史，再说明这种审美惯性延续到收藏领域，中心是解释高古石雕未受重视的原因。","source":"word #170","bad":false,"notice":""},{"id":"w171","major":"词汇与综合","minor":"阅读理解","question":"三十多年前，精密计算模型已预测二氧化碳增加会使全球升温，但科学家和公众一度并未重视，甚至乐观地认为这会促进农业。由此可以推出（ ）。","options":[{"key":"A","text":"全球变暖一定只会损害农业"},{"key":"B","text":"早期人们尚未充分认识全球变暖的严重影响"},{"key":"C","text":"所有气候模型都不可靠"},{"key":"D","text":"二氧化碳增加不会影响气温"}],"answer":"B","explanation":"材料对比了已有升温预测与当时社会的乐观、平静态度，表明早期人们尚未充分认识问题的严重性。","source":"word #171","bad":false,"notice":""},{"id":"w172","major":"词汇与综合","minor":"阅读理解","question":"未来人口增长和经济发展将推动全球能源需求增加，能源利用效率的提高只能抵消其中相当一部分增长。下列表述不正确的是（ ）。","options":[{"key":"A","text":"能源与经济发展关系密切"},{"key":"B","text":"未来能源需求仍可能增加"},{"key":"C","text":"提高能源效率会抵消部分需求增长"},{"key":"D","text":"提高能源效率最终会完全抑制能源需求增长"}],"answer":"D","explanation":"原文只说效率提高会抵消相当一部分需求增长，并未说会完全抑制或逆转能源需求增长。","source":"word #172","bad":false,"notice":""},{"id":"w173","major":"词汇与综合","minor":"词语辨析","question":"面对人大代表依法提出的问题，有些部门负责人虽然不能圆满答复，但都虚心接受。与“人大代表依法提出问题”最恰当的词是（ ）。","options":[{"key":"A","text":"质疑"},{"key":"B","text":"质问"},{"key":"C","text":"对质"},{"key":"D","text":"质询"}],"answer":"D","explanation":"“质询”指人大代表依法就政府工作向有关国家机关提出询问并要求答复，具有特定的政务语境。","source":"word #173","bad":false,"notice":""},{"id":"w174","major":"词汇与综合","minor":"语言运用","question":"网络飞速发展，使社会各方面的____加强、信息交流加快、生产和工作效率提高，同时也可能____新的社会问题。依次填入最恰当的一项是（ ）。","options":[{"key":"A","text":"关联；催生"},{"key":"B","text":"联系；带来"},{"key":"C","text":"交往；杜绝"},{"key":"D","text":"关系；消灭"}],"answer":"B","explanation":"“联系加强”是固定、自然的搭配；网络发展既提高效率，也可能“带来”新的社会问题。","source":"word #174","bad":false,"notice":""},{"id":"w175","major":"词汇与综合","minor":"网络法治","question":"有人认为，要求互联网服务提供者对用户发布的信息进行____，不利于言论自由；但若把散布谣言也视为自由，显然是____。依次填入最恰当的一项是（ ）。","options":[{"key":"A","text":"过滤；偷换概念"},{"key":"B","text":"整合；断章取义"},{"key":"C","text":"评价；混淆时空"},{"key":"D","text":"转发；循序渐进"}],"answer":"A","explanation":"前一空是对违法有害信息的筛查、过滤；把散布谣言偷换成受保护的言论自由，属于偷换概念。","source":"word #175","bad":false,"notice":""},{"id":"w176","major":"词汇与综合","minor":"说明文阅读","question":"超细颗粒功能制备机先用高速气流粉碎并自动分级颗粒，再加入纳米或微米材料进行复合包覆，使药品颗粒防止团聚并保护药效。这段文字主要说明该设备的（ ）。","options":[{"key":"A","text":"销售渠道和市场规模"},{"key":"B","text":"设计原理及其在药品粉碎、制备中的应用"},{"key":"C","text":"制造成本和维修方法"},{"key":"D","text":"操作人员的培训制度"}],"answer":"B","explanation":"材料按工作流程介绍设备的设计原理，并以药品超细粉碎、包覆为例说明其应用。","source":"word #176","bad":false,"notice":""},{"id":"w177","major":"词汇与综合","minor":"成语运用","question":"依次填入下列句子，最恰当的一组是（ ）。①环境污染日趋严重，人类这种____的行为如不停止，将自毁生存空间。②某公司非法占地建设别墅，最终____，建筑被责令拆除。③制造铁路爆炸案的罪犯终于____，被逮捕归案。","options":[{"key":"A","text":"玩火自焚；自食其果；落入法网"},{"key":"B","text":"作茧自缚；安然无恙；逍遥法外"},{"key":"C","text":"自作自受；因祸得福；功成名就"},{"key":"D","text":"自食其果；左右逢源；逃之夭夭"}],"answer":"A","explanation":"“玩火自焚”强调危险行为终将害己；“自食其果”指自己承担恶果；罪犯被捕应用“落入法网”。","source":"word #177","bad":false,"notice":""},{"id":"w178","major":"词汇与综合","minor":"语言逻辑","question":"关于“这块麦田今年增产”的原因，下列说法最严谨的是（ ）。","options":[{"key":"A","text":"肯定是化肥用得多"},{"key":"B","text":"一定与化肥无关"},{"key":"C","text":"只能是气候原因"},{"key":"D","text":"可能是化肥用得多，也可能另有原因"}],"answer":"D","explanation":"在证据不足时，不能把相关或可能原因说成唯一、确定原因；“可能”表述保留了其他解释。","source":"word #178","bad":false,"notice":""},{"id":"w179","major":"词汇与综合","minor":"关联词","question":"____虚心承认错误和缺点，____能从错误和缺点中学到新的知识和本领，____取得进步。依次填入最恰当的一项是（ ）。","options":[{"key":"A","text":"如果；或者；就"},{"key":"B","text":"只有；才；从而"},{"key":"C","text":"即使；也；但是"},{"key":"D","text":"因为；所以；反而"}],"answer":"B","explanation":"句子表达必要条件和结果关系，应用“只有……才……从而……”。","source":"word #179","bad":false,"notice":""},{"id":"w180","major":"词汇与综合","minor":"语境填空","question":"影响消费者口碑的，有时不是产品主体，而是纽扣、按钮等不太引人注意的零部件。这些看似____的失误足以引起反感。赢得口碑必须把基础工作做细、做到位并____。依次填入最恰当的一项是（ ）。","options":[{"key":"A","text":"微不足道；持之以恒"},{"key":"B","text":"漫不经心；有的放矢"},{"key":"C","text":"随处可见；面面俱到"},{"key":"D","text":"举足轻重；半途而废"}],"answer":"A","explanation":"“微不足道”与“不太引人注意”照应；品质控制需要长期坚持，应用“持之以恒”。","source":"word #180","bad":false,"notice":""},{"id":"w181","major":"词汇与综合","minor":"语境填空","question":"每一个老字号的成长都凝结着经营者的____，但有些老字号如今已____。老字号的兴衰与社会生活____。依次填入最恰当的一项是（ ）。","options":[{"key":"A","text":"苦心孤诣；奄奄一息；息息相关"},{"key":"B","text":"人生百态；朝不保夕；互不相干"},{"key":"C","text":"心酸无奈；蒸蒸日上；毫无联系"},{"key":"D","text":"沧海桑田；安然无恙；南辕北辙"}],"answer":"A","explanation":"“苦心孤诣”指费尽心思钻研经营；“奄奄一息”形容濒于衰亡；“息息相关”表示关系密切。","source":"word #181","bad":false,"notice":""},{"id":"w182","major":"词汇与综合","minor":"词语辨析","question":"天山绵延几千里，雪峰、深谷处处都有丰饶物产和____的美景。填入最恰当的一项是（ ）。","options":[{"key":"A","text":"美丽"},{"key":"B","text":"奇丽"},{"key":"C","text":"艳丽"},{"key":"D","text":"华丽"}],"answer":"B","explanation":"“奇丽”指奇特而美丽，适合描写天山多样、壮美而独特的自然景观。","source":"word #182","bad":false,"notice":""},{"id":"w183","major":"词汇与综合","minor":"管理学","question":"组织结构设置不合理，导致一个下级同时接受多个上级领导，这种现象称为“多头领导”。下列俗语最能体现这一问题的是（ ）。","options":[{"key":"A","text":"三个和尚没水吃"},{"key":"B","text":"塞翁失马，焉知非福"},{"key":"C","text":"一叶障目，不见泰山"},{"key":"D","text":"众人拾柴火焰高"}],"answer":"A","explanation":"多头领导会造成职责不清、相互推诿，“三个和尚没水吃”形象地反映了这一问题。","source":"word #183","bad":false,"notice":""},{"id":"w184","major":"词汇与综合","minor":"医学常识","question":"亚健康是健康与疾病之间的过渡状态。下列现象最符合亚健康特征的是（ ）。","options":[{"key":"A","text":"外伤后在医院进行康复治疗"},{"key":"B","text":"已确诊急性传染病并发热"},{"key":"C","text":"长期劳累、检查发现异常，但尚无明显疾病症状"},{"key":"D","text":"身体健康且各项指标正常"}],"answer":"C","explanation":"亚健康强调尚未达到明确疾病诊断，却已出现功能下降、指标异常或不适。长期劳累且检查有异常、尚无明显症状最符合。","source":"word #184","bad":false,"notice":""},{"id":"w185","major":"词汇与综合","minor":"词语辨析","question":"为了躲避敌人的搜捕，她____成一名普通村民。填入最恰当的一项是（ ）。","options":[{"key":"A","text":"化装"},{"key":"B","text":"化妆"},{"key":"C","text":"乔装打扮地化妆"},{"key":"D","text":"美容"}],"answer":"A","explanation":"“化装”指改变装束、容貌以掩饰身份；“化妆”侧重用化妆品修饰容貌。","source":"word #185","bad":false,"notice":""},{"id":"w186","major":"词汇与综合","minor":"成语辨析","question":"古筝悠扬，清茶沁人，加之窗外西湖美景，令人心旷神怡，几乎（ ）。","options":[{"key":"A","text":"乐不思蜀"},{"key":"B","text":"感慨万千"},{"key":"C","text":"诗兴大发"},{"key":"D","text":"物我两忘"}],"answer":"D","explanation":"“物我两忘”形容沉浸于境界之中，忘却外物与自我，最符合古筝、清茶、西湖共同营造的审美意境。","source":"word #186","bad":false,"notice":""},{"id":"w187","major":"词汇与综合","minor":"成语辨析","question":"“他们____地要使我永远不能再拿笔。”填入最恰当的一项是（ ）。","options":[{"key":"A","text":"耿耿于怀"},{"key":"B","text":"挖空心思"},{"key":"C","text":"阴险狡诈"},{"key":"D","text":"处心积虑"}],"answer":"D","explanation":"“处心积虑”指长期蓄意谋划，多含贬义；与“要使我永远不能再拿笔”的恶意目的相符。","source":"word #187","bad":false,"notice":""},{"id":"w188","major":"词汇与综合","minor":"文学常识","question":"“诗中有画，画中有诗”是苏轼对哪位诗人的评价？（ ）","options":[{"key":"A","text":"王维"},{"key":"B","text":"李白"},{"key":"C","text":"杜甫"},{"key":"D","text":"白居易"}],"answer":"A","explanation":"苏轼评价王维“味摩诘之诗，诗中有画；观摩诘之画，画中有诗”。","source":"word #188","bad":false,"notice":""},{"id":"w189","major":"词汇与综合","minor":"文学常识","question":"巴金“激流三部曲”包括（ ）。","options":[{"key":"A","text":"《家》《春》《秋》"},{"key":"B","text":"《雾》《雨》《电》"},{"key":"C","text":"《幻灭》《动摇》《追求》"},{"key":"D","text":"《红日》《红旗谱》《创业史》"}],"answer":"A","explanation":"巴金的“激流三部曲”为《家》《春》《秋》；《雾》《雨》《电》是“爱情三部曲”。","source":"word #189","bad":false,"notice":""},{"id":"w190","major":"词汇与综合","minor":"人生哲理","question":"人生有挫折、失败和误解很正常。想让生活少些阻碍，应先____心中的障碍；懂得爱的人不会是____的。依次填入最恰当的一项是（ ）。","options":[{"key":"A","text":"增加；平凡"},{"key":"B","text":"保留；伟大"},{"key":"C","text":"扫除；平庸"},{"key":"D","text":"制造；高尚"}],"answer":"C","explanation":"“扫除障碍”搭配恰当；懂得爱使人的精神世界充实，不会流于“平庸”。","source":"word #190","bad":false,"notice":""},{"id":"w191","major":"词汇与综合","minor":"字音","question":"下列词语中，加点字的读音完全正确的一项是（ ）。","options":[{"key":"A","text":"狡黠（jí） ……"},{"key":"B","text":"缄默（jiān） ……"},{"key":"C","text":"木讷（nè） ……"},{"key":"D","text":"兀自（wù） ……"}],"answer":"B","explanation":"题干不完整。原资料标注答案为B；其余选项中可辨认的“狡黠”应读jiǎo xiá，“兀自”的“兀”读wù。","source":"word #191","bad":true,"notice":"原扫描文本不完整，答案未核实，请在待核验区查看。"},{"id":"w192","major":"词汇与综合","minor":"易错字","question":"选出下列没有错别字的一项（ ）。","options":[{"key":"A","text":"觅食 轻捷 质朴 收敛"},{"key":"B","text":"乘凉 监赏 啄食 缘由"},{"key":"C","text":"书塾 消释 颠倒 鼎沸"},{"key":"D","text":"绅士 秀像 渊博 恭敬"}],"answer":"C","explanation":"题干不完整。原资料标注答案为C。B项“监赏”应为“鉴赏”，D项“秀像”应为“肖像”；A项在扫描页中可能有字符缺损，故按原答案保留。","source":"word #192","bad":false,"notice":"依据可见残文整理/补充，并非完整原版试题。"},{"id":"w193","major":"词汇与综合","minor":"易错字","question":"下面句子中没有错别字的一项是（ ）。","options":[{"key":"A","text":"主持人宣布：这次辨论达到了辨伪去妄的目的。"},{"key":"B","text":"我放弃了竞选，我偃旗息鼓，甘拜下风。"},{"key":"C","text":"第二天早上，我们决定把小茅屋修茸一下。"},{"key":"D","text":"这栋建筑构思精巧，外形美轮美换。"}],"answer":"B","explanation":"题干不完整。原资料标注答案为B。A项“辨论”应为“辩论”；C项“修茸”应为“修葺”；D项“美轮美换”应为“美轮美奂”。","source":"word #193","bad":false,"notice":"依据可见残文整理/补充，并非完整原版试题。"},{"id":"w194","major":"词汇与综合","minor":"易错字","question":"下列词语中，没有错别字的一组是（ ）。","options":[{"key":"A","text":"奢侈 点缀 川流不息 才疏学浅"},{"key":"B","text":"辉煌 惋惜 辨伪去妄 姹紫嫣红"},{"key":"C","text":"翱翔 狼籍 豁然开朗 巧妙绝伦"},{"key":"D","text":"葱茏 渊博 改邪归正 相提并论"}],"answer":"D","explanation":"题干不完整。原资料标注答案为D。C项“狼籍”应为“狼藉”；A、B项中至少有一处原字在扫描页上无法可靠辨认，因此不据清晰转写判断。","source":"word #194","bad":false,"notice":"依据可见残文整理/补充，并非完整原版试题。"},{"id":"w195","major":"词汇与综合","minor":"病句辨析","question":"下列各句中，没有语病的一句是（ ）。","options":[{"key":"A","text":"随着改革开放的日益深入，每年到绥芬河边境……"},{"key":"B","text":"校长非常理解他这次因县里召开第三届数学能手大赛……"},{"key":"C","text":"对于网上发布的应取消房屋预售制度的消息……"},{"key":"D","text":"是否具有坚忍不拔的毅力和卓尔不凡的……"}],"answer":"A","explanation":"题干不完整。原资料标注答案为A；由于四个选项均有缺字，无法对每个病因作可靠还原。","source":"word #195","bad":true,"notice":"原扫描文本不完整，答案未核实，请在待核验区查看。"},{"id":"w196","major":"词汇与综合","minor":"标点符号","question":"下列各句中，标点符号使用正确的一项是（ ）。","options":[{"key":"A","text":"句末标点置于括号内"},{"key":"B","text":"句末标点置于括号外"},{"key":"C","text":"并列词之间全部使用逗号"},{"key":"D","text":"将书名号改为引号"}],"answer":"A","explanation":"题干不完整。原资料给出的正确项为A。该项将括号内相对独立的说明文字及其句末点号完整置于括号内。","source":"word #196","bad":true,"notice":"原扫描文本不完整，答案未核实，请在待核验区查看。"},{"id":"w197","major":"词汇与综合","minor":"歧义辨析","question":"下列句子中，语意明确、没有歧义的一句是（ ）。","options":[{"key":"A","text":"他文思敏捷，三天就写出了一篇文章。"},{"key":"B","text":"不适当地管教孩子，对孩子的成长十分不利。"},{"key":"C","text":"在我们公司里，除了老王，他最关心生产安全。"},{"key":"D","text":"火车票没买到，老王只能托小李给他买票。"}],"answer":"A","explanation":"题干不完整。A项语意明确。B项可按“不/适当地管教”或“不适当地/管教”作不同切分；C项“除了老王”有排除或包含老王两种理解；D项“他”的指代对象不够明确。","source":"word #197","bad":false,"notice":"依据可见残文整理/补充，并非完整原版试题。"},{"id":"w198","major":"词汇与综合","minor":"成语辨析","question":"下列句中成语使用正确的一项是（ ）。","options":[{"key":"A","text":"面对突如其来的暴雨，工作人员临危不乱，迅速组织群众转移。"},{"key":"B","text":"来自各班的同学推波助澜，使活动顺利举行。"},{"key":"C","text":"面对亚健康状态，他不以为然地制定了锻炼计划。"},{"key":"D","text":"就反腐败问题，他振振有词地表示坚决支持。"}],"answer":"A","explanation":"题干不完整。根据原答案补配选项。A项“临危不乱”使用恰当；B项“推波助澜”、C项“不以为然”、D项“振振有词”在对应褒义语境中均使用不当。","source":"word #198","bad":false,"notice":"依据可见残文整理/补充，并非完整原版试题。"},{"id":"w199","major":"词汇与综合","minor":"语境填空","question":"或许我们真的需要经典作品来____我们前行的步伐；这些作品有着____岁月阻隔的力度，能唤起我们在浮躁时代对人生的追索。","options":[{"key":"A","text":"放慢 穿过"},{"key":"B","text":"停止 超越"},{"key":"C","text":"阻止 超过"},{"key":"D","text":"引领 跨越"}],"answer":"D","explanation":"题干不完整。根据可辨认语境补配选项：经典作品可以“引领”前行的步伐，也能“跨越”岁月阻隔，D项搭配自然、语意连贯。","source":"word #199","bad":false,"notice":"依据可见残文整理/补充，并非完整原版试题。"},{"id":"w200","major":"词汇与综合","minor":"语境填空","question":"天气预报看似很____，只有寥寥几句话，但要作出____的预报，工程量很大；大气运动本身又____，这是预报有时不准确的根本原因。","options":[{"key":"A","text":"轻松 准确 无迹可寻"},{"key":"B","text":"平常 精密 变幻莫测"},{"key":"C","text":"普通 精确 难以捉摸"},{"key":"D","text":"简单 准确 复杂多变"}],"answer":"D","explanation":"题干不完整。根据可辨认语境补配D项：“只有寥寥几句话”对应“简单”；预报要求“准确”；大气运动“复杂多变”导致预测困难。","source":"word #200","bad":false,"notice":"依据可见残文整理/补充，并非完整原版试题。"},{"id":"w201","major":"词汇与综合","minor":"病句辨析","question":"下面各句中没有语病的一句是（ ）。","options":[{"key":"A","text":"那一刻，通过我们几个看到他露出灿烂笑容，使大家激动不已。"},{"key":"B","text":"机动车进胡同，对机动车噪声居民们早有微词。"},{"key":"C","text":"我们的教育工作者积极发现人才、培养人才，本身就是一种贡献。"},{"key":"D","text":"由于殖民时代的业余运作方式，直接导致竞技体育运动长期处于低水平。"}],"answer":"C","explanation":"题干不完整。C项主干清楚、搭配恰当。A项“通过……使……”导致主语残缺；B项语序不当；D项“由于……”与“导致……”连用，导致主语残缺。","source":"word #201","bad":false,"notice":"依据可见残文整理/补充，并非完整原版试题。"},{"id":"w202","major":"词汇与综合","minor":"教育学","question":"教育过程的主要矛盾是（ ）。","options":[{"key":"A","text":"教育者提出的教育要求与受教育者已有发展水平之间的矛盾"},{"key":"B","text":"教材内容与课时之间的矛盾"},{"key":"C","text":"学校与家庭之间的矛盾"},{"key":"D","text":"教师数量与学生数量之间的矛盾"}],"answer":"A","explanation":"题干不完整。按教育学通行表述，教育过程的主要矛盾是教育者提出的教育要求与受教育者已有身心发展水平之间的矛盾。","source":"word #202","bad":false,"notice":"依据可见残文整理/补充，并非完整原版试题。"},{"id":"w203","major":"词汇与综合","minor":"教育制度","question":"凡年满（ ）周岁的儿童，其父母或者其他法定监护人应当送其入学接受并完成义务教育；条件不具备的地区可推迟到（ ）周岁。","options":[{"key":"A","text":"六；七"},{"key":"B","text":"七；八"},{"key":"C","text":"五；六"},{"key":"D","text":"八；九"}],"answer":"A","explanation":"题干不完整。依据义务教育法的一般规定，凡年满六周岁的儿童应入学，条件不具备的地区可以推迟到七周岁。","source":"word #203","bad":false,"notice":"依据可见残文整理/补充，并非完整原版试题。"},{"id":"w204","major":"词汇与综合","minor":"教师职业","question":"在教育过程中，教师劳动具有（ ）特点。","options":[{"key":"A","text":"创造性"},{"key":"B","text":"机械性"},{"key":"C","text":"短期性"},{"key":"D","text":"单一性"}],"answer":"A","explanation":"题干不完整。教师劳动通常具有复杂性、创造性、示范性、长期性等特点；若按原页单选标注，答案为“创造性”。","source":"word #204","bad":true,"notice":"原扫描文本不完整，答案未核实，请在待核验区查看。"},{"id":"w205","major":"词汇与综合","minor":"教育学","question":"教育与生产力之间的关系是（ ）。","options":[{"key":"A","text":"生产力制约教育发展，教育也能促进生产力发展"},{"key":"B","text":"二者完全无关"},{"key":"C","text":"教育只能被动适应生产力"},{"key":"D","text":"教育决定一切生产力水平"}],"answer":"A","explanation":"题干不完整。生产力的发展水平制约教育的规模、速度、结构和内容，教育又通过人才培养和知识传播促进生产力发展。","source":"word #205","bad":false,"notice":"依据可见残文整理/补充，并非完整原版试题。"},{"id":"w206","major":"词汇与综合","minor":"社会经济","question":"“口红效应”是指（ ）。","options":[{"key":"A","text":"经济不景气时，某些价格较低的非必需消费品销量反而上升"},{"key":"B","text":"物价上涨时所有商品销量都增加"},{"key":"C","text":"高价奢侈品永远畅销"},{"key":"D","text":"经济繁荣时消费必然停止"}],"answer":"A","explanation":"题干不完整。“口红效应”通常指经济低迷时，消费者减少大额支出，却可能增加口红等价格相对较低、能带来心理满足的非必需消费。","source":"word #206","bad":false,"notice":"依据可见残文整理/补充，并非完整原版试题。"},{"id":"w207","major":"词汇与综合","minor":"语言运用","question":"外交部发言中，中国对有关西沙、南沙群岛的无端言论予以____。","options":[{"key":"A","text":"驳斥"},{"key":"B","text":"赞同"},{"key":"C","text":"迎合"},{"key":"D","text":"默认"}],"answer":"A","explanation":"题干不完整。结合外交表态语境，对无端言论通常使用“驳斥”等词；原题完整搭配已无法由扫描页可靠恢复。","source":"word #207","bad":true,"notice":"原扫描文本不完整，答案未核实，请在待核验区查看。"},{"id":"m1","major":"数学题","minor":"概率","question":"在写有2、4、6、7、8、11、12、13的8张卡片中任取2张，两数互质的概率是多少？","options":[{"key":"A","text":"3/28"},{"key":"B","text":"3/4"},{"key":"C","text":"3/14"},{"key":"D","text":"9/14"}],"answer":"D","explanation":"任取2张共有C(8,2)=28种。逐对检验最大公约数，互质的组合有18种，所以概率为18/28=9/14。","source":"math #1","bad":false,"notice":""},{"id":"m2","major":"数学题","minor":"概率","question":"有1、2、3、4、5、6厘米长的小棒各1根，任取3根，能拼成三角形的概率是多少？","options":[{"key":"A","text":"1/3"},{"key":"B","text":"1/4"},{"key":"C","text":"1/6"},{"key":"D","text":"7/20"}],"answer":"D","explanation":"任取3根共有C(6,3)=20种。按“两短边之和大于最长边”逐组检验，符合的有7组，所以概率为7/20。","source":"math #2","bad":false,"notice":""},{"id":"m3","major":"数学题","minor":"方程应用","question":"网管员小刘负责甲、乙、丙三个机房的巡检工作，三个机房分别每隔2天、4天和7天巡检一次。3月1日三个机房都已巡检，整个3月有几天不用巡检？","options":[{"key":"A","text":"12天"},{"key":"B","text":"14天"},{"key":"C","text":"15天"},{"key":"D","text":"13天"}],"answer":"D","explanation":"甲机房的巡检日在3月共有16天；乙机房的巡检日包含在甲机房内。丙机房巡检日为1、8、15、22、29日，其中8日和22日是新增日期，共有18天要巡检，所以不用巡检的天数为31-18=13天。","source":"math #3","bad":false,"notice":""},{"id":"m4","major":"数学题","minor":"概率","question":"有三个自然数，任取两个数相加分别得到8、11、13，任取两个数相乘分别得到15、24、40，求这三个数的平方和。","options":[{"key":"A","text":"52"},{"key":"B","text":"65"},{"key":"C","text":"70"},{"key":"D","text":"98"}],"answer":"D","explanation":"三个数为3、5、8，平方和为3²+5²+8²=98。","source":"math #4","bad":false,"notice":""},{"id":"m5","major":"数学题","minor":"容斥原理","question":"某单位组织党员参加党史、党风廉政建设、科学发展观和业务能力四项培训，要求每名党员参加且只参加其中两项。无论如何安排，都有至少5名党员参加的培训完全相同，问该单位至少有多少名党员？","options":[{"key":"A","text":"17"},{"key":"B","text":"21"},{"key":"C","text":"25"},{"key":"D","text":"29"}],"answer":"C","explanation":"四项培训中任选两项共有6种组合。每种组合最多安排4人时共24人，再增加1人必有某一组合至少5人，因此至少25人。","source":"math #5","bad":false,"notice":""},{"id":"m6","major":"数学题","minor":"利润经济","question":"某苗木公司准备出售一批苗木。如果每株以4元出售，可卖出20万株；单价每提高0.4元，就会少卖1万株。问在最佳定价情况下，公司最大收入是多少万元？","options":[{"key":"A","text":"60"},{"key":"B","text":"80"},{"key":"C","text":"90"},{"key":"D","text":"100"}],"answer":"C","explanation":"设提价x次，收入为(4+0.4x)(20-x)万元。该二次函数在x=5时取得最大值90万元。","source":"math #6","bad":false,"notice":""},{"id":"m7","major":"数学题","minor":"容斥原理","question":"某社团46人，其中35人爱好戏剧、30人爱好体育、38人爱好写作、40人爱好收藏。至少有多少人同时喜欢这4项活动？","options":[{"key":"A","text":"5人"},{"key":"B","text":"6人"},{"key":"C","text":"7人"},{"key":"D","text":"8人"}],"answer":"A","explanation":"四项爱好人数和为143。若把每人最多先计入3项，46人可容纳138人次，超出的143-138=5人次必须来自同时喜欢4项的人，所以至少5人。","source":"math #7","bad":false,"notice":""},{"id":"m8","major":"数学题","minor":"排列组合","question":"有前排6座、后排7座，安排2名不同的人就座。前排中间2座不能坐，且两人不能在同一排相邻。不同坐法有多少种？","options":[{"key":"A","text":"32种"},{"key":"B","text":"44种"},{"key":"C","text":"60种"},{"key":"D","text":"94种"}],"answer":"D","explanation":"可用座位共11个，两人有11×10=110种有序坐法。同排相邻的无序座位对有前排2对、后排6对，共8对；考虑两人顺序要扣16种，得到110-16=94种。","source":"math #8","bad":false,"notice":""},{"id":"m9","major":"数学题","minor":"几何问题","question":"某单位准备扩建一个矩形花园。若将花园的长和宽各增加4米，新花园的面积比原来增加40平方米。原花园的周长是多少米？","options":[{"key":"A","text":"12"},{"key":"B","text":"24"},{"key":"C","text":"32"},{"key":"D","text":"40"}],"answer":"A","explanation":"设原长、宽为a、b，则(a+4)(b+4)-ab=40，得a+b=6，原周长为2(a+b)=12米。","source":"math #9","bad":false,"notice":""},{"id":"m10","major":"数学题","minor":"方程应用","question":"某次测验有50道判断题，每答对一题得3分，不做或答错一题倒扣1分。某学生共得82分，问答对题数与答错题数（包括未作答）相差多少？","options":[{"key":"A","text":"19"},{"key":"B","text":"18"},{"key":"C","text":"17"},{"key":"D","text":"16"}],"answer":"D","explanation":"设答对x题，则3x-(50-x)=82，解得x=33；其余17题，相差16题。","source":"math #10","bad":false,"notice":""},{"id":"m11","major":"数学题","minor":"数论问题","question":"一个四位数分别能被15、12和10整除，且被这三个数整除所得三个商的和为1365。这个四位数的四个数字之和是多少？","options":[{"key":"A","text":"12"},{"key":"B","text":"14"},{"key":"C","text":"15"},{"key":"D","text":"16"}],"answer":"C","explanation":"设该数为n，则n/15+n/12+n/10=n/4=1365，所以n=5460，数字和为15。","source":"math #11","bad":false,"notice":""},{"id":"m12","major":"数学题","minor":"比例百分数","question":"某公司去年有830名员工。今年男员工比去年减少6%，女员工比去年增加5%，员工总数增加3人。今年男员工有多少人？","options":[{"key":"A","text":"329人"},{"key":"B","text":"350人"},{"key":"C","text":"371人"},{"key":"D","text":"504人"}],"answer":"A","explanation":"设去年男员工x人，则女员工830-x人。0.94x+1.05(830-x)=833，解得去年男员工350人，今年为350×0.94=329人。","source":"math #12","bad":false,"notice":""},{"id":"m13","major":"数学题","minor":"方程应用","question":"5个鸡蛋和3个鸭蛋的重量相当于12个鸭蛋。1个鸡蛋相当于几个鸭蛋的重量？","options":[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"1.5"},{"key":"D","text":"1.8"}],"answer":"D","explanation":"5个鸡蛋相当于9个鸭蛋，所以1个鸡蛋相当于9÷5=1.8个鸭蛋。","source":"math #13","bad":false,"notice":""},{"id":"m14","major":"数学题","minor":"比例百分数","question":"去年车间产量850件，今年884件，增长率是多少？","options":[{"key":"A","text":"1%"},{"key":"B","text":"2%"},{"key":"C","text":"4%"},{"key":"D","text":"5%"}],"answer":"C","explanation":"增长量为884-850=34，增长率为34÷850=4%。","source":"math #14","bad":false,"notice":""},{"id":"m15","major":"数学题","minor":"排列组合","question":"一部影片在4个单位各放映1场，4个单位的轮映次序有多少种？","options":[{"key":"A","text":"6种"},{"key":"B","text":"12种"},{"key":"C","text":"24种"},{"key":"D","text":"48种"}],"answer":"C","explanation":"4个不同单位的放映顺序是全排列，共4!=24种。","source":"math #15","bad":false,"notice":""},{"id":"m16","major":"数学题","minor":"计数问题","question":"商场活动：满300减180、满200减100、满100减40，不参加活动可打五五折。购买360元、220元、150元商品各1件，最少付多少元？","options":[{"key":"A","text":"360元"},{"key":"B","text":"382.5元"},{"key":"C","text":"401.6元"},{"key":"D","text":"415元"}],"answer":"B","explanation":"逐件取更优惠方式：360元用满减付180元；220元用满减付120元；150元打五五折付82.5元。合计382.5元。","source":"math #16","bad":false,"notice":""},{"id":"m17","major":"数学题","minor":"方程应用","question":"甲、乙两数之和为456，甲数末位是5，去掉末位5所得数等于乙。甲数是多少？","options":[{"key":"A","text":"155"},{"key":"B","text":"415"},{"key":"C","text":"355"},{"key":"D","text":"215"}],"answer":"B","explanation":"设乙为x，则甲为10x+5。由10x+5+x=456，解得x=41，因此甲为415。","source":"math #17","bad":false,"notice":""},{"id":"m18","major":"数学题","minor":"比例百分数","question":"a比b大20%，b比c大25%，则a比c大多少？","options":[{"key":"A","text":"40%"},{"key":"B","text":"50%"},{"key":"C","text":"60%"},{"key":"D","text":"30%"}],"answer":"B","explanation":"a=1.2b，b=1.25c，所以a=1.5c，即a比c大50%。","source":"math #18","bad":false,"notice":""},{"id":"m19","major":"数学题","minor":"数列规律","question":"1/5，1/8，1/11，1/14，（ ）。","options":[{"key":"A","text":"1/15"},{"key":"B","text":"1/17"},{"key":"C","text":"1/16"},{"key":"D","text":"1/18"}],"answer":"B","explanation":"分母依次增加3，所以下一项为1/17。","source":"math #19","bad":false,"notice":""},{"id":"m20","major":"数学题","minor":"数论问题","question":"一个小于200的自然数，除以11余8，除以13余10。这个数是多少？","options":[{"key":"A","text":"140"},{"key":"B","text":"126"},{"key":"C","text":"154"},{"key":"D","text":"168"}],"answer":"A","explanation":"把候选数写成11k+8，逐个检验模13的余数。140÷11余8，140÷13余10，且140小于200。","source":"math #20","bad":false,"notice":""},{"id":"m21","major":"数学题","minor":"容斥原理","question":"三位专家为10幅作品投票，每位专家各投5票，且每幅作品都至少有一位专家投票。三位专家都投票的作品为A等，两位专家投票的作品为B等，仅一位专家投票的作品为C等。下列说法正确的是哪一项？","options":[{"key":"A","text":"A等和B等共6幅"},{"key":"B","text":"B等和C等共7幅"},{"key":"C","text":"A等最多有5幅"},{"key":"D","text":"A等比C等少5幅"}],"answer":"D","explanation":"本题考查容斥原理。先计算各集合人数之和，再扣除重复部分或使用最不利情况。计算结果为“A等比C等少5幅”，因此选择D。","source":"math #21","bad":false,"notice":""},{"id":"m22","major":"数学题","minor":"概率","question":"8名网球选手平均分成两组，每组4人。甲、乙两名选手不在同一组的概率是多少？","options":[{"key":"A","text":"3/7"},{"key":"B","text":"5/7"},{"key":"C","text":"4/7"},{"key":"D","text":"6/7"}],"answer":"C","explanation":"先固定甲所在的组。剩余7个位置中，有4个位置属于另一组，所以乙与甲不同组的概率是4/7。","source":"math #22","bad":false,"notice":""},{"id":"m23","major":"数学题","minor":"方程应用","question":"最小的两位数、最小的三位数和最小的四位数之和是多少？","options":[{"key":"A","text":"1010"},{"key":"B","text":"2100"},{"key":"C","text":"11100"},{"key":"D","text":"1110"}],"answer":"D","explanation":"10+100+1000=1110。","source":"math #23","bad":false,"notice":""},{"id":"m24","major":"数学题","minor":"排列组合","question":"制作一面国旗要用红、黄、蓝3种颜色的布。制作4面完全相同的国旗，至少需要多少种颜色的布？","options":[{"key":"A","text":"3种"},{"key":"B","text":"2种"},{"key":"C","text":"4种"},{"key":"D","text":"5种"}],"answer":"A","explanation":"四面国旗完全相同，可以反复使用同样的3种颜色，不会因数量增加而增加颜色种类。","source":"math #24","bad":false,"notice":""},{"id":"m25","major":"数学题","minor":"数列规律","question":"1，8，9，4，（ ），1/6。","options":[{"key":"A","text":"3"},{"key":"B","text":"2"},{"key":"C","text":"1"},{"key":"D","text":"1/3"}],"answer":"C","explanation":"各项可写为1¹、2³、3²、4¹、5⁰、6⁻¹，因此空缺项为1。","source":"math #25","bad":false,"notice":""},{"id":"m26","major":"数学题","minor":"方程应用","question":"树上有8只鸟，猎人开枪后打死2只，问树上还剩几只活鸟？（假设其他鸟都被枪声惊飞）","options":[{"key":"A","text":"0"},{"key":"B","text":"2"},{"key":"C","text":"6"},{"key":"D","text":"8"}],"answer":"A","explanation":"枪声使其他活鸟飞走，被打死的鸟不再是活鸟，所以树上剩0只活鸟。","source":"math #26","bad":false,"notice":""},{"id":"m27","major":"数学题","minor":"数列规律","question":"3，4，8，24，88，（ ）。","options":[{"key":"A","text":"344"},{"key":"B","text":"332"},{"key":"C","text":"166"},{"key":"D","text":"164"}],"answer":"A","explanation":"本题考查数列规律。比较相邻项的差、比或拆分奇偶位置，确定稳定变化规律。计算结果为“344”，因此选择A。","source":"math #27","bad":false,"notice":""},{"id":"m28","major":"数学题","minor":"数列规律","question":"28，17，6，（ ），8/7。","options":[{"key":"A","text":"3/2"},{"key":"B","text":"1"},{"key":"C","text":"0"},{"key":"D","text":"2"}],"answer":"D","explanation":"原题解析乱码，数列规律未获可靠核实，请对原题及标准答案保持审慎；此题暂不计入正常练习。","source":"math #28","bad":true,"notice":"原题信息残缺或答案有争议，暂不参与计分。"},{"id":"m29","major":"数学题","minor":"数论问题","question":"某电器工作功耗为370瓦，待机功耗为37瓦。周一9:30至17:00处于工作状态，其余时间断电；周二9:00至24:00处于待机状态，其余时间断电。周一耗电量是周二的多少倍？","options":[{"key":"A","text":"6"},{"key":"B","text":"7"},{"key":"C","text":"8"},{"key":"D","text":"5"}],"answer":"D","explanation":"周一耗电量为370×7.5，周二耗电量为37×15，二者之比为5。","source":"math #29","bad":false,"notice":""},{"id":"m30","major":"数学题","minor":"方程应用","question":"一个人去书店买了一本书和一本杂志，付款时把书价的十位数和个位数看反了，付了21元。售货员说应付39元。书比杂志贵多少元？","options":[{"key":"A","text":"20"},{"key":"B","text":"22"},{"key":"C","text":"23"},{"key":"D","text":"24"}],"answer":"C","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“23”，因此选择C。","source":"math #30","bad":false,"notice":""},{"id":"m31","major":"数学题","minor":"比例百分数","question":"两个城市中心的距离在比例尺为1:100000的地图上为16.8厘米，两地实际距离是多少公里？","options":[{"key":"A","text":"1.68"},{"key":"B","text":"16.8"},{"key":"C","text":"168"},{"key":"D","text":"1680"}],"answer":"B","explanation":"本题考查比例百分数。把基准量设为1份或100%，按对应比例换算。计算结果为“16.8”，因此选择B。","source":"math #31","bad":false,"notice":""},{"id":"m32","major":"数学题","minor":"几何问题","question":"在一块长25公里、宽8公里的长方形区域内设置哨塔，每个哨塔的监视半径为5公里。若要求区域内每个角落都能被监视到，至少需要设置多少个哨塔？","options":[{"key":"A","text":"7"},{"key":"B","text":"6"},{"key":"C","text":"5"},{"key":"D","text":"4"}],"answer":"C","explanation":"本题考查几何问题。画出关键尺寸，代入相应的周长、面积或体积公式。计算结果为“5”，因此选择C。","source":"math #32","bad":false,"notice":""},{"id":"m33","major":"数学题","minor":"比例百分数","question":"某单位原有本科、研究生学历职工人数之比为7∶5。上半年招聘本科生后，两类人数之比变为3∶1；下半年引进研究生后，又变为15∶8。全年引进的本科生比研究生多15人。原有两类职工共多少人？","options":[{"key":"A","text":"32人"},{"key":"B","text":"36人"},{"key":"C","text":"40人"},{"key":"D","text":"44人"}],"answer":"B","explanation":"设原人数为7k、5k。招聘本科生8k人后变为15k∶5k；再引进3k名研究生后变为15∶8。由8k-3k=15得k=3，原有12k=36人。","source":"math #33","bad":false,"notice":""},{"id":"m34","major":"数学题","minor":"利润经济","question":"商业街发放满50减10元、满100减30元、满200减60元优惠券。商户共核销15.6万张，优惠总额的75%可抵租金，最终抵扣租金219万元。消费者实际支付金额的最低值在哪个范围？","options":[{"key":"A","text":"低于750万元"},{"key":"B","text":"750～800万元"},{"key":"C","text":"800～850万元"},{"key":"D","text":"超过850万元"}],"answer":"C","explanation":"优惠总额为219÷75%=292万元。要让实付最低，应优先使用满100减30的券：可由8.8万张10元券和6.8万张30元券组成。最低实付为8.8×40+6.8×70=828万元。","source":"math #34","bad":false,"notice":""},{"id":"m35","major":"数学题","minor":"计数问题","question":"某村有756名居民需要乘车，车辆有20座中巴和30座大巴。按车辆总数最少的原则安排，最少需要多少辆大巴？","options":[{"key":"A","text":"23辆"},{"key":"B","text":"29辆"},{"key":"C","text":"32辆"},{"key":"D","text":"26辆"}],"answer":"D","explanation":"大巴载客量更大。756÷30=25余6，因此至少需要26辆大巴；25辆最多载750人，不够。","source":"math #35","bad":false,"notice":""},{"id":"m36","major":"数学题","minor":"计数问题","question":"某地10户农户共申请25万元贷款。每户申请额都是1000元的整数倍，各户金额互不相同，最高额不超过最低额的2倍。最低申请额最少可能是多少万元？","options":[{"key":"A","text":"1.6万元"},{"key":"B","text":"1.44万元"},{"key":"C","text":"1.76万元"},{"key":"D","text":"1.92万元"}],"answer":"A","explanation":"把金额按千元计。最低额若为15，另外9个数最多取22～30，总和为234，加15只有249，不足250；最低额为16时可以配出总和250，因此最少为1.6万元。","source":"math #36","bad":false,"notice":""},{"id":"m37","major":"数学题","minor":"几何问题","question":"用三个互相垂直的平面切一个圆柱形蛋糕，最多能切成多少块？","options":[{"key":"A","text":"7块"},{"key":"B","text":"8块"},{"key":"C","text":"9块"},{"key":"D","text":"10块"}],"answer":"B","explanation":"第一刀分成2块，第二刀与第一刀垂直可分成4块，第三刀再与前两刀垂直，可把4块各分为两半，共8块。","source":"math #37","bad":false,"notice":""},{"id":"m38","major":"数学题","minor":"年龄问题","question":"今年哥哥和弟弟的年龄和为55岁。曾有一年，哥哥当时的年龄等于弟弟今年的年龄，并且当时哥哥年龄是弟弟年龄的2倍。哥哥今年多少岁？","options":[{"key":"A","text":"30岁"},{"key":"B","text":"36岁"},{"key":"C","text":"33岁"},{"key":"D","text":"39岁"}],"answer":"C","explanation":"设哥哥今年x岁，弟弟55-x岁。回到哥哥为55-x岁时，弟弟为110-3x岁。由55-x=2(110-3x)，解得x=33。","source":"math #38","bad":false,"notice":""},{"id":"m39","major":"数学题","minor":"方程应用","question":"计算：999×999+1999。","options":[{"key":"A","text":"900000"},{"key":"B","text":"1100000"},{"key":"C","text":"1200000"},{"key":"D","text":"1000000"}],"answer":"D","explanation":"999×999=(1000-1)²=998001，再加1999恰好等于1000000。","source":"math #39","bad":false,"notice":""},{"id":"m40","major":"数学题","minor":"工程问题","question":"修建一座水库，甲村单独投资还缺92万元，乙村单独投资还缺88万元，两村合作投资仍缺20万元。修建水库共需多少万元？","options":[{"key":"A","text":"160万元"},{"key":"B","text":"144万元"},{"key":"C","text":"176万元"},{"key":"D","text":"192万元"}],"answer":"A","explanation":"设总投资为x万元，则甲村可出x-92，乙村可出x-88。合作仍缺20，故(x-92)+(x-88)=x-20，解得x=160。","source":"math #40","bad":false,"notice":""},{"id":"m41","major":"数学题","minor":"方程应用","question":"最小的两位数、最小的三位数和最小的四位数之和是多少？","options":[{"key":"A","text":"999"},{"key":"B","text":"1110"},{"key":"C","text":"1221"},{"key":"D","text":"1332"}],"answer":"B","explanation":"最小的两位数是10，最小的三位数是100，最小的四位数是1000，三者之和为1110。","source":"math #41","bad":false,"notice":""},{"id":"m42","major":"数学题","minor":"工程问题","question":"一份稿件，小王单独打需8小时，老张单独打需6小时。两人一起打字，中途老张停了1小时。完成时小王工作了多少小时？","options":[{"key":"A","text":"3小时"},{"key":"B","text":"5小时"},{"key":"C","text":"4小时"},{"key":"D","text":"6小时"}],"answer":"C","explanation":"设小王工作x小时，则老张工作x-1小时。列式x/8+(x-1)/6=1，解得x=4。","source":"math #42","bad":false,"notice":""},{"id":"m43","major":"数学题","minor":"方程应用","question":"纽约时间比香港时间晚13小时。纽约4月1日20:00通话时，香港是几点？","options":[{"key":"A","text":"3月2日9:00"},{"key":"B","text":"5月2日9:00"},{"key":"C","text":"6月2日9:00"},{"key":"D","text":"4月2日9:00"}],"answer":"D","explanation":"香港时间比纽约早13小时，20:00加13小时为次日9:00。","source":"math #43","bad":false,"notice":""},{"id":"m44","major":"数学题","minor":"数列规律","question":"找规律：4，7，6，8，8，11，（ ），（ ）。","options":[{"key":"A","text":"10，16"},{"key":"B","text":"9，16"},{"key":"C","text":"11，16"},{"key":"D","text":"12，16"}],"answer":"A","explanation":"奇数位为4、6、8、10，依次加2；偶数位为7、8、11、16，增量依次为1、3、5。","source":"math #44","bad":false,"notice":""},{"id":"m45","major":"数学题","minor":"排列组合","question":"数列按（1，3，5）、（2，6，10）、（3，9，15）……排列，第101个数是多少？","options":[{"key":"A","text":"92"},{"key":"B","text":"102"},{"key":"C","text":"112"},{"key":"D","text":"122"}],"answer":"B","explanation":"每3个数为一组，第n组是n、3n、5n。101=3×33+2，是第34组第2个数，即3×34=102。","source":"math #45","bad":false,"notice":""},{"id":"m46","major":"数学题","minor":"数列规律","question":"找规律：3，4，8，24，88，（ ）。","options":[{"key":"A","text":"310"},{"key":"B","text":"378"},{"key":"C","text":"344"},{"key":"D","text":"412"}],"answer":"C","explanation":"相邻两项的差依次为1、4、16、64，均为前一个差的4倍，所以下一个差为256，88+256=344。","source":"math #46","bad":false,"notice":""},{"id":"m47","major":"数学题","minor":"方程应用","question":"空间中三条不同直线的交点个数可能有哪些？","options":[{"key":"A","text":"0、2"},{"key":"B","text":"2、3"},{"key":"C","text":"0、2、3"},{"key":"D","text":"0、1、2、3"}],"answer":"D","explanation":"三线可互相异面而无交点，也可出现1个、2个或两两相交形成3个不同交点，因此四种数量都可能。","source":"math #47","bad":false,"notice":""},{"id":"m48","major":"数学题","minor":"几何问题","question":"一块宽为2a的长方形铁片，两边各向上折起x，形成矩形水槽。x取何值时横截面积最大？","options":[{"key":"A","text":"a/4"},{"key":"B","text":"a/3"},{"key":"C","text":"a/2"},{"key":"D","text":"2a/3"}],"answer":"C","explanation":"横截面积S=x(2a-2x)=-2(x-a/2)²+a²/2，所以x=a/2时面积最大。","source":"math #48","bad":false,"notice":""},{"id":"m49","major":"数学题","minor":"概率","question":"一枚均匀硬币连续抛3次，至少有2次正面朝上的概率是多少？","options":[{"key":"A","text":"0/2"},{"key":"B","text":"1/2"},{"key":"C","text":"2/2"},{"key":"D","text":"3/2"}],"answer":"B","explanation":"恰有2次正面有C(3,2)=3种，3次全是正面有1种，共4种；总结果有2³=8种，概率为4/8=1/2。","source":"math #49","bad":false,"notice":""},{"id":"m50","major":"数学题","minor":"几何问题","question":"一个长方形被分成3×3的9个小长方形。三个角上小长方形的面积分别为8、12、18，第四个角的面积是多少？","options":[{"key":"A","text":"24"},{"key":"B","text":"30"},{"key":"C","text":"27"},{"key":"D","text":"33"}],"answer":"C","explanation":"设四角面积分别为ac、ad、bc、bd，则ac×bd=ad×bc。第四角面积为12×18÷8=27。","source":"math #50","bad":false,"notice":""},{"id":"m51","major":"数学题","minor":"年龄问题","question":"一家三口年龄和为74岁，爸爸比妈妈大2岁，妈妈年龄是孩子的4倍。爸爸多少岁？","options":[{"key":"A","text":"31岁"},{"key":"B","text":"37岁"},{"key":"C","text":"40岁"},{"key":"D","text":"34岁"}],"answer":"D","explanation":"设孩子x岁，则妈妈4x岁、爸爸4x+2岁。x+4x+4x+2=74，得x=8，爸爸34岁。","source":"math #51","bad":false,"notice":""},{"id":"m52","major":"数学题","minor":"方程应用","question":"台历连续7天没有翻，这7个日期之和为77。今天是几号？","options":[{"key":"A","text":"15号"},{"key":"B","text":"13号"},{"key":"C","text":"17号"},{"key":"D","text":"19号"}],"answer":"A","explanation":"连续7个日期的中间数等于平均数77÷7=11，所以这7天是8日至14日，今天是15日。","source":"math #52","bad":false,"notice":""},{"id":"m53","major":"数学题","minor":"利润经济","question":"某商品按成本价加价40%定价，后按定价的75%出售，每件盈利16元。成本价是多少？","options":[{"key":"A","text":"288元"},{"key":"B","text":"320元"},{"key":"C","text":"352元"},{"key":"D","text":"384元"}],"answer":"B","explanation":"售价为成本的1.4×0.75=1.05倍，利润率为5%。成本价=16÷5%=320元。","source":"math #53","bad":false,"notice":""},{"id":"m54","major":"数学题","minor":"方程应用","question":"某校师生共若干人，男女比为7∶3，教师与学生比为2∶8，教师中男女比也为7∶3。男教师有70人，女学生有多少人？","options":[{"key":"A","text":"108人"},{"key":"B","text":"132人"},{"key":"C","text":"120人"},{"key":"D","text":"144人"}],"answer":"C","explanation":"男教师70人对应教师的70%，教师共100人；全校共500人，女性150人。女教师30人，所以女学生为150-30=120人。","source":"math #54","bad":false,"notice":""},{"id":"m55","major":"数学题","minor":"排列组合","question":"某病房有15名护士，每班2人，每8小时换班。若把所有两人组合轮换一遍，同一组合再次值班最长需多少天？","options":[{"key":"A","text":"31天"},{"key":"B","text":"39天"},{"key":"C","text":"43天"},{"key":"D","text":"35天"}],"answer":"D","explanation":"两人组合共有C(15,2)=105组，每班8小时，共105×8=840小时，即35天。","source":"math #55","bad":false,"notice":""},{"id":"m56","major":"数学题","minor":"方程应用","question":"已知-5<x≤3，-3<y≤5，则xy的取值范围是？","options":[{"key":"A","text":"-25<xy≤15"},{"key":"B","text":"-15<xy<15"},{"key":"C","text":"-25≤xy≤25"},{"key":"D","text":"-25<xy<25"}],"answer":"A","explanation":"正积最大值为3×5=15；负积可以无限接近-25但不能取到。整体范围为-25<xy≤15。","source":"math #56","bad":false,"notice":""},{"id":"m57","major":"数学题","minor":"方程应用","question":"下列哪个分数大于4/5且小于5/6？","options":[{"key":"A","text":"7/10"},{"key":"B","text":"10/11"},{"key":"C","text":"49/60"},{"key":"D","text":"28/31"}],"answer":"C","explanation":"4/5=48/60，5/6=50/60，因此49/60严格位于两者之间。","source":"math #57","bad":false,"notice":""},{"id":"m58","major":"数学题","minor":"方程应用","question":"三个自然数两两相加分别得到4、7、9，两两相乘分别得到3、6、18。这三个数的平方和是多少？","options":[{"key":"A","text":"41"},{"key":"B","text":"51"},{"key":"C","text":"46"},{"key":"D","text":"56"}],"answer":"C","explanation":"三个数是1、3、6，平方和为1²+3²+6²=46。","source":"math #58","bad":false,"notice":""},{"id":"m59","major":"数学题","minor":"概率","question":"从1～9中任取3个不同的数，恰好只有一组相邻数的概率是多少？","options":[{"key":"A","text":"0/2"},{"key":"B","text":"2/2"},{"key":"C","text":"3/2"},{"key":"D","text":"1/2"}],"answer":"D","explanation":"总取法为C(9,3)=84。枚举相邻数对并排除连续三数，可得符合条件的三数组合有42个，所以概率为42/84=1/2。","source":"math #59","bad":false,"notice":""},{"id":"m60","major":"数学题","minor":"工程问题","question":"A、B两台机器合作18天完成任务，A、C合作28天完成，A、B、C合作14.4天完成。B、C合作需多少天？","options":[{"key":"A","text":"21天"},{"key":"B","text":"19天"},{"key":"C","text":"23天"},{"key":"D","text":"25天"}],"answer":"A","explanation":"设效率为a、b、c。a+b=1/18，a+c=1/28，a+b+c=1/14.4，先求a，再得b+c=1/21。","source":"math #60","bad":false,"notice":""},{"id":"m61","major":"数学题","minor":"容斥原理","question":"某年级100人，20人参加外语组，32人参加计算机组。两组都不参加的人至少有多少？","options":[{"key":"A","text":"43人"},{"key":"B","text":"48人"},{"key":"C","text":"53人"},{"key":"D","text":"58人"}],"answer":"B","explanation":"两组参加人数的并集最多为20+32=52人，因此都不参加的人至少为100-52=48人。","source":"math #61","bad":false,"notice":""},{"id":"m62","major":"数学题","minor":"方程应用","question":"数学竞赛共10题，答对1题得8分，答错1题扣5分。小明答完全部题并得41分，他答对几题？","options":[{"key":"A","text":"6题"},{"key":"B","text":"8题"},{"key":"C","text":"7题"},{"key":"D","text":"9题"}],"answer":"C","explanation":"设答对x题，则8x-5(10-x)=41，解得13x=91，x=7。","source":"math #62","bad":false,"notice":""},{"id":"m63","major":"数学题","minor":"方程应用","question":"数学竞赛共20题，答对1题得5分，答错或不答扣3分。小明得60分，他答对几题？","options":[{"key":"A","text":"13题"},{"key":"B","text":"17题"},{"key":"C","text":"19题"},{"key":"D","text":"15题"}],"answer":"D","explanation":"设答对x题，则5x-3(20-x)=60，解得8x=120，所以x=15。","source":"math #63","bad":false,"notice":""},{"id":"m64","major":"数学题","minor":"行程问题","question":"静水中船以垂直河岸的方向匀速过河，用时T₁。水流动后，船相对水的方向和速度不变，过河用时T₂。两者关系如何？","options":[{"key":"A","text":"T₂>T₁"},{"key":"B","text":"T₂=T₁"},{"key":"C","text":"T₂<T₁"},{"key":"D","text":"无法确定"}],"answer":"B","explanation":"水流只改变沿河方向的位移，不改变船垂直河岸方向的速度分量，所以过河时间不变。","source":"math #64","bad":false,"notice":""},{"id":"m65","major":"数学题","minor":"行程问题","question":"甲、乙两车同地同向前往目的地。甲每小时40千米，乙每小时35千米。乙先行20千米后甲出发，甲几小时追上乙？","options":[{"key":"A","text":"3小时"},{"key":"B","text":"4小时"},{"key":"C","text":"5小时"},{"key":"D","text":"6小时"}],"answer":"B","explanation":"甲每小时比乙多行5千米，追上20千米的路程差需要20÷5=4小时。","source":"math #65","bad":false,"notice":""},{"id":"m66","major":"数学题","minor":"容斥原理","question":"兄弟从家去学校。弟弟每分钟60米，提前10分钟出发；哥哥每分钟90米，两人同时到校。家到学校多远？","options":[{"key":"A","text":"1620米"},{"key":"B","text":"1980米"},{"key":"C","text":"1800米"},{"key":"D","text":"2160米"}],"answer":"C","explanation":"设哥哥走t分钟，60(t+10)=90t，解得t=20，路程为90×20=1800米。","source":"math #66","bad":false,"notice":""},{"id":"m67","major":"数学题","minor":"方程应用","question":"小明有一些巧克力，第一天吃一半，第二天又吃剩下的一半，最后还剩1颗。原有多少颗？","options":[{"key":"A","text":"3颗"},{"key":"B","text":"5颗"},{"key":"C","text":"6颗"},{"key":"D","text":"4颗"}],"answer":"D","explanation":"倒推：第二天吃之前有2颗，第一天吃之前有4颗。","source":"math #67","bad":false,"notice":""},{"id":"m68","major":"数学题","minor":"方程应用","question":"小明有一些巧克力，先吃4颗，再把剩下的一半送人，自己还剩18颗。原有多少颗？","options":[{"key":"A","text":"40颗"},{"key":"B","text":"36颗"},{"key":"C","text":"44颗"},{"key":"D","text":"48颗"}],"answer":"A","explanation":"送人前剩36颗，因此原来有36+4=40颗。","source":"math #68","bad":false,"notice":""},{"id":"m69","major":"数学题","minor":"比例百分数","question":"两个三角形面积相等，底边之比为7∶8，高之比是多少？","options":[{"key":"A","text":"7∶7"},{"key":"B","text":"8∶7"},{"key":"C","text":"9∶7"},{"key":"D","text":"10∶7"}],"answer":"B","explanation":"面积相等时底×高相等，因此高与底成反比，高之比为8∶7。","source":"math #69","bad":false,"notice":""},{"id":"m70","major":"数学题","minor":"排列组合","question":"有4张数字卡片3、4、7、9，任选两张求和，和有多少种不同结果？","options":[{"key":"A","text":"5种"},{"key":"B","text":"7种"},{"key":"C","text":"6种"},{"key":"D","text":"8种"}],"answer":"C","explanation":"六组和分别为7、10、12、11、13、16，互不相同，共6种。","source":"math #70","bad":false,"notice":""},{"id":"m71","major":"数学题","minor":"方程应用","question":"如果今天是星期六，那么147天后是星期几？","options":[{"key":"A","text":"星期一"},{"key":"B","text":"星期六"},{"key":"C","text":"星期日"},{"key":"D","text":"星期四"}],"answer":"B","explanation":"147÷7=21，没有余数，所以星期不变。","source":"math #71","bad":false,"notice":""},{"id":"m72","major":"数学题","minor":"行程问题","question":"地铁检修车匀速行驶，每6分钟有一列同向地铁从后面追上，每2分钟有一列反向地铁迎面开来。两方向列车速度、发车间隔相同，发车间隔是多少？","options":[{"key":"A","text":"3分钟"},{"key":"B","text":"2分钟"},{"key":"C","text":"4分钟"},{"key":"D","text":"5分钟"}],"answer":"A","explanation":"设列车速度v、检修车速度u、相邻列车距离d，则d/(v-u)=6，d/(v+u)=2。解得u=v/2、d=3v，所以发车间隔d/v=3分钟。","source":"math #72","bad":false,"notice":""},{"id":"m73","major":"数学题","minor":"方程应用","question":"小明有88元买35支冰淇淋。买20支巧克力味和15支草莓味还差17元；买15支巧克力味和20支草莓味剩3元。草莓味每支多少元？","options":[{"key":"A","text":"1元"},{"key":"B","text":"2元"},{"key":"C","text":"3元"},{"key":"D","text":"4元"}],"answer":"B","explanation":"设巧克力、草莓单价为x、y。由20x+15y=105、15x+20y=85，解得y=2。","source":"math #73","bad":false,"notice":""},{"id":"m74","major":"数学题","minor":"方程应用","question":"3只玩具兔10元，5只玩具熊20元。幼儿园花70元买了18只玩具兔和玩具熊，其中玩具兔有多少只？","options":[{"key":"A","text":"2只"},{"key":"B","text":"4只"},{"key":"C","text":"3只"},{"key":"D","text":"5只"}],"answer":"C","explanation":"设兔有x只，熊18-x只。列式(10/3)x+4(18-x)=70，解得x=3。","source":"math #74","bad":false,"notice":""},{"id":"m75","major":"数学题","minor":"方程应用","question":"x、y为正整数，4x+3y=47。下列哪个数可能是y？","options":[{"key":"A","text":"8"},{"key":"B","text":"10"},{"key":"C","text":"11"},{"key":"D","text":"9"}],"answer":"D","explanation":"对选项逐一代入，y=9时4x=20，x=5为正整数。","source":"math #75","bad":false,"notice":""},{"id":"m76","major":"数学题","minor":"工程问题","question":"一项植树任务按每天200棵计划45天完成。如果每天多种25%，可提前多少天完成？","options":[{"key":"A","text":"9天"},{"key":"B","text":"8天"},{"key":"C","text":"10天"},{"key":"D","text":"11天"}],"answer":"A","explanation":"总量为200×45。提速后每天种250棵，需要36天，因此提前45-36=9天。","source":"math #76","bad":false,"notice":""},{"id":"m77","major":"数学题","minor":"数列规律","question":"找规律：100，81，64，49，36，（ ）。","options":[{"key":"A","text":"23"},{"key":"B","text":"25"},{"key":"C","text":"27"},{"key":"D","text":"29"}],"answer":"B","explanation":"各项依次是10²、9²、8²、7²、6²，下一项是5²=25。","source":"math #77","bad":false,"notice":""},{"id":"m78","major":"数学题","minor":"计数问题","question":"在一条长256米的直路一侧植树，每隔1米种1棵，两端都种，共需多少棵？","options":[{"key":"A","text":"231棵"},{"key":"B","text":"283棵"},{"key":"C","text":"257棵"},{"key":"D","text":"309棵"}],"answer":"C","explanation":"间隔数为256÷1=256，棵数比间隔数多1，所以是257棵。","source":"math #78","bad":false,"notice":""},{"id":"m79","major":"数学题","minor":"计数问题","question":"一盒乒乓球每次取5个黄球、3个白球，白球正好取完时还剩8个黄球；若每次取7个黄球、3个白球，黄球正好取完时还剩24个白球。盒中共有多少个球？","options":[{"key":"A","text":"238个"},{"key":"B","text":"290个"},{"key":"C","text":"316个"},{"key":"D","text":"264个"}],"answer":"D","explanation":"设两种取法分别进行k、m次，则黄球5k+8=7m，白球3k=3m+24。解得m=24、k=32，黄球168个、白球96个，共264个。","source":"math #79","bad":false,"notice":""},{"id":"m80","major":"数学题","minor":"利润经济","question":"某商品进价80元，按90元可卖400件。售价每提高1元，销量减少20件。利润最大时应定价多少元？","options":[{"key":"A","text":"95元"},{"key":"B","text":"85元"},{"key":"C","text":"105元"},{"key":"D","text":"115元"}],"answer":"A","explanation":"设提价x元，利润为(10+x)(400-20x)，整理为开口向下的二次函数，在x=5时最大，所以定价95元。","source":"math #80","bad":false,"notice":""},{"id":"m81","major":"数学题","minor":"工程问题","question":"甲单独完成工程需40天，乙需24天。乙先做12天后由甲完成，甲还需多少天？","options":[{"key":"A","text":"18天"},{"key":"B","text":"20天"},{"key":"C","text":"22天"},{"key":"D","text":"24天"}],"answer":"B","explanation":"乙12天完成12/24=1/2，剩余1/2由甲完成，需要40×1/2=20天。","source":"math #81","bad":false,"notice":""},{"id":"m82","major":"数学题","minor":"行程问题","question":"一列长90米的火车以30米/秒通过长1200米的隧道，需要多少秒？","options":[{"key":"A","text":"39秒"},{"key":"B","text":"47秒"},{"key":"C","text":"43秒"},{"key":"D","text":"51秒"}],"answer":"C","explanation":"火车完全通过需行驶1200+90=1290米，用时1290÷30=43秒。","source":"math #82","bad":false,"notice":""},{"id":"m83","major":"数学题","minor":"方程应用","question":"正数a、b的算术平均数是几何平均数的2倍，则a/b的值最接近哪个数？","options":[{"key":"A","text":"13"},{"key":"B","text":"15"},{"key":"C","text":"16"},{"key":"D","text":"14"}],"answer":"D","explanation":"令t=√(a/b)，由(a+b)/2=2√(ab)得t²-4t+1=0。较大的比值(2+√3)²≈13.93，最接近14。","source":"math #83","bad":false,"notice":""},{"id":"m84","major":"数学题","minor":"方程应用","question":"一本书从第1页至第300页连续编页码，数字“1”共出现多少次？","options":[{"key":"A","text":"120"},{"key":"B","text":"140"},{"key":"C","text":"160"},{"key":"D","text":"180"}],"answer":"","explanation":"个位1出现30次，十位1出现30次，百位1出现100次，合计160次。","source":"math #84","bad":true,"notice":"原题信息残缺或答案有争议，暂不参与计分。"},{"id":"m85","major":"数学题","minor":"利润经济","question":"一年前某股票价格为10元，一年内税后股息为0.25元，现在股价为12元。不计交易费用，一年收益率是多少？","options":[{"key":"A","text":"20.25%"},{"key":"B","text":"22.5%"},{"key":"C","text":"24.75%"},{"key":"D","text":"27%"}],"answer":"B","explanation":"收益包括价差2元和股息0.25元，总收益2.25元，相对最初10元的收益率为22.5%。","source":"math #85","bad":false,"notice":""},{"id":"m86","major":"数学题","minor":"比例百分数","question":"有40个气球，30%是红色，其余为黄色；黄色气球中1/4系了绳子。未系绳的黄色气球有多少个？","options":[{"key":"A","text":"19个"},{"key":"B","text":"23个"},{"key":"C","text":"21个"},{"key":"D","text":"25个"}],"answer":"C","explanation":"黄色有40×70%=28个，未系绳占3/4，所以有28×3/4=21个。","source":"math #86","bad":false,"notice":""},{"id":"m87","major":"数学题","minor":"概率","question":"两个独立安全系统的报警概率分别为0.93和0.96。至少一个系统报警的概率是多少？","options":[{"key":"A","text":"0.8972"},{"key":"B","text":"1.0972"},{"key":"C","text":"1.1972"},{"key":"D","text":"0.9972"}],"answer":"D","explanation":"用对立事件：1-(1-0.93)(1-0.96)=1-0.07×0.04=0.9972。","source":"math #87","bad":false,"notice":""},{"id":"m88","major":"数学题","minor":"方程应用","question":"用绳子测井深：绳子三折后长出井口4米，四折后长出井口1米。井深多少米？","options":[{"key":"A","text":"8米"},{"key":"B","text":"7米"},{"key":"C","text":"9米"},{"key":"D","text":"10米"}],"answer":"A","explanation":"设井深d、绳长L，则L=3(d+4)=4(d+1)，解得d=8。","source":"math #88","bad":false,"notice":""},{"id":"m89","major":"数学题","minor":"利润经济","question":"2013年1—6月商品房销售面积同比增长28.7%，销售额同比增长43.2%。商品房平均销售价格同比约增长多少？","options":[{"key":"A","text":"10.17%"},{"key":"B","text":"11.3%"},{"key":"C","text":"12.43%"},{"key":"D","text":"13.56%"}],"answer":"B","explanation":"平均价=销售额÷销售面积，增幅为1.432÷1.287-1≈11.3%。","source":"math #89","bad":false,"notice":""},{"id":"m90","major":"数学题","minor":"方程应用","question":"某省2006年城镇固定资产投资中，第一、第二、第三产业投资分别为15.45亿元、3439.08亿元、4019.17亿元。三者合计多少亿元？","options":[{"key":"A","text":"6726.33亿元"},{"key":"B","text":"8221.07亿元"},{"key":"C","text":"7473.7亿元"},{"key":"D","text":"8968.44亿元"}],"answer":"C","explanation":"直接相加：15.45+3439.08+4019.17=7473.70亿元。","source":"math #90","bad":false,"notice":""},{"id":"m91","major":"数学题","minor":"行程问题","question":"两校相距2760米，甲、乙分别以70米/分、110米/分从两校同时出发，到对方学校后立即返回。从出发到第二次相遇需多少分钟？","options":[{"key":"A","text":"41分钟"},{"key":"B","text":"51分钟"},{"key":"C","text":"56分钟"},{"key":"D","text":"46分钟"}],"answer":"D","explanation":"第二次相遇时两人合计行程为3个全程，即3×2760米。用时为8280÷(70+110)=46分钟。","source":"math #91","bad":false,"notice":""},{"id":"m92","major":"数学题","minor":"数列规律","question":"找规律：8/9，2/3，1/2，3/8，9/32，（ ）。","options":[{"key":"A","text":"27/128"},{"key":"B","text":"24/128"},{"key":"C","text":"30/128"},{"key":"D","text":"33/128"}],"answer":"A","explanation":"每一项都是前一项乘3/4，所以下一项为9/32×3/4=27/128。","source":"math #92","bad":false,"notice":""},{"id":"m93","major":"数学题","minor":"概率","question":"7个白球、3个红球随机分给5个人，每人2个球。3个红球分别由3个人得到的概率是多少？","options":[{"key":"A","text":"1/3"},{"key":"B","text":"2/3"},{"key":"C","text":"3/3"},{"key":"D","text":"4/3"}],"answer":"B","explanation":"把10个位置分成5组，每组2个。总选法C(10,3)=120；从5人中选3人且每人选1个位置，有C(5,3)×2³=80种，概率为80/120=2/3。","source":"math #93","bad":false,"notice":""},{"id":"m94","major":"数学题","minor":"计数问题","question":"钉子按4个0.25元买入，再按3个0.22元卖出，共获利2.6元。一共买了多少个钉子？","options":[{"key":"A","text":"216个"},{"key":"B","text":"264个"},{"key":"C","text":"240个"},{"key":"D","text":"288个"}],"answer":"C","explanation":"每个进价0.25÷4元，售价0.22÷3元，单个利润为13/1200元。2.6÷(13/1200)=240。","source":"math #94","bad":false,"notice":""},{"id":"m95","major":"数学题","minor":"年龄问题","question":"一家三口年龄和74岁，妈妈比爸爸小2岁，妈妈年龄是儿子的4倍。三人各多少岁？","options":[{"key":"A","text":"爸爸34岁、妈妈32岁、儿子8岁"},{"key":"B","text":"爸爸36岁、妈妈34岁、儿子4岁"},{"key":"C","text":"爸爸32岁、妈妈30岁、儿子12岁"},{"key":"D","text":"爸爸38岁、妈妈36岁、儿子0岁"}],"answer":"A","explanation":"设儿子x岁，则妈妈4x岁、爸爸4x+2岁。9x+2=74，解得x=8。","source":"math #95","bad":false,"notice":""},{"id":"m96","major":"数学题","minor":"利润经济","question":"某国1995年国民总收入为105亿元，总储蓄为75亿元。储蓄率约为多少？","options":[{"key":"A","text":"71.4%"},{"key":"B","text":"64.26%"},{"key":"C","text":"78.54%"},{"key":"D","text":"85.68%"}],"answer":"A","explanation":"储蓄率=总储蓄÷国民总收入=75÷105≈71.4%。","source":"math #96","bad":false,"notice":""},{"id":"m97","major":"数学题","minor":"方程应用","question":"车队运货：每车运3500千克还剩5000千克；每车运4000千克还剩500千克。车队有多少辆车？","options":[{"key":"A","text":"8辆"},{"key":"B","text":"9辆"},{"key":"C","text":"10辆"},{"key":"D","text":"11辆"}],"answer":"B","explanation":"两种装法的货物总量相等：3500n+5000=4000n+500，解得n=9。","source":"math #97","bad":false,"notice":""},{"id":"m98","major":"数学题","minor":"容斥原理","question":"100名村民从甲、乙、丙中选代表。已统计61票：甲35票、乙10票、丙16票。余下选票中甲至少再得多少票就一定当选？","options":[{"key":"A","text":"10票"},{"key":"B","text":"12票"},{"key":"C","text":"11票"},{"key":"D","text":"13票"}],"answer":"C","explanation":"若甲再得x票，最不利时其余39-x票全给当前第二名丙。要保证当选需35+x>16+39-x，解得x>10，所以至少11票。","source":"math #98","bad":false,"notice":""},{"id":"m99","major":"数学题","minor":"工程问题","question":"一项工程原计划300天完成。开工100天后，工作效率下降20%。工程比原计划推迟多少天？","options":[{"key":"A","text":"45天"},{"key":"B","text":"55天"},{"key":"C","text":"60天"},{"key":"D","text":"50天"}],"answer":"D","explanation":"前100天完成1/3，剩余原本需200天；效率降为80%后需200÷0.8=250天，因此推迟50天。","source":"math #99","bad":false,"notice":""},{"id":"m100","major":"数学题","minor":"几何问题","question":"平面内一个正方形有多少条对称轴？","options":[{"key":"A","text":"4条"},{"key":"B","text":"3条"},{"key":"C","text":"5条"},{"key":"D","text":"6条"}],"answer":"A","explanation":"两条对角线和两组对边中点的连线都是对称轴，共4条。","source":"math #100","bad":false,"notice":""},{"id":"m101","major":"数学题","minor":"概率","question":"两个独立报警器在紧急情况下发出信号的概率分别为0.95和0.92。至少一个报警的概率是多少？","options":[{"key":"A","text":"0.896"},{"key":"B","text":"0.996"},{"key":"C","text":"1.096"},{"key":"D","text":"1.196"}],"answer":"B","explanation":"两者都不报警的概率为0.05×0.08=0.004，所以至少一个报警的概率为1-0.004=0.996。","source":"math #101","bad":false,"notice":""},{"id":"m102","major":"数学题","minor":"数列规律","question":"找规律：1/2，-1/4，1/6，-1/8，（ ）。","options":[{"key":"A","text":"0/10"},{"key":"B","text":"2/10"},{"key":"C","text":"1/10"},{"key":"D","text":"3/10"}],"answer":"C","explanation":"分母是连续偶数2、4、6、8、10，正负号交替，下一项为1/10。","source":"math #102","bad":false,"notice":""},{"id":"m103","major":"数学题","minor":"方程应用","question":"计算：12.5×0.15×16。","options":[{"key":"A","text":"27"},{"key":"B","text":"33"},{"key":"C","text":"36"},{"key":"D","text":"30"}],"answer":"D","explanation":"先算12.5×16=200，再乘0.15，得到30。","source":"math #103","bad":false,"notice":""},{"id":"m104","major":"数学题","minor":"几何问题","question":"一个圆与一个三角形的边界最多有多少个交点？","options":[{"key":"A","text":"6个"},{"key":"B","text":"5个"},{"key":"C","text":"7个"},{"key":"D","text":"8个"}],"answer":"A","explanation":"圆与三角形的每条边最多有2个交点，3条边最多有3×2=6个交点。","source":"math #104","bad":false,"notice":""},{"id":"m105","major":"数学题","minor":"几何问题","question":"用长度一定的封闭曲线围图形，哪种形状围成的面积最大？","options":[{"key":"A","text":"圆形"},{"key":"B","text":"正方形"},{"key":"C","text":"菱形"},{"key":"D","text":"长方形"}],"answer":"A","explanation":"等周问题的结论是：在周长相同的平面图形中，圆的面积最大。","source":"math #105","bad":false,"notice":""},{"id":"m106","major":"数学题","minor":"方程应用","question":"计算0.7的5次方。","options":[{"key":"A","text":"0.06807"},{"key":"B","text":"0.26807"},{"key":"C","text":"0.16807"},{"key":"D","text":"0.36807"}],"answer":"C","explanation":"0.7⁵=7⁵/10⁵=16807/100000=0.16807。","source":"math #106","bad":false,"notice":""},{"id":"m107","major":"数学题","minor":"方程应用","question":"比较579/580、1427/1428和42/43的大小。","options":[{"key":"A","text":"1427/1428＞579/580＞42/43"},{"key":"B","text":"579/580＞1427/1428＞42/43"},{"key":"C","text":"42/43＞579/580＞1427/1428"},{"key":"D","text":"579/580＞42/43＞1427/1428"}],"answer":"A","explanation":"三个分数都可写成1减一个单位分数。1/1428最小、1/580次之、1/43最大，所以大小顺序如答案。","source":"math #107","bad":false,"notice":""},{"id":"m108","major":"数学题","minor":"行程问题","question":"甲、乙从A地到B地分别需30分钟和40分钟。甲比乙晚出发5分钟，甲出发多少分钟后追上乙？","options":[{"key":"A","text":"10分钟"},{"key":"B","text":"15分钟"},{"key":"C","text":"20分钟"},{"key":"D","text":"25分钟"}],"answer":"B","explanation":"设甲出发t分钟后追上，则乙已走t+5分钟。由t/30=(t+5)/40，解得t=15。","source":"math #108","bad":false,"notice":""},{"id":"m109","major":"数学题","minor":"排列组合","question":"制作一面国旗需要3种颜色，制作4面完全相同的国旗需要多少种颜色？","options":[{"key":"A","text":"2种"},{"key":"B","text":"3种"},{"key":"C","text":"4种"},{"key":"D","text":"5种"}],"answer":"B","explanation":"国旗数量增加不改变每面旗的配色种类，仍是3种。","source":"math #109","bad":false,"notice":""},{"id":"m110","major":"数学题","minor":"方程应用","question":"小罗、小宋、小王3人轮流下象棋，每局两人参赛，输者下一局休息。若小罗休息2局、小王下8局、小宋下5局，第9局是哪两人比赛？","options":[{"key":"A","text":"小罗和小宋"},{"key":"B","text":"小宋和小王"},{"key":"C","text":"小罗和小王"},{"key":"D","text":"无法确定"}],"answer":"C","explanation":"依据每局输者下一局休息，把各人的参赛与休息次数按局次排列，可锁定第9局参赛者为小罗和小王。","source":"math #110","bad":false,"notice":""},{"id":"m111","major":"数学题","minor":"利润经济","question":"某股票6月份下跌20%，6月30日收盘价为每股12元。5月31日收盘价是多少？","options":[{"key":"A","text":"13元"},{"key":"B","text":"17元"},{"key":"C","text":"19元"},{"key":"D","text":"15元"}],"answer":"D","explanation":"下跌后的价格是原价的80%，原价=12÷0.8=15元。","source":"math #111","bad":false,"notice":""},{"id":"m112","major":"数学题","minor":"工程问题","question":"甲、乙单独完成同一工程分别需40天、24天。乙先做12天，剩余由甲完成，甲还需多少天？","options":[{"key":"A","text":"20天"},{"key":"B","text":"18天"},{"key":"C","text":"22天"},{"key":"D","text":"24天"}],"answer":"A","explanation":"乙完成一半，剩余一半由甲做，需要40×1/2=20天。","source":"math #112","bad":false,"notice":""},{"id":"m113","major":"数学题","minor":"方程应用","question":"一个分数的分子不变，分母扩大到原来的8倍，分数值如何变化？","options":[{"key":"A","text":"扩大到原来的8倍"},{"key":"B","text":"缩小到原来的1/8"},{"key":"C","text":"缩小到原来的1/4"},{"key":"D","text":"大小不变"}],"answer":"B","explanation":"分母扩大8倍相当于整个分数除以8，因此新值是原来的1/8。","source":"math #113","bad":false,"notice":""},{"id":"m114","major":"数学题","minor":"方程应用","question":"a是b的2倍，b的3倍减1等于14。a是多少？","options":[{"key":"A","text":"9"},{"key":"B","text":"11"},{"key":"C","text":"10"},{"key":"D","text":"12"}],"answer":"C","explanation":"3b-1=14，得b=5，因此a=2b=10。","source":"math #114","bad":false,"notice":""},{"id":"m115","major":"数学题","minor":"方程应用","question":"比较4⁸、5⁷、6⁶、7⁵的大小，哪个最大？","options":[{"key":"A","text":"4⁷"},{"key":"B","text":"6⁷"},{"key":"C","text":"7⁷"},{"key":"D","text":"5⁷"}],"answer":"D","explanation":"计算或拆分比较：4⁸=65536，5⁷=78125，6⁶=46656，7⁵=16807，最大是5⁷。","source":"math #115","bad":false,"notice":""},{"id":"m116","major":"数学题","minor":"数列规律","question":"找规律：6，9，（ ），24，39。","options":[{"key":"A","text":"15"},{"key":"B","text":"13"},{"key":"C","text":"17"},{"key":"D","text":"19"}],"answer":"A","explanation":"相邻差依次为3、6、9、15，可看作前两差之和生成后一差；缺项为9+6=15。","source":"math #116","bad":false,"notice":""},{"id":"m117","major":"数学题","minor":"方程应用","question":"计算1996+1997+1998+1999+2000。","options":[{"key":"A","text":"8991"},{"key":"B","text":"9990"},{"key":"C","text":"10989"},{"key":"D","text":"11988"}],"answer":"B","explanation":"五个连续整数的平均数是1998，总和为1998×5=9990。","source":"math #117","bad":false,"notice":""},{"id":"m118","major":"数学题","minor":"几何问题","question":"边长40米的正方形，将边长增加20米后，面积增加多少平方米？","options":[{"key":"A","text":"1800平方米"},{"key":"B","text":"2200平方米"},{"key":"C","text":"2000平方米"},{"key":"D","text":"2400平方米"}],"answer":"C","explanation":"新面积60²，原面积40²，增加3600-1600=2000平方米。","source":"math #118","bad":false,"notice":""},{"id":"m119","major":"数学题","minor":"计数问题","question":"有10瓶啤酒，喝完后每3个空瓶可换1瓶啤酒。最多能喝多少瓶？","options":[{"key":"A","text":"13瓶"},{"key":"B","text":"15瓶"},{"key":"C","text":"16瓶"},{"key":"D","text":"14瓶"}],"answer":"D","explanation":"10个空瓶先换3瓶，剩1个；喝完后有4个空瓶，再换1瓶，最终剩2个空瓶，共喝10+3+1=14瓶。","source":"math #119","bad":false,"notice":""},{"id":"m120","major":"数学题","minor":"方程应用","question":"下列哪个分数大于4/5且小于5/6？","options":[{"key":"A","text":"49/60"},{"key":"B","text":"44/60"},{"key":"C","text":"54/60"},{"key":"D","text":"59/60"}],"answer":"A","explanation":"通分得4/5=48/60、5/6=50/60，所以49/60符合。","source":"math #120","bad":false,"notice":""},{"id":"m121","major":"数学题","minor":"工程问题","question":"修建水库，甲村单独投资还缺92万元，乙村单独投资还缺88万元，两村合作仍缺20万元。总投资是多少？","options":[{"key":"A","text":"144万元"},{"key":"B","text":"160万元"},{"key":"C","text":"176万元"},{"key":"D","text":"192万元"}],"answer":"B","explanation":"设总投资x万元，(x-92)+(x-88)=x-20，解得x=160。","source":"math #121","bad":false,"notice":""},{"id":"m122","major":"数学题","minor":"容斥原理","question":"从3、5、7、11这4个质数中至少选1个相乘，可以得到多少个不同的积？","options":[{"key":"A","text":"13个"},{"key":"B","text":"17个"},{"key":"C","text":"15个"},{"key":"D","text":"19个"}],"answer":"C","explanation":"不同质数的乘积能唯一对应所选质数集合，因此不同积的数量等于4个元素的非空子集数2⁴-1=15。","source":"math #122","bad":false,"notice":""},{"id":"m123","major":"数学题","minor":"方程应用","question":"甲、乙两数之和为456，甲的末位是5，去掉末位5后所得数等于乙。甲是多少？","options":[{"key":"A","text":"373"},{"key":"B","text":"457"},{"key":"C","text":"499"},{"key":"D","text":"415"}],"answer":"D","explanation":"设乙为x，则甲为10x+5。由10x+5+x=456，得x=41，所以甲为415。","source":"math #123","bad":false,"notice":""},{"id":"m124","major":"数学题","minor":"方程应用","question":"计算1+2+3+…+999。","options":[{"key":"A","text":"499500"},{"key":"B","text":"449550"},{"key":"C","text":"549450"},{"key":"D","text":"599400"}],"answer":"A","explanation":"等差数列求和：(1+999)×999÷2=499500。","source":"math #124","bad":false,"notice":""},{"id":"m125","major":"数学题","minor":"排列组合","question":"从6个不同颜色的球中依次取出2个且不放回，有多少种不同取法？","options":[{"key":"A","text":"27种"},{"key":"B","text":"30种"},{"key":"C","text":"33种"},{"key":"D","text":"36种"}],"answer":"B","explanation":"第一次有6种选择，第二次有5种，按顺序共有6×5=30种。","source":"math #125","bad":false,"notice":""},{"id":"m126","major":"数学题","minor":"数列规律","question":"找规律：1，8，9，（ ），25。","options":[{"key":"A","text":"58"},{"key":"B","text":"70"},{"key":"C","text":"64"},{"key":"D","text":"76"}],"answer":"C","explanation":"奇数位置是1²、3²、5²，偶数位置是2³、4³，所以缺项为4³=64。","source":"math #126","bad":false,"notice":""},{"id":"m127","major":"数学题","minor":"利润经济","question":"用2万元购买甲、乙股票，投资额之比4∶1。甲每股8元、乙每股4元；卖出时分别为10元、3元。共获利多少元？","options":[{"key":"A","text":"2700元"},{"key":"B","text":"3300元"},{"key":"C","text":"3600元"},{"key":"D","text":"3000元"}],"answer":"D","explanation":"甲投入16000元买2000股，获利4000元；乙投入4000元买1000股，亏损1000元，净获利3000元。","source":"math #127","bad":false,"notice":""},{"id":"m128","major":"数学题","minor":"方程应用","question":"一只青蛙在10米深的井底，每次向上跳5米又下滑4米。最后一次跳出井口后不再下滑，至少需要跳几次？","options":[{"key":"A","text":"6K"},{"key":"B","text":"9M dD. 10K"},{"key":"C","text":"以上都不正确"},{"key":"D","text":"以上都不正确"}],"answer":"A","explanation":"每次未跳出前净上升1米，第6次起跳位置为5米，一跳5米到井口，所以共6次。","source":"math #128","bad":false,"notice":""},{"id":"m129","major":"数学题","minor":"利润经济","question":"若某股票的一年前的价格为10元一年中的税后股息为025现在的市价为12元。 在不考虑交易费用的情况下一年内该股票的收益率为 ()。 hA. 20%W","options":[{"key":"A","text":"7"},{"key":"B","text":"8"},{"key":"C","text":"9"},{"key":"D","text":"10"}],"answer":"B","explanation":"本题考查利润经济。分别写出成本、售价、数量与利润之间的关系，再比较或求极值。计算结果为“8”，因此选择B。","source":"math #129","bad":false,"notice":""},{"id":"m130","major":"数学题","minor":"方程应用","question":"两个正数的等差中项为15，等比中项为12。两数之差的绝对值是多少？","options":[{"key":"A","text":"16"},{"key":"B","text":"20"},{"key":"C","text":"18"},{"key":"D","text":"22"}],"answer":"C","explanation":"设两数x、y，则x+y=30、xy=144。(x-y)²=(x+y)²-4xy=900-576=324，所以差为18。","source":"math #130","bad":false,"notice":""},{"id":"m131","major":"数学题","minor":"方程应用","question":"共有200人具中有50火买","options":[{"key":"A","text":"产品40人"},{"key":"B","text":"产品75人"},{"key":"C","text":"产品60人"},{"key":"D","text":"产品85人产品已知15人既买了"}],"answer":"A","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“产品40人”，因此选择A。","source":"math #131","bad":true,"notice":"原题信息残缺或答案有争议，暂不参与计分。"},{"id":"m132","major":"数学题","minor":"年龄问题","question":"10年前父亲年龄是女儿的7倍，15年后父亲年龄是女儿的2倍。女儿现在多少岁？","options":[{"key":"A","text":"15岁"},{"key":"B","text":"13岁"},{"key":"C","text":"17岁"},{"key":"D","text":"19岁"}],"answer":"A","explanation":"设父亲、女儿现在F、D岁。F-10=7(D-10)，F+15=2(D+15)，联立解得D=15。","source":"math #132","bad":false,"notice":""},{"id":"m133","major":"数学题","minor":"容斥原理","question":"某出版社新招10名英文、法文、日文编辑。只有小李同时会英文和日文，其余每人只会一种。会法文的比会英文的多4人，且是会日文人数的2倍。只会英文的有几人？","options":[{"key":"A","text":"0人"},{"key":"B","text":"1人"},{"key":"C","text":"2人"},{"key":"D","text":"3人"}],"answer":"B","explanation":"设会英文、法文、日文人数为E、F、J。因小李被重复计算一次，E+F+J=11；又F=E+4=2J。解得E=2、F=6、J=3，只会英文的为E-1=1人。","source":"math #133","bad":false,"notice":""},{"id":"m134","major":"数学题","minor":"计数问题","question":"某城市9月平均气温为28.5℃，且最热日与最冷日的平均气温相差不超过10℃。平均气温不低于30℃的日子最多有多少天？","options":[{"key":"A","text":"23天"},{"key":"B","text":"27天"},{"key":"C","text":"25天"},{"key":"D","text":"29天"}],"answer":"C","explanation":"要让高温天数尽量多，可令高温日为30℃、其余日为20℃。由(30n+20(30-n))/30≤28.5得n≤25.5，因此最多25天。","source":"math #134","bad":false,"notice":""},{"id":"m135","major":"数学题","minor":"方程应用","question":"甲、乙、丙进行1000米赛跑。甲到终点时乙还差100米，丙比乙再落后90米。若甲比乙早到18秒，乙比丙早到多少秒？","options":[{"key":"A","text":"18秒"},{"key":"B","text":"22秒"},{"key":"C","text":"24秒"},{"key":"D","text":"20秒"}],"answer":"D","explanation":"甲到终点时，乙、丙分别跑900米、810米，速度比为1∶0.9∶0.81。由甲比乙早18秒可得甲用时162秒、乙180秒、丙200秒，乙比丙早20秒。","source":"math #135","bad":false,"notice":""},{"id":"m136","major":"数学题","minor":"数列规律","question":"找规律：0，7，26，63，（ ）。","options":[{"key":"A","text":"124"},{"key":"B","text":"112"},{"key":"C","text":"136"},{"key":"D","text":"148"}],"answer":"A","explanation":"各项依次为1³-1、2³-1、3³-1、4³-1，下一项为5³-1=124。","source":"math #136","bad":false,"notice":""},{"id":"m137","major":"数学题","minor":"方程应用","question":"计算：25×44+99-110。","options":[{"key":"A","text":"980"},{"key":"B","text":"1089"},{"key":"C","text":"1198"},{"key":"D","text":"1307"}],"answer":"B","explanation":"25×44=1100，1100+99-110=1089。","source":"math #137","bad":false,"notice":""},{"id":"m138","major":"数学题","minor":"数论问题","question":"树上有8只鸟，猎人开枪打中2只，其余鸟都飞走了。树上还剩几只活鸟？","options":[{"key":"A","text":"-1只"},{"key":"B","text":"1只"},{"key":"C","text":"0只"},{"key":"D","text":"2只"}],"answer":"C","explanation":"枪响后没有被打中的鸟会飞走，因此树上不剩活鸟。","source":"math #138","bad":false,"notice":""},{"id":"m139","major":"数学题","minor":"方程应用","question":"求199、202、207、192、200的平均数。","options":[{"key":"A","text":"180"},{"key":"B","text":"220"},{"key":"C","text":"240"},{"key":"D","text":"200"}],"answer":"D","explanation":"五个数的和为1000，平均数为1000÷5=200。","source":"math #139","bad":false,"notice":""},{"id":"m140","major":"数学题","minor":"容斥原理","question":"某校100人，60人参加外语社团，72人参加计算机社团，其中8人只参加外语社团。只参加计算机社团的有多少人？","options":[{"key":"A","text":"20人"},{"key":"B","text":"18人"},{"key":"C","text":"22人"},{"key":"D","text":"24人"}],"answer":"A","explanation":"两社团都参加的有60-8=52人，只参加计算机的有72-52=20人。","source":"math #140","bad":false,"notice":""},{"id":"m141","major":"数学题","minor":"几何问题","question":"一个长方形分成9个小长方形，左上、左下、右上角面积分别为8、12、18。右下角面积是多少？","options":[{"key":"A","text":"24"},{"key":"B","text":"27"},{"key":"C","text":"30"},{"key":"D","text":"33"}],"answer":"B","explanation":"四角面积满足左上×右下=左下×右上，因此右下=12×18÷8=27。","source":"math #141","bad":false,"notice":""},{"id":"m142","major":"数学题","minor":"数论问题","question":"最小的正整数中，除以11余10，除以13余8的是多少？","options":[{"key":"A","text":"19"},{"key":"B","text":"23"},{"key":"C","text":"21"},{"key":"D","text":"25"}],"answer":"C","explanation":"21÷11余10，21÷13余8，且它是满足条件的最小正整数。","source":"math #142","bad":false,"notice":""},{"id":"m143","major":"数学题","minor":"方程应用","question":"计算：(2/3-1/2)÷(11/24)。","options":[{"key":"A","text":"3/11"},{"key":"B","text":"5/11"},{"key":"C","text":"6/11"},{"key":"D","text":"4/11"}],"answer":"D","explanation":"括号内为1/6，再除以11/24等于1/6×24/11=4/11。","source":"math #143","bad":false,"notice":""},{"id":"m144","major":"数学题","minor":"方程应用","question":"某工厂男工人数是女工人数的1/3，女工比男工多380人。全厂共有多少人？","options":[{"key":"A","text":"760人"},{"key":"B","text":"684人"},{"key":"C","text":"836人"},{"key":"D","text":"912人"}],"answer":"A","explanation":"设男工x人、女工3x人，则3x-x=380，x=190，总人数4x=760。","source":"math #144","bad":false,"notice":""},{"id":"m145","major":"数学题","minor":"方程应用","question":"出租车起步10公里收费10.4元，超过10公里的部分每公里加收1.6元，乘车20公里应付多少元？","options":[{"key":"A","text":"26"},{"key":"B","text":"20"},{"key":"C","text":"20.°8"},{"key":"D","text":"26.4 sh"}],"answer":"D","explanation":"10.4＋(20－10)×1.6＝26.4元。","source":"math #145","bad":false,"notice":""},{"id":"m146","major":"数学题","minor":"方程应用","question":"计算：1/(12×13)+1/(13×14)+…+1/(19×20)。","options":[{"key":"A","text":"0/30"},{"key":"B","text":"2/30"},{"key":"C","text":"1/30"},{"key":"D","text":"3/30"}],"answer":"C","explanation":"利用1/[n(n+1)]=1/n-1/(n+1)，各项相消后只剩1/12-1/20=1/30。","source":"math #146","bad":false,"notice":""},{"id":"m147","major":"数学题","minor":"方程应用","question":"一共100道选挂题 》 对一道1分,、 错一道0.5分, 得分:91分, 共错几道 (Ad","options":[{"key":"B","text":"5"},{"key":"C","text":"6"},{"key":"D","text":"7 S"}],"answer":"C","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“6”，因此选择C。","source":"math #147","bad":false,"notice":""},{"id":"m148","major":"数学题","minor":"方程应用","question":"用绳子测井深：三折后长出井口4米，四折后长出井口1米。井深多少米？","options":[{"key":"A","text":"8米"},{"key":"B","text":"7米"},{"key":"C","text":"9米"},{"key":"D","text":"10米"}],"answer":"A","explanation":"绳长满足3(d+4)=4(d+1)，解得井深d=8米。","source":"math #148","bad":false,"notice":""},{"id":"m149","major":"数学题","minor":"几何问题","question":"一个圆与一个三角形的边界最多有多少个交点？","options":[{"key":"A","text":"5个"},{"key":"B","text":"6个"},{"key":"C","text":"7个"},{"key":"D","text":"8个"}],"answer":"B","explanation":"每条边与圆最多有2个交点，三条边最多6个。","source":"math #149","bad":false,"notice":""},{"id":"m150","major":"数学题","minor":"年龄问题","question":"哥哥和弟弟今年年龄和55岁。曾有一年，哥哥当时年龄等于弟弟今年年龄，且是弟弟当时年龄的2倍。哥哥今年多少岁？","options":[{"key":"A","text":"30岁"},{"key":"B","text":"36岁"},{"key":"C","text":"33岁"},{"key":"D","text":"39岁"}],"answer":"C","explanation":"设哥哥x岁，按年龄差建立方程55-x=2(110-3x)，解得x=33。","source":"math #150","bad":false,"notice":""},{"id":"m151","major":"数学题","minor":"比例百分数","question":"小王参加了五门百分制的测验, 每门成绩都是敷数, 典中语文94分, 数学的得分最商, 外语的得分等于语文和物理的平均分, 物理的得分等于五门的平均分, 化学的得分比外语多2分, 并且是五门中第二高的得分, 问小王的物理考了多少分?","options":[{"key":"A","text":"94"},{"key":"B","text":"95"},{"key":"C","text":"96"},{"key":"D","text":"97"}],"answer":"C","explanation":"本题考查比例百分数。把基准量设为1份或100%，按对应比例换算。计算结果为“96”，因此选择C。","source":"math #151","bad":true,"notice":"原题信息残缺或答案有争议，暂不参与计分。"},{"id":"m152","major":"数学题","minor":"数论问题","question":"某单位四个兴趣组中，羽毛球人数是乒乓球的2倍，足球人数是篮球的3倍，乒乓球人数的4倍等于其余三组人数之和。羽毛球人数等于什么？","options":[{"key":"A","text":"足球组的1.5倍"},{"key":"B","text":"篮球组的3倍"},{"key":"C","text":"足球组与篮球组人数之和"},{"key":"D","text":"乒乓球组与足球组人数之和"}],"answer":"C","explanation":"设乒乓球p、篮球b，则羽毛球2p、足球3b。由4p=2p+b+3b得p=2b，所以羽毛球4b，恰等于足球3b与篮球b之和。","source":"math #152","bad":false,"notice":""},{"id":"m153","major":"数学题","minor":"方程应用","question":"一个班排队：3人一排比2人一排少9排，4人一排比3人一排少5排。若5人一排，共有多少排？","options":[{"key":"A","text":"10排"},{"key":"B","text":"11排"},{"key":"C","text":"12排"},{"key":"D","text":"13排"}],"answer":"B","explanation":"55人时，2人一排需28排、3人一排需19排，相差9排；4人一排14排，再少5排；5人一排正好11排。","source":"math #153","bad":false,"notice":""},{"id":"m154","major":"数学题","minor":"利润经济","question":"用2万元按4∶1购买甲、乙股票，甲每股8元、乙每股4元。后来分别以10元、3元卖出，共获利多少？","options":[{"key":"A","text":"2700元"},{"key":"B","text":"3300元"},{"key":"C","text":"3000元"},{"key":"D","text":"3600元"}],"answer":"C","explanation":"甲获利2000×2=4000元，乙亏损1000×1=1000元，净获利3000元。","source":"math #154","bad":false,"notice":""},{"id":"m155","major":"数学题","minor":"排列组合","question":"黄、白、蓝三个球从左到右排列，有多少种不同排法？","options":[{"key":"A","text":"5种"},{"key":"B","text":"7种"},{"key":"C","text":"8种"},{"key":"D","text":"6种"}],"answer":"D","explanation":"三个不同元素全排列共有3!=6种。","source":"math #155","bad":false,"notice":""},{"id":"m156","major":"数学题","minor":"几何问题","question":"一个边长2米的正方体上叠放一个边长1米的正方体，底面和接触面不粉刷。需要粉刷的外表面积是多少？","options":[{"key":"A","text":"24平方米"},{"key":"B","text":"22平方米"},{"key":"C","text":"26平方米"},{"key":"D","text":"28平方米"}],"answer":"A","explanation":"大正方体外露面积为16+3=19平方米，小正方体外露5个面共5平方米，总计24平方米。","source":"math #156","bad":false,"notice":""},{"id":"m157","major":"数学题","minor":"数论问题","question":"求1～100中所有能被5整除的数之和。","options":[{"key":"A","text":"945"},{"key":"B","text":"1050"},{"key":"C","text":"1155"},{"key":"D","text":"1260"}],"answer":"B","explanation":"这些数是5、10、…、100，共20项，和为(5+100)×20÷2=1050。","source":"math #157","bad":false,"notice":""},{"id":"m158","major":"数学题","minor":"行程问题","question":"小张、小王同时从A地骑摩托车去B地，速度分别为40千米/时、48千米/时。小王到B地后立即返回，15分钟后与小张相遇。AB相距多少千米？","options":[{"key":"A","text":"119千米"},{"key":"B","text":"145千米"},{"key":"C","text":"132千米"},{"key":"D","text":"158千米"}],"answer":"C","explanation":"相遇时小王已返程12千米，小张距B地也为12千米，两人路程差24千米。速度差8千米/时，所以已行3小时；AB距离为48×3-12=132千米。","source":"math #158","bad":false,"notice":""},{"id":"m159","major":"数学题","minor":"方程应用","question":"两仁水桶共盛40斤水, 如果把第一桶里的8斤水倒入第二个水桶里, 两个水梓里的水就一样多, 第二桶水重多少斤?() ai","options":[{"key":"A","text":"21"},{"key":"B","text":"18"},{"key":"C","text":"12"},{"key":"D","text":"10"}],"answer":"C","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“12”，因此选择C。","source":"math #159","bad":false,"notice":""},{"id":"m160","major":"数学题","minor":"数论问题","question":"一根绳子先剪去2米，再剪去剩余的一半，最后还剩5米。原长多少米？","options":[{"key":"A","text":"12米"},{"key":"B","text":"11米"},{"key":"C","text":"13米"},{"key":"D","text":"14米"}],"answer":"A","explanation":"第二次剪之前有10米，第一次剪之前有10+2=12米。","source":"math #160","bad":false,"notice":""},{"id":"m161","major":"数学题","minor":"方程应用","question":"一桶油连桶重100千克，倒去一半油后连桶重45千克。下列判断正确的是？","options":[{"key":"A","text":"桶重10千克"},{"key":"B","text":"桶重20千克"},{"key":"C","text":"桶重45千克"},{"key":"D","text":"题目条件矛盾"}],"answer":"D","explanation":"设油重x、桶重y，则x+y=100、x/2+y=45，相减得x=110、y=-10。桶重不可能为负数，因此原数据不合理。","source":"math #161","bad":false,"notice":""},{"id":"m162","major":"数学题","minor":"数论问题","question":"一本100多页的书被撕掉4张纸（共8个页码），剩余页码总和为8037。这本书最多有多少页？","options":[{"key":"A","text":"121页"},{"key":"B","text":"147页"},{"key":"C","text":"134页"},{"key":"D","text":"160页"}],"answer":"C","explanation":"计算前n个页码总和，并检查被撕去的4张纸所对应的8个页码。n=134时总和9045，与8037相差1008，可由4张纸的页码组成；再增页数则不满足。","source":"math #162","bad":false,"notice":""},{"id":"m163","major":"数学题","minor":"概率","question":"从长度为1、2、3、4、5、6的6根小棒中任取3根，能组成三角形的概率是多少？","options":[{"key":"A","text":"6/20"},{"key":"B","text":"8/20"},{"key":"C","text":"9/20"},{"key":"D","text":"7/20"}],"answer":"D","explanation":"总取法C(6,3)=20。逐组检验两短边之和大于最长边，符合的有7组，概率7/20。","source":"math #163","bad":false,"notice":""},{"id":"m164","major":"数学题","minor":"数列规律","question":"找规律：1，-1/2，1/3，-1/4，1/5，（ ）。","options":[{"key":"A","text":"-1/6"},{"key":"B","text":"-2/6"},{"key":"C","text":"0/6"},{"key":"D","text":"1/6"}],"answer":"A","explanation":"分母依次加1，正负号交替，所以下一项为-1/6。","source":"math #164","bad":false,"notice":""},{"id":"m165","major":"数学题","minor":"方程应用","question":"从10:15到16:45经过了多长时间？","options":[{"key":"A","text":"5小时30分钟"},{"key":"B","text":"6小时30分钟"},{"key":"C","text":"7小时30分钟"},{"key":"D","text":"8小时30分钟"}],"answer":"B","explanation":"10:15到16:15是6小时，再到16:45是30分钟。","source":"math #165","bad":false,"notice":""},{"id":"m166","major":"数学题","minor":"方程应用","question":"分数1/3的分子不变，分母扩大到原来的3倍，分数值如何变化？","options":[{"key":"A","text":"扩大到原来的3倍"},{"key":"B","text":"缩小到原来的1/3"},{"key":"C","text":"缩小到原来的1/9"},{"key":"D","text":"大小不变"}],"answer":"B","explanation":"新分数为1/9，而(1/9)÷(1/3)=1/3。","source":"math #166","bad":false,"notice":""},{"id":"m167","major":"数学题","minor":"排列组合","question":"48支足球队平均分成8组，每组内单循环赛。初赛共比赛多少场？","options":[{"key":"A","text":"108场"},{"key":"B","text":"132场"},{"key":"C","text":"144场"},{"key":"D","text":"120场"}],"answer":"D","explanation":"每组6队，单循环有C(6,2)=15场，8组共15×8=120场。","source":"math #167","bad":false,"notice":""},{"id":"m168","major":"数学题","minor":"方程应用","question":"375, 127,248,121, ¢)","options":[{"key":"A","text":"369"},{"key":"B","text":"127"},{"key":"C","text":"127: 颂 -369"},{"key":"D","text":"以上都不正确"}],"answer":"A","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“369”，因此选择A。","source":"math #168","bad":false,"notice":""},{"id":"m169","major":"数学题","minor":"数列规律","question":"找规律：10，17，（ ），37。","options":[{"key":"A","text":"23"},{"key":"B","text":"26"},{"key":"C","text":"29"},{"key":"D","text":"32"}],"answer":"B","explanation":"相邻增量依次为7、9、11，所以缺项为17+9=26。","source":"math #169","bad":false,"notice":""},{"id":"m170","major":"数学题","minor":"利润经济","question":"将进货单价为80元的商品拯90元售出时, 能卖出400个, 已知这种商品每涨价1元, 共销售量就要减少20个, 为了获得最大利涧, 每个售价应定为","options":[{"key":"A","text":"95"},{"key":"B","text":"100"},{"key":"C","text":"105"},{"key":"D","text":"110"}],"answer":"A","explanation":"本题考查利润经济。分别写出成本、售价、数量与利润之间的关系，再比较或求极值。计算结果为“95”，因此选择A。","source":"math #170","bad":false,"notice":""},{"id":"m171","major":"数学题","minor":"排列组合","question":"现有1分、2分、5分、1角、5角、1元硬币各1枚，至少使用1枚，可组成多少种不同币值？","options":[{"key":"A","text":"57种"},{"key":"B","text":"69种"},{"key":"C","text":"75种"},{"key":"D","text":"63种"}],"answer":"D","explanation":"各面值均大于之前所有小面值之和，因此不同子集的币值不同。6枚硬币的非空子集数为2⁶-1=63。","source":"math #171","bad":false,"notice":""},{"id":"m172","major":"数学题","minor":"方程应用","question":"中午12点时针与分针重合，到下一个中午12点之前，两针共重合多少次？","options":[{"key":"A","text":"11次"},{"key":"B","text":"10次"},{"key":"C","text":"12次"},{"key":"D","text":"13次"}],"answer":"A","explanation":"分针相对时针每12/11小时追上一圈，因此12小时内重合11次。","source":"math #172","bad":false,"notice":""},{"id":"m173","major":"数学题","minor":"计数问题","question":"有10个空酒瓶，每3个空瓶可换1瓶酒；允许最后借1个空瓶并在喝完后归还。最多能喝几瓶？","options":[{"key":"A","text":"4瓶"},{"key":"B","text":"5瓶"},{"key":"C","text":"6瓶"},{"key":"D","text":"7瓶"}],"answer":"B","explanation":"10个空瓶换3瓶，喝完后有4个；再换1瓶后剩2个，借1个换1瓶，喝完归还借来的空瓶，共5瓶。","source":"math #173","bad":false,"notice":""},{"id":"m174","major":"数学题","minor":"方程应用","question":"32, 27, 23, 20, eX","options":[{"key":"A","text":"4"},{"key":"B","text":"6"},{"key":"C","text":"5"},{"key":"D","text":"7"}],"answer":"C","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“5”，因此选择C。","source":"math #174","bad":false,"notice":""},{"id":"m175","major":"数学题","minor":"方程应用","question":"某校1000人，男女比6∶4，教师与学生比2∶8。若男教师100人，女学生有多少人？","options":[{"key":"A","text":"270人"},{"key":"B","text":"330人"},{"key":"C","text":"360人"},{"key":"D","text":"300人"}],"answer":"D","explanation":"全校女性400人，教师200人。男教师100人，则女教师100人，女学生400-100=300人。","source":"math #175","bad":false,"notice":""},{"id":"m176","major":"数学题","minor":"几何问题","question":"宽为2a的长方形铁片，两边各向上折起x形成矩形水槽。x为何值时截面积最大？","options":[{"key":"A","text":"a/4"},{"key":"B","text":"a/3"},{"key":"C","text":"a/2"},{"key":"D","text":"2a/3"}],"answer":"C","explanation":"截面积x(2a-2x)是开口向下的二次函数，顶点在x=a/2。","source":"math #176","bad":false,"notice":""},{"id":"m177","major":"数学题","minor":"方程应用","question":"23支队伍参加单淘汰赛，每轮两两比赛，队伍数为奇数时有1队轮空。整个赛事共出现几次轮空？","options":[{"key":"A","text":"1次"},{"key":"B","text":"2次"},{"key":"C","text":"3次"},{"key":"D","text":"4次"}],"answer":"B","explanation":"23队首轮有1次轮空，晋级后12队；12→6→3，3队这一轮再有1次轮空，之后2→1，共2次。","source":"math #177","bad":false,"notice":""},{"id":"m178","major":"数学题","minor":"方程应用","question":"33÷70所得小数的小数点后第1000位数字是多少？","options":[{"key":"A","text":"3"},{"key":"B","text":"5"},{"key":"C","text":"4"},{"key":"D","text":"6"}],"answer":"C","explanation":"33/70=0.4(714285)循环。除去首位4后，循环节长6；第1000位对应循环节第3位，数字为4。","source":"math #178","bad":false,"notice":""},{"id":"m179","major":"数学题","minor":"方程应用","question":"求199、202、207、192、200的平均数。","options":[{"key":"A","text":"180"},{"key":"B","text":"220"},{"key":"C","text":"240"},{"key":"D","text":"200"}],"answer":"D","explanation":"五个数的和是1000，平均数为1000÷5=200。","source":"math #179","bad":false,"notice":""},{"id":"m180","major":"数学题","minor":"计数问题","question":"晴天浇水量是阴天的2.5倍。满箱水若天天晴可用18天；6月30天晴阴相间后恰好用完。6月有多少个阴天？","options":[{"key":"A","text":"20天"},{"key":"B","text":"18天"},{"key":"C","text":"22天"},{"key":"D","text":"24天"}],"answer":"A","explanation":"以阴天用水量为1，水箱容量为18×2.5=45。设阴天x天，则x+2.5(30-x)=45，解得x=20。","source":"math #180","bad":false,"notice":""},{"id":"m181","major":"数学题","minor":"工程问题","question":"甲村单独修坝缺92万元，乙村单独修缺88万元，两村合作仍缺20万元。修坝需多少万元？","options":[{"key":"A","text":"144万元"},{"key":"B","text":"160万元"},{"key":"C","text":"176万元"},{"key":"D","text":"192万元"}],"answer":"B","explanation":"设总额x，列式(x-92)+(x-88)=x-20，解得x=160。","source":"math #181","bad":false,"notice":""},{"id":"m182","major":"数学题","minor":"方程应用","question":"最小的两位数、三位数和四位数相加，结果是多少？","options":[{"key":"A","text":"999"},{"key":"B","text":"1221"},{"key":"C","text":"1110"},{"key":"D","text":"1332"}],"answer":"C","explanation":"10+100+1000=1110。","source":"math #182","bad":false,"notice":""},{"id":"m183","major":"数学题","minor":"方程应用","question":"题目规定纽约时间比香港时间快13小时。香港6月1日20:00打电话，纽约是几点？","options":[{"key":"A","text":"5月2日9:00"},{"key":"B","text":"7月2日9:00"},{"key":"C","text":"8月2日9:00"},{"key":"D","text":"6月2日9:00"}],"answer":"D","explanation":"按题目给定时差，纽约时间为香港时间加13小时，即次日9:00。","source":"math #183","bad":false,"notice":""},{"id":"m184","major":"数学题","minor":"方程应用","question":"翻日历,: 翎了7张, 和加起来77, 问这一天是几号? al4号、","options":[{"key":"B","text":"1l3号"},{"key":"C","text":"15号、 dl17号"}],"answer":"C","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“15号、 dl17号”，因此选择C。","source":"math #184","bad":false,"notice":""},{"id":"m185","major":"数学题","minor":"计数问题","question":"在公路一侧植树。每隔3米种1棵会多3棵树，每隔2.5米种1棵会缺37棵树，两端都种。公路长多少米？","options":[{"key":"A","text":"540米"},{"key":"B","text":"600米"},{"key":"C","text":"660米"},{"key":"D","text":"720米"}],"answer":"B","explanation":"设路长L、现有树N，则N=L/3+1+3=L/2.5+1-37。解得L=600米。","source":"math #185","bad":false,"notice":""},{"id":"m186","major":"数学题","minor":"数论问题","question":"一本100多页的书被撕掉4张纸，剩余页码数字之和为8037。这本书最多有多少页？","options":[{"key":"A","text":"121页"},{"key":"B","text":"147页"},{"key":"C","text":"134页"},{"key":"D","text":"160页"}],"answer":"C","explanation":"逐一检查100多页时的页码总和与4张纸对应的8个页码。134页的总和为9045，减去相应8个页码后可得8037，再增加页数则不能满足。","source":"math #186","bad":false,"notice":""},{"id":"m187","major":"数学题","minor":"方程应用","question":"公司招人35人, 只能胜任","options":[{"key":"A","text":"的比兼职胜任多1人, 问只胜任"},{"key":"B","text":"江作的人是"},{"key":"C","text":"的两倍, 只能胜任"},{"key":"D","text":"以上都不正确"}],"answer":"B","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“江作的人是”，因此选择B。","source":"math #187","bad":true,"notice":"原题信息残缺或答案有争议，暂不参与计分。"},{"id":"m188","major":"数学题","minor":"数论问题","question":"一个正整数除以11余8，除以13余10，除以17余14。最小值是多少？","options":[{"key":"A","text":"2428"},{"key":"B","text":"2185"},{"key":"C","text":"2671"},{"key":"D","text":"2914"}],"answer":"A","explanation":"三个余数分别比除数小3，所以该数加3同时被11、13、17整除。最小值为11×13×17-3=2428。","source":"math #188","bad":false,"notice":""},{"id":"m189","major":"数学题","minor":"排列组合","question":"用1、2、3、4组成无重复数字的四位数，按从小到大排列，第18个是多少？","options":[{"key":"A","text":"3079"},{"key":"B","text":"3421"},{"key":"C","text":"3763"},{"key":"D","text":"4105"}],"answer":"B","explanation":"每个千位数字对应6个数。第18个是千位为3的第6个，后三位1、2、4按升序排列的第6个为421，所以是3421。","source":"math #189","bad":false,"notice":""},{"id":"m190","major":"数学题","minor":"方程应用","question":"下列哪个乘积最大？","options":[{"key":"A","text":"599×601"},{"key":"B","text":"598×602"},{"key":"C","text":"590×610"},{"key":"D","text":"500×700"}],"answer":"A","explanation":"都围绕600比较：599×601=600²-1，598×602=600²-4，590×610=600²-100，第一项最大。","source":"math #190","bad":false,"notice":""},{"id":"m191","major":"数学题","minor":"方程应用","question":"三个自然数两两相加得8、11、13，两两相乘得15、24、40。三个数的乘积是多少？","options":[{"key":"A","text":"108"},{"key":"B","text":"132"},{"key":"C","text":"144"},{"key":"D","text":"120"}],"answer":"D","explanation":"三个数是3、5、8，乘积为3×5×8=120。","source":"math #191","bad":false,"notice":""},{"id":"m192","major":"数学题","minor":"几何问题","question":"用28米围栏围成三角形，第一边长m米，第二边长m+4米，第三边长24-2m米。若第一边是唯一最短边，且第三边长于第二边，m可取哪个整数？","options":[{"key":"A","text":"6"},{"key":"B","text":"5"},{"key":"C","text":"7"},{"key":"D","text":"8"}],"answer":"A","explanation":"三角形条件给m>5，第三边长于第二边给24-2m>m+4，即m<20/3。整数m只能取6。","source":"math #192","bad":false,"notice":""},{"id":"m193","major":"数学题","minor":"排列组合","question":"5支足球队单循环赛，胜3分、平各1分、负0分。总积分25分，冠军4战全胜得12分。亚军得多少分？","options":[{"key":"A","text":"4分"},{"key":"B","text":"5分"},{"key":"C","text":"6分"},{"key":"D","text":"7分"}],"answer":"B","explanation":"10场比赛若全分胜负总分30分，实际25分说明有5场平局。冠军4场全胜，剩余4队的6场中5平1胜负，最高者得5分。","source":"math #193","bad":false,"notice":""},{"id":"m194","major":"数学题","minor":"容斥原理","question":"按题设，体力、情绪、智力分别以22、28、33天为周期，前半周期为高潮。按每年365天计算，生日时三者首次同时处于高潮的最小年龄是？","options":[{"key":"A","text":"1周岁"},{"key":"B","text":"3周岁"},{"key":"C","text":"2周岁"},{"key":"D","text":"4周岁"}],"answer":"C","explanation":"1周岁时365 mod 22=13，体力不在前半周期；2周岁730天，对22、28、33的余数分别为4、2、4，均在前半周期。","source":"math #194","bad":false,"notice":""},{"id":"m195","major":"数学题","minor":"工程问题","question":"电动公交车相较柴油公交车的综合减排效率约为88%。某公交公司通过更换电动车使总体碳排放降低约59%，电动公交车占比约为多少？","options":[{"key":"A","text":"60%"},{"key":"B","text":"74%"},{"key":"C","text":"81%"},{"key":"D","text":"67%"}],"answer":"D","explanation":"若电动车占比为x，则总体减排约为88%x。由0.88x≈0.59，得x≈0.67，即约67%。","source":"math #195","bad":false,"notice":""},{"id":"m196","major":"数学题","minor":"行程问题","question":"飞机原计划每分钟飞12千米，后提高到每分钟15千米，比原计划提前30分钟到达。机场到灾区多远？","options":[{"key":"A","text":"1800千米"},{"key":"B","text":"1620千米"},{"key":"C","text":"1980千米"},{"key":"D","text":"2160千米"}],"answer":"A","explanation":"设距离d，d/12-d/15=30，解得d=1800千米。","source":"math #196","bad":false,"notice":""},{"id":"m197","major":"数学题","minor":"方程应用","question":"用1、 2、3、4、5组成一个无重复数字的五位数, 组成数字是","options":[{"key":"A","text":"484% 3"},{"key":"B","text":"364%"},{"key":"C","text":"偶数有几种惊况? 明人 es"},{"key":"D","text":"以上都不正确"}],"answer":"A","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“484% 3”，因此选择A。","source":"math #197","bad":false,"notice":""},{"id":"m198","major":"数学题","minor":"容斥原理","question":"学校开设语文、数学、美术3种课外班，每名学生至多参加2种，也可以不参加。至少有多少名学生，才能保证有5名学生参加课外班的情况完全相同？","options":[{"key":"A","text":"26人"},{"key":"B","text":"32人"},{"key":"C","text":"29人"},{"key":"D","text":"35人"}],"answer":"C","explanation":"参加方式有：不参加1种、只参加一种3种、参加两种3种，共7种。每种最多4人时有28人，再来1人必有一种方式达到5人，所以至少29人。","source":"math #198","bad":false,"notice":""},{"id":"m199","major":"数学题","minor":"比例百分数","question":"某学校目前学生与教师人数之比为30:1。若学生增加50人、教师增加5人，两者之比变为25:1。目前教师有多少人？","options":[{"key":"A","text":"8"},{"key":"B","text":"10"},{"key":"C","text":"12"},{"key":"D","text":"15"}],"answer":"D","explanation":"设目前教师有x人，则(30x+50)/(x+5)=25，解得x=15。","source":"math #199","bad":false,"notice":""},{"id":"m200","major":"数学题","minor":"数论问题","question":"小丽读一本书，第一天读全书的4/7，第二天读余下的3/5，还剩84页。全书多少页？","options":[{"key":"A","text":"490页"},{"key":"B","text":"441页"},{"key":"C","text":"539页"},{"key":"D","text":"588页"}],"answer":"A","explanation":"最后剩全书的(1-4/7)(1-3/5)=6/35，所以全书84÷(6/35)=490页。","source":"math #200","bad":false,"notice":""},{"id":"m201","major":"数学题","minor":"几何问题","question":"正八面体有多少条棱？","options":[{"key":"A","text":"11条"},{"key":"B","text":"12条"},{"key":"C","text":"13条"},{"key":"D","text":"14条"}],"answer":"B","explanation":"正八面体有8个三角形面，每个面3条边，每条棱被2个面共有，所以棱数8×3÷2=12。","source":"math #201","bad":false,"notice":""},{"id":"m202","major":"数学题","minor":"排列组合","question":"1分、2分、5分、1角、2角和1元硬币各1枚，至少取1枚，可组成多少种不同币值？","options":[{"key":"A","text":"57种"},{"key":"B","text":"69种"},{"key":"C","text":"63种"},{"key":"D","text":"75种"}],"answer":"C","explanation":"这些面值使不同非空子集对应不同总金额。6枚硬币有2⁶-1=63个非空子集。","source":"math #202","bad":false,"notice":""},{"id":"m203","major":"数学题","minor":"方程应用","question":"前9次测试平均分为17分，第10次测试后，10次平均分为18分。第10次得多少分？","options":[{"key":"A","text":"24分"},{"key":"B","text":"30分"},{"key":"C","text":"33分"},{"key":"D","text":"27分"}],"answer":"D","explanation":"前9次总分9×17=153，10次总分10×18=180，第10次得180-153=27分。","source":"math #203","bad":false,"notice":""},{"id":"m204","major":"数学题","minor":"方程应用","question":"计算：12.5×0.15×16÷10。","options":[{"key":"A","text":"3"},{"key":"B","text":"2"},{"key":"C","text":"4"},{"key":"D","text":"5"}],"answer":"A","explanation":"先算12.5×16=200，再算200×0.15÷10=30÷10=3。","source":"math #204","bad":false,"notice":""},{"id":"m205","major":"数学题","minor":"方程应用","question":"计算84.78+59.50+66.50+12.43+121.61。","options":[{"key":"A","text":"310.338"},{"key":"B","text":"344.82"},{"key":"C","text":"379.302"},{"key":"D","text":"413.784"}],"answer":"B","explanation":"依次相加得到144.28、210.78、223.21，最后加121.61得344.82。","source":"math #205","bad":false,"notice":""},{"id":"m206","major":"数学题","minor":"概率","question":"射击运动员每次射击命中10环的概率是80%,5次射击有4次命中10环的概率是 ()","options":[{"key":"A","text":"80%"},{"key":"B","text":"63.22%"},{"key":"C","text":"40, 96%"},{"key":"D","text":"32.81%"}],"answer":"C","explanation":"恰好4次命中10环：C(5,4)×0.8⁴×0.2＝40.96%。","source":"math #206","bad":false,"notice":""},{"id":"m207","major":"数学题","minor":"年龄问题","question":"赵先生年龄是钱先生的2倍，钱先生比孙先生小7岁。三人年龄和是小于70的素数，且该素数各位数字和为13。三人年龄分别是多少？","options":[{"key":"A","text":"27岁、15岁、22岁"},{"key":"B","text":"33岁、15岁、22岁"},{"key":"C","text":"36岁、15岁、22岁"},{"key":"D","text":"30岁、15岁、22岁"}],"answer":"D","explanation":"逐项检验：30=2×15，15比22小7；三人年龄和67是小于70的素数，且6+7=13，完全符合。","source":"math #207","bad":false,"notice":""},{"id":"m208","major":"数学题","minor":"工程问题","question":"甲乙两个工程队合作挖一条隔道, 如果甲队单独施工要20天完成,.. 乙队单独施工要10天完成。 如果甲先挖一天, 然后乙拳替甲挖一天, 再由甲接替乙挖一天 …... 两人如此交替合作。 那么, 挖完这条隧道共要多少天?","options":[{"key":"A","text":"13"},{"key":"B","text":"13.5"},{"key":"C","text":"14"},{"key":"D","text":"15.5"}],"answer":"B","explanation":"本题考查工程问题。把总工作量设为1，将各自效率写成每天完成量后列式。计算结果为“13.5”，因此选择B。","source":"math #208","bad":false,"notice":""},{"id":"m209","major":"数学题","minor":"方程应用","question":"4⁸、5⁷、6⁶、7⁵中哪个最大？","options":[{"key":"A","text":"4⁷"},{"key":"B","text":"5⁷"},{"key":"C","text":"6⁷"},{"key":"D","text":"7⁷"}],"answer":"B","explanation":"分别为65536、78125、46656、16807，最大是5⁷。","source":"math #209","bad":false,"notice":""},{"id":"m210","major":"数学题","minor":"方程应用","question":"分钟转了一百园时针转了几圈 D Al","options":[{"key":"B","text":"2"},{"key":"C","text":"5/3"},{"key":"D","text":"3/4限 y"}],"answer":"C","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“5/3”，因此选择C。","source":"math #210","bad":false,"notice":""},{"id":"m211","major":"数学题","minor":"比例百分数","question":"把90千克浓度为50%的酒精溶液稀释成30%，需要加水多少千克？","options":[{"key":"A","text":"54千克"},{"key":"B","text":"66千克"},{"key":"C","text":"72千克"},{"key":"D","text":"60千克"}],"answer":"D","explanation":"酒精质量保持45千克不变，稀释后总质量为45÷30%=150千克，因此需加水150-90=60千克。","source":"math #211","bad":false,"notice":""},{"id":"m212","major":"数学题","minor":"比例百分数","question":"某企业调查网络信息获取方式，问卷回收率90%。使用搜索、官网、社交网站的分别有179、146、246人；三种都用115人，恰用两种24人，三种都不用52人。共发出多少份问卷？","options":[{"key":"A","text":"410份"},{"key":"B","text":"369份"},{"key":"C","text":"451份"},{"key":"D","text":"492份"}],"answer":"A","explanation":"三类人数和571=只用一种人数+2×24+3×115，得只用一种178人。回收问卷数为178+24+115+52=369，发出369÷90%=410份。","source":"math #212","bad":false,"notice":""},{"id":"m213","major":"数学题","minor":"几何问题","question":"用一根周长相等的铁丝, 困城三角形、 园形、 正方形、 菊形, 则面积最大的图形是 ()","options":[{"key":"A","text":"三角形"},{"key":"B","text":"圆形 Cc. 正方形 D. BE"},{"key":"C","text":"以上都不正确"},{"key":"D","text":"以上都不正确"}],"answer":"B","explanation":"本题考查几何问题。画出关键尺寸，代入相应的周长、面积或体积公式。计算结果为“圆形 Cc. 正方形 D. BE”，因此选择B。","source":"math #213","bad":false,"notice":""},{"id":"m214","major":"数学题","minor":"方程应用","question":"某工厂男职工人数是女职工的1/3，男职工比女职工少380人。全厂共有多少人？","options":[{"key":"A","text":"684人"},{"key":"B","text":"836人"},{"key":"C","text":"760人"},{"key":"D","text":"912人"}],"answer":"C","explanation":"设男职工x人、女职工3x人，3x-x=380，得x=190，总人数4x=760。","source":"math #214","bad":false,"notice":""},{"id":"m215","major":"数学题","minor":"方程应用","question":"6, 18, () 78, 126","options":[{"key":"A","text":"40"},{"key":"B","text":"42"},{"key":"C","text":"44"},{"key":"D","text":"46"}],"answer":"B","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“42”，因此选择B。","source":"math #215","bad":false,"notice":""},{"id":"m216","major":"数学题","minor":"数列规律","question":"找规律：6，-9，12，（ ），18。","options":[{"key":"A","text":"-15"},{"key":"B","text":"-17"},{"key":"C","text":"-13"},{"key":"D","text":"-11"}],"answer":"A","explanation":"绝对值依次加3，正负号交替，因此缺项为-15。","source":"math #216","bad":false,"notice":""},{"id":"m217","major":"数学题","minor":"方程应用","question":"在一次联欢会上, 10名同学握手, 若每两人之间握一次手, 共握 () 次手","options":[{"key":"A","text":"28"},{"key":"B","text":"45"},{"key":"C","text":"36"},{"key":"D","text":"以上都不正确"}],"answer":"B","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“45”，因此选择B。","source":"math #217","bad":false,"notice":""},{"id":"m218","major":"数学题","minor":"概率","question":"10个位置平均分给5个人，每人2个位置。随机放入3个红球，其余为白球。恰有3个人没拿到红球的概率是多少？","options":[{"key":"A","text":"0/3"},{"key":"B","text":"2/3"},{"key":"C","text":"1/3"},{"key":"D","text":"3/3"}],"answer":"C","explanation":"恰有3人无红球，表示3个红球集中在另外2人的4个位置且两人都拿到。选这2人有C(5,2)种，在4个位置选3个有4种，共40种；总数C(10,3)=120，概率1/3。","source":"math #218","bad":false,"notice":""},{"id":"m219","major":"数学题","minor":"方程应用","question":"有一个两位数, 如果在两个数字中间加一个零, 得刻的三位数是原 S: 来的9倍, 请问这个两位数是 C)","options":[{"key":"A","text":"23"},{"key":"B","text":"34"},{"key":"C","text":"45"},{"key":"D","text":"56门心"}],"answer":"C","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“45”，因此选择C。","source":"math #219","bad":false,"notice":""},{"id":"m220","major":"数学题","minor":"工程问题","question":"一项工作甲单独做20天，乙单独做30天。两人合作3天可完成全部工作的几分之几？","options":[{"key":"A","text":"1/4"},{"key":"B","text":"0/4"},{"key":"C","text":"2/4"},{"key":"D","text":"3/4"}],"answer":"A","explanation":"合作效率为1/20+1/30=1/12，3天完成3/12=1/4。","source":"math #220","bad":false,"notice":""},{"id":"m221","major":"数学题","minor":"方程应用","question":"0.2、0.8、1.2和x的平均数为0.6，x是多少？","options":[{"key":"A","text":"0.1"},{"key":"B","text":"0.2"},{"key":"C","text":"0.3"},{"key":"D","text":"0.4"}],"answer":"B","explanation":"四个数总和应为0.6×4=2.4，前三个数和为2.2，所以x=0.2。","source":"math #221","bad":false,"notice":""},{"id":"m222","major":"数学题","minor":"排列组合","question":"餐厅需要9升食用油。库房有15桶5升装、3桶2升装、8桶1升装。恰好发出9升有多少种发货方式？","options":[{"key":"A","text":"6种"},{"key":"B","text":"8种"},{"key":"C","text":"7种"},{"key":"D","text":"9种"}],"answer":"C","explanation":"列方程5a+2b+c=9。a=0时b可取0～3，共4种；a=1时b可取0～2，共3种，合计7种。","source":"math #222","bad":false,"notice":""},{"id":"m223","major":"数学题","minor":"数列规律","question":"找规律：0，7，26，63，（ ）。","options":[{"key":"A","text":"112"},{"key":"B","text":"136"},{"key":"C","text":"148"},{"key":"D","text":"124"}],"answer":"D","explanation":"第n项为n³-1，下一项5³-1=124。","source":"math #223","bad":false,"notice":""},{"id":"m224","major":"数学题","minor":"利润经济","question":"汉堡每个成本4.5元、售价10.5元，当天未售完即丢弃。10天每天制作200个，其中6天售完，4天各剩25个。10天共获利多少元？","options":[{"key":"A","text":"10950元"},{"key":"B","text":"9855元"},{"key":"C","text":"12045元"},{"key":"D","text":"13140元"}],"answer":"A","explanation":"共制作2000个，成本9000元；售出6×200+4×175=1900个，收入19950元，利润19950-9000=10950元。","source":"math #224","bad":false,"notice":""},{"id":"m225","major":"数学题","minor":"方程应用","question":"若ab<0，则直线y=ax+b与x轴交点的位置一定是？","options":[{"key":"A","text":"x轴负半轴"},{"key":"B","text":"x轴正半轴"},{"key":"C","text":"y轴负半轴"},{"key":"D","text":"y轴正半轴"}],"answer":"B","explanation":"令y=0得横坐标x=-b/a。ab<0说明a、b异号，所以-b/a>0，交点在x轴正半轴。","source":"math #225","bad":false,"notice":""},{"id":"m226","major":"数学题","minor":"方程应用","question":"计算：(1-1/10)(1-1/9)(1-1/8)…(1-1/2)。","options":[{"key":"A","text":"0/10"},{"key":"B","text":"2/10"},{"key":"C","text":"1/10"},{"key":"D","text":"3/10"}],"answer":"C","explanation":"写成9/10×8/9×7/8×…×1/2，中间因子全部约去，只剩1/10。","source":"math #226","bad":false,"notice":""},{"id":"m227","major":"数学题","minor":"年龄问题","question":"10年前父亲年龄是女儿的7倍，15年后父亲年龄是女儿的2倍。女儿现在多少岁？","options":[{"key":"A","text":"13岁"},{"key":"B","text":"17岁"},{"key":"C","text":"19岁"},{"key":"D","text":"15岁"}],"answer":"D","explanation":"设现在父亲F岁、女儿D岁。F-10=7(D-10)，F+15=2(D+15)，联立得D=15、F=45。","source":"math #227","bad":false,"notice":""},{"id":"m228","major":"数学题","minor":"行程问题","question":"比例尺1∶100000的地图上，两地距离13.8厘米，实际距离是多少千米？","options":[{"key":"A","text":"13.8千米"},{"key":"B","text":"12.42千米"},{"key":"C","text":"15.18千米"},{"key":"D","text":"16.56千米"}],"answer":"A","explanation":"13.8×100000厘米=1380000厘米=13.8千米。","source":"math #228","bad":false,"notice":""},{"id":"m229","major":"数学题","minor":"方程应用","question":"乒乓球比赛中每两名选手赛一场，共36场。参赛者有多少人？","options":[{"key":"A","text":"8人"},{"key":"B","text":"9人"},{"key":"C","text":"10人"},{"key":"D","text":"11人"}],"answer":"B","explanation":"设n人，比赛场数C(n,2)=36，即n(n-1)=72，解得n=9。","source":"math #229","bad":false,"notice":""},{"id":"m230","major":"数学题","minor":"数列规律","question":"按规律：1=5，2=15，3=215，4=2145，那么5=？","options":[{"key":"A","text":"19337"},{"key":"B","text":"23633"},{"key":"C","text":"21485"},{"key":"D","text":"25781"}],"answer":"C","explanation":"右侧每次在倒数第二位前插入下一个2的幂：1、2、4、8，因此得到21485。","source":"math #230","bad":false,"notice":""},{"id":"m231","major":"数学题","minor":"利润经济","question":"商店规定购买标价200元以上商品可优惠20%。用300元最多可以买到标价多少元的商品？","options":[{"key":"A","text":"337元"},{"key":"B","text":"413元"},{"key":"C","text":"451元"},{"key":"D","text":"375元"}],"answer":"D","explanation":"实付为标价的80%，标价上限为300÷0.8=375元。","source":"math #231","bad":false,"notice":""},{"id":"m232","major":"数学题","minor":"比例百分数","question":"食堂购进200斤含水量90%的西红柿。3天后含水量变为80%，这批西红柿总重量减少多少斤？","options":[{"key":"A","text":"100斤"},{"key":"B","text":"90斤"},{"key":"C","text":"110斤"},{"key":"D","text":"120斤"}],"answer":"A","explanation":"不变的固体物质原有200×10%=20斤。含水量80%时固体占20%，总重为20÷20%=100斤，因此减少100斤。","source":"math #232","bad":false,"notice":""},{"id":"m233","major":"数学题","minor":"概率","question":"一个家庭有两个孩子，已知至少有一个是女孩。假定生男生女概率相同，两个孩子都是女孩的概率是多少？","options":[{"key":"A","text":"0/3"},{"key":"B","text":"1/3"},{"key":"C","text":"2/3"},{"key":"D","text":"3/3"}],"answer":"B","explanation":"满足“至少一个女孩”的等可能性别组合是女女、女男、男女三种，其中只有女女符合，所以概率为1/3。","source":"math #233","bad":false,"notice":""},{"id":"m234","major":"数学题","minor":"容斥原理","question":"红、黄、蓝珠子各若干。52名学生每人取1～3颗，每种颜色至多取1颗。至少有多少人取珠方式完全相同？","options":[{"key":"A","text":"7人"},{"key":"B","text":"9人"},{"key":"C","text":"8人"},{"key":"D","text":"10人"}],"answer":"C","explanation":"取法共有C(3,1)+C(3,2)+C(3,3)=7种。52÷7=7余3，由抽屉原理至少有8人相同。","source":"math #234","bad":false,"notice":""},{"id":"m235","major":"数学题","minor":"方程应用","question":"牧场养27头牛，6天吃完草；养23头牛，9天吃完。草持续生长。养21头牛多少天吃完？","options":[{"key":"A","text":"11天"},{"key":"B","text":"13天"},{"key":"C","text":"14天"},{"key":"D","text":"12天"}],"answer":"D","explanation":"设每天长草量相当于r头牛，初始草量G。6(27-r)=9(23-r)，得r=15、G=72；21头牛净消耗6份/天，需72÷6=12天。","source":"math #235","bad":false,"notice":""},{"id":"m236","major":"数学题","minor":"方程应用","question":"甲乙丙丁四人为地震灾区捐款, 甲捐款数是另外三人捐款总数的一半, 乙抹全款数是另外三人捐款总数的三分之一, 丙捐款数是古外三人捐款总数的四分之一, 丁捐款169元, 请问四人一共捐款多少钱?","options":[{"key":"A","text":"780"},{"key":"B","text":"890"},{"key":"C","text":"1183"},{"key":"D","text":"2083... a"}],"answer":"A","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“780”，因此选择A。","source":"math #236","bad":false,"notice":""},{"id":"m237","major":"数学题","minor":"方程应用","question":"1992是24个连续偶数的和，其中最大的偶数是多少？","options":[{"key":"A","text":"95"},{"key":"B","text":"106"},{"key":"C","text":"117"},{"key":"D","text":"128"}],"answer":"B","explanation":"平均数为1992÷24=83。24个连续偶数关于83对称，最小60、最大106。","source":"math #237","bad":false,"notice":""},{"id":"m238","major":"数学题","minor":"数论问题","question":"以下哪个数字能被11整除? &","options":[{"key":"A","text":"937845678 or"},{"key":"B","text":"235789453 E"},{"key":"C","text":"436728839"},{"key":"D","text":"867392267"}],"answer":"A","explanation":"本题考查数论问题。把整除与余数条件写成同余式，再寻找最小公倍关系。计算结果为“937845678 or”，因此选择A。","source":"math #238","bad":true,"notice":"原题信息残缺或答案有争议，暂不参与计分。"},{"id":"m239","major":"数学题","minor":"工程问题","question":"道路抢修规定d天完成。甲单独做恰好按期，乙单独做需d+3天。两队合作2天后，余下由乙单独完成，仍恰好按期。d是多少？","options":[{"key":"A","text":"5天"},{"key":"B","text":"7天"},{"key":"C","text":"8天"},{"key":"D","text":"6天"}],"answer":"D","explanation":"列式2(1/d+1/(d+3))+(d-2)/(d+3)=1，化简得d=6。","source":"math #239","bad":false,"notice":""},{"id":"m240","major":"数学题","minor":"数列规律","question":"找规律：1，5，（ ），29。","options":[{"key":"A","text":"13"},{"key":"B","text":"12"},{"key":"C","text":"14"},{"key":"D","text":"15"}],"answer":"A","explanation":"相邻差依次为4、8、16，后一差是前一差的2倍，所以缺项为5+8=13。","source":"math #240","bad":false,"notice":""},{"id":"m241","major":"数学题","minor":"方程应用","question":"据估计, 东京市居民的年用水里为2亿吨, 大约有6000万吨水用在冲水马柚。 为节约用水, 东京某居民在自己楼房顶安装了一个容积为2吨的储水罐储存两水用于冲马桶,15年来即便在少一季节, 罐内一水从木用尽过。 他认为, 若东京每户居民都装一个2吨的储水罐, 就相当于在市内建起一个容积为900万吨的水库。 由此可以推出东京居民每户年用水量为 ()。","options":[{"key":"A","text":"40~50 MiB, 50~60吨"},{"key":"C","text":"30~40 mi"},{"key":"D","text":"60-~70"}],"answer":"A","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“40~50 MiB, 50~60吨”，因此选择A。","source":"math #241","bad":false,"notice":""},{"id":"m242","major":"数学题","minor":"方程应用","question":"两个水梓共盛30升水, 如果把第一个桶里的6厂水倒入第二个水 it 梓里, 两个水桶的水就一样多, 问第二桶水重多少厂?","options":[{"key":"A","text":"8"},{"key":"B","text":"21"},{"key":"C","text":"9"},{"key":"D","text":"10 b"}],"answer":"C","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“9”，因此选择C。","source":"math #242","bad":false,"notice":""},{"id":"m243","major":"数学题","minor":"数论问题","question":"下列哪个数既能被3整除，又是4的倍数？","options":[{"key":"A","text":"303"},{"key":"B","text":"307"},{"key":"C","text":"308"},{"key":"D","text":"312"}],"answer":"D","explanation":"同时满足两个条件即能被12整除。312÷12=26，其他选项不满足。","source":"math #243","bad":false,"notice":""},{"id":"m244","major":"数学题","minor":"比例百分数","question":"甲把自己原有数量的一半给乙后，乙现有数量是甲现有数量的4/3。甲、乙原有数量之比是多少？","options":[{"key":"A","text":"6∶1"},{"key":"B","text":"5∶1"},{"key":"C","text":"7∶1"},{"key":"D","text":"8∶1"}],"answer":"A","explanation":"设甲原有6份、乙原有1份。甲给出3份后剩3份，乙变为4份，恰是甲现有量的4/3，所以原比为6∶1。","source":"math #244","bad":false,"notice":""},{"id":"m245","major":"数学题","minor":"方程应用","question":"甲队每小时修12米，比乙队每小时多修1/3。两队合修1小时共修多少米？","options":[{"key":"A","text":"19米"},{"key":"B","text":"21米"},{"key":"C","text":"23米"},{"key":"D","text":"25米"}],"answer":"B","explanation":"乙队效率为12÷(1+1/3)=9米/时，两队合计12+9=21米。","source":"math #245","bad":false,"notice":""},{"id":"m246","major":"数学题","minor":"计数问题","question":"李主任8:30后参加会议。会议开始时手表时针与分针夹角为120°，结束时为180°。会议期间两针呈90°的情况最多出现几次？","options":[{"key":"A","text":"3次"},{"key":"B","text":"5次"},{"key":"C","text":"4次"},{"key":"D","text":"6次"}],"answer":"C","explanation":"时针和分针的相对角速度恒定。结合开始、结束夹角以及会议位于上午的时间范围，分段枚举两针夹角为90°的时刻，最多出现4次。","source":"math #246","bad":false,"notice":""},{"id":"m247","major":"数学题","minor":"概率","question":"某单位有3项业务要招标, 共有5家公司前来投标, 且每家公司都对3项业史务发出了投标中请, 最终发现每项业务都有且只有1家公司中标。 如5家公司圭各项业务中中标的概率均相等, 问这3项业务由同一家公司中标的概率为多少?","options":[{"key":"A","text":"1/86"},{"key":"B","text":"1/8L ="},{"key":"C","text":"1/125 i. 1/243"},{"key":"D","text":"以上都不正确"}],"answer":"A","explanation":"本题考查概率。先确定所有等可能结果，再统计满足条件的结果数，用“符合数÷总数”计算。计算结果为“1/86”，因此选择A。","source":"math #247","bad":false,"notice":""},{"id":"m248","major":"数学题","minor":"排列组合","question":"黄、白、蓝三个不同颜色的球从左到右排列，有多少种不同排法？","options":[{"key":"A","text":"6种"},{"key":"B","text":"5种"},{"key":"C","text":"7种"},{"key":"D","text":"8种"}],"answer":"A","explanation":"三个不同元素的全排列数为3!=6。","source":"math #248","bad":false,"notice":""},{"id":"m249","major":"数学题","minor":"数论问题","question":"5649879、98798742、78668、54678这四个数中，能被9整除的有几个？","options":[{"key":"A","text":"0个"},{"key":"B","text":"1个"},{"key":"C","text":"2个"},{"key":"D","text":"3个"}],"answer":"B","explanation":"各数数字和分别为48、54、35、30，只有54能被9整除，所以只有1个。","source":"math #249","bad":false,"notice":""},{"id":"m250","major":"数学题","minor":"几何问题","question":"直径分别为1、2、3、4、5、8厘米的圆片中，周长最小的圆片周长是多少？","options":[{"key":"A","text":"π厘米"},{"key":"B","text":"2π厘米"},{"key":"C","text":"3π厘米"},{"key":"D","text":"4π厘米"}],"answer":"A","explanation":"圆周长C=πd，直径最小为1厘米，所以最小周长为π厘米。","source":"math #250","bad":false,"notice":""},{"id":"m251","major":"数学题","minor":"方程应用","question":"语文、数学、英语三本书价格比为2∶5∶3，总价70元。数学书多少元？","options":[{"key":"A","text":"31元"},{"key":"B","text":"39元"},{"key":"C","text":"43元"},{"key":"D","text":"35元"}],"answer":"D","explanation":"总份数10，数学占5份，价格70×5/10=35元。","source":"math #251","bad":false,"notice":""},{"id":"m252","major":"数学题","minor":"容斥原理","question":"“甲、乙两人至少有一人不是大学生”等价于哪一项？","options":[{"key":"A","text":"甲、乙至多一人是大学生"},{"key":"B","text":"甲、乙都不是大学生"},{"key":"C","text":"甲是大学生而乙不是"},{"key":"D","text":"甲、乙至少一人是大学生"}],"answer":"A","explanation":"“至少一人不是”否定的是“两人都是大学生”，等价于大学生人数不超过1。","source":"math #252","bad":false,"notice":""},{"id":"m253","major":"数学题","minor":"概率","question":"某病自然痊愈率0.1。无效新药给10名病人服用，至少3人痊愈就误判有效。发生误判的概率是多少？","options":[{"key":"A","text":"约0.0194"},{"key":"B","text":"约0.0520"},{"key":"C","text":"约0.0702"},{"key":"D","text":"约0.1000"}],"answer":"C","explanation":"令X服从B(10,0.1)，误判概率P(X≥3)=1-P(0)-P(1)-P(2)≈0.0702。","source":"math #253","bad":false,"notice":""},{"id":"m254","major":"数学题","minor":"方程应用","question":"所有两位偶数的和是多少？","options":[{"key":"A","text":"2187"},{"key":"B","text":"2673"},{"key":"C","text":"2430"},{"key":"D","text":"2916"}],"answer":"C","explanation":"两位偶数从10到98，共45个，平均数54，总和45×54=2430。","source":"math #254","bad":false,"notice":""},{"id":"m255","major":"数学题","minor":"概率","question":"连续掷一枚均匀骰子两次，点数和为7的概率是多少？","options":[{"key":"A","text":"0/6"},{"key":"B","text":"2/6"},{"key":"C","text":"3/6"},{"key":"D","text":"1/6"}],"answer":"D","explanation":"共有36种等可能结果，和为7的有(1,6)、(2,5)、…、(6,1)共6种，概率6/36=1/6。","source":"math #255","bad":false,"notice":""},{"id":"m256","major":"数学题","minor":"方程应用","question":"公共汽车起点站每5分钟一赵车, 一小时要发出多少辆公共汽车 () at","options":[{"key":"A","text":"12"},{"key":"B","text":"13"},{"key":"C","text":"28"},{"key":"D","text":"30 ah"}],"answer":"B","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“13”，因此选择B。","source":"math #256","bad":false,"notice":""},{"id":"m257","major":"数学题","minor":"比例百分数","question":"李继工资的60%是900 - 元, 她这个月工资为 (1500元) 271.3, 4, 8, 24, 88()","options":[{"key":"A","text":"121"},{"key":"B","text":"196"},{"key":"C","text":"225"},{"key":"D","text":"344"}],"answer":"B","explanation":"本题考查比例百分数。把基准量设为1份或100%，按对应比例换算。计算结果为“196”，因此选择B。","source":"math #257","bad":false,"notice":""},{"id":"m258","major":"数学题","minor":"方程应用","question":"张鹏每周储茜35元, 他已有100元存款, 还帮多少天才能买240元的自行转?","options":[{"key":"A","text":"4"},{"key":"B","text":"6"},{"key":"C","text":"28"},{"key":"D","text":"21"}],"answer":"C","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“28”，因此选择C。","source":"math #258","bad":false,"notice":""},{"id":"m259","major":"数学题","minor":"方程应用","question":"已知a/b=2/3，求(2a+b)/(3b)。","options":[{"key":"A","text":"6/9"},{"key":"B","text":"8/9"},{"key":"C","text":"9/9"},{"key":"D","text":"7/9"}],"answer":"D","explanation":"令a=2k、b=3k，则(2a+b)/(3b)=(4k+3k)/(9k)=7/9。","source":"math #259","bad":false,"notice":""},{"id":"m260","major":"数学题","minor":"方程应用","question":"(904-594)÷620等于多少？","options":[{"key":"A","text":"1/2"},{"key":"B","text":"0/2"},{"key":"C","text":"2/2"},{"key":"D","text":"3/2"}],"answer":"A","explanation":"904-594=310，310÷620=1/2。","source":"math #260","bad":false,"notice":""},{"id":"m261","major":"数学题","minor":"比例百分数","question":"某运动员跳高成绩2.3米，跳远成绩是跳高成绩2.5倍的80%。跳远成绩是多少米？","options":[{"key":"A","text":"4.14米"},{"key":"B","text":"4.6米"},{"key":"C","text":"5.06米"},{"key":"D","text":"5.52米"}],"answer":"B","explanation":"2.3×2.5×80%=2.3×2=4.6米。","source":"math #261","bad":false,"notice":""},{"id":"m262","major":"数学题","minor":"比例百分数","question":"某学校目前学生与教师人数之比为30:1。若学生增加50人、教师增加5人，两者之比变为25:1。目前教师有多少人？","options":[{"key":"A","text":"8"},{"key":"B","text":"10"},{"key":"C","text":"12"},{"key":"D","text":"15"}],"answer":"D","explanation":"设目前教师有x人，则(30x+50)/(x+5)=25，解得x=15。","source":"math #262","bad":false,"notice":""},{"id":"m263","major":"数学题","minor":"方程应用","question":"整数x与y的积是偶数，和是奇数。x、y的奇偶性如何？","options":[{"key":"A","text":"均为偶数"},{"key":"B","text":"均为奇数"},{"key":"C","text":"一奇一偶"},{"key":"D","text":"无法确定"}],"answer":"C","explanation":"和为奇数说明两数奇偶性不同；一奇一偶的乘积必为偶数，与题意一致。","source":"math #263","bad":false,"notice":""},{"id":"m264","major":"数学题","minor":"比例百分数","question":"一批商品先涨价20%, 再降价10%, 问现在价格是多少?","options":[{"key":"A","text":"提高了"},{"key":"B","text":"降低了"},{"key":"C","text":"不变"},{"key":"D","text":"无法确定"}],"answer":"A","explanation":"本题考查比例百分数。把基准量设为1份或100%，按对应比例换算。计算结果为“提高了”，因此选择A。","source":"math #264","bad":false,"notice":""},{"id":"m265","major":"数学题","minor":"方程应用","question":"5个不同的数，两两之和依次为3、4、5、6、7、8、11、12、13、15。这5个数的平均值是多少？","options":[{"key":"A","text":"3.78"},{"key":"B","text":"4.2"},{"key":"C","text":"4.62"},{"key":"D","text":"5.04"}],"answer":"B","explanation":"10个两两之和的总和为84。每个原数在两两和中出现4次，所以5个数之和为84÷4=21，平均值21÷5=4.2。","source":"math #265","bad":false,"notice":""},{"id":"m266","major":"数学题","minor":"概率","question":"任取一个自然数, 则该数平方的末尾数是4的概率为 () N05","options":[{"key":"B","text":"0.2/"},{"key":"C","text":"04"}],"answer":"B","explanation":"本题考查概率。先确定所有等可能结果，再统计满足条件的结果数，用“符合数÷总数”计算。计算结果为“0.2/”，因此选择B。","source":"math #266","bad":false,"notice":""},{"id":"m267","major":"数学题","minor":"概率","question":"15000件产品中有1000件废品，随机抽取150件，废品数的期望是多少？","options":[{"key":"A","text":"9件"},{"key":"B","text":"11件"},{"key":"C","text":"12件"},{"key":"D","text":"10件"}],"answer":"D","explanation":"期望=抽样数×总体废品率=150×1000/15000=10。","source":"math #267","bad":false,"notice":""},{"id":"m268","major":"数学题","minor":"工程问题","question":"甲、乙合作5天完成一项工程，甲、乙、丙合作3天完成。丙单独做需多少天？","options":[{"key":"A","text":"7.5天"},{"key":"B","text":"6.75天"},{"key":"C","text":"8.25天"},{"key":"D","text":"9天"}],"answer":"A","explanation":"丙的效率为1/3-1/5=2/15，因此单独完成需15/2=7.5天。","source":"math #268","bad":false,"notice":""},{"id":"m269","major":"数学题","minor":"容斥原理","question":"袋中有红、白、黄、蓝4种颜色的球。至少取多少个，才能保证有2个球颜色相同？","options":[{"key":"A","text":"4个"},{"key":"B","text":"5个"},{"key":"C","text":"6个"},{"key":"D","text":"7个"}],"answer":"B","explanation":"最不利情况先取到4种不同颜色，第5个必与其中一种同色。","source":"math #269","bad":false,"notice":""},{"id":"m270","major":"数学题","minor":"方程应用","question":"关于三个连续整数：①它们的和一定是偶数；②它们的乘积一定是偶数。正确的是？","options":[{"key":"A","text":"只有①正确"},{"key":"B","text":"只有②正确"},{"key":"C","text":"①②都正确"},{"key":"D","text":"①②都不正确"}],"answer":"B","explanation":"三个连续整数中必有一个偶数，所以乘积一定为偶数；和的奇偶性与中间整数相同，不一定为偶数。","source":"math #270","bad":false,"notice":""},{"id":"m271","major":"数学题","minor":"概率","question":"15000件产品中有1000件次品，随机抽取150件检查，查得次品数的数学期望是多少？","options":[{"key":"A","text":"9件"},{"key":"B","text":"11件"},{"key":"C","text":"12件"},{"key":"D","text":"10件"}],"answer":"D","explanation":"超几何分布期望为样本量×总体次品率，即150×1000/15000=10。","source":"math #271","bad":false,"notice":""},{"id":"m272","major":"数学题","minor":"概率","question":"公务员考试分笔试和面试, 笔试通过率为20%, 最后的录取率为4%; 己知桦人已经通过笔试, 则他最后被录取的概率为 (》","options":[{"key":"A","text":"20%"},{"key":"B","text":"24%"},{"key":"C","text":"16%"},{"key":"D","text":"4% a"}],"answer":"A","explanation":"本题考查概率。先确定所有等可能结果，再统计满足条件的结果数，用“符合数÷总数”计算。计算结果为“20%”，因此选择A。","source":"math #272","bad":false,"notice":""},{"id":"m273","major":"数学题","minor":"方程应用","question":"若甲数加3与乙数减8相等，甲数比乙数少多少？","options":[{"key":"A","text":"10"},{"key":"B","text":"11"},{"key":"C","text":"12"},{"key":"D","text":"13"}],"answer":"B","explanation":"甲+3=乙-8，移项得乙-甲=11。","source":"math #273","bad":false,"notice":""},{"id":"m274","major":"数学题","minor":"方程应用","question":"在200米小路一侧栽树，每隔40米一棵，两端都栽，共栽多少棵？","options":[{"key":"A","text":"5棵"},{"key":"B","text":"7棵"},{"key":"C","text":"6棵"},{"key":"D","text":"8棵"}],"answer":"C","explanation":"200÷40=5个间隔，两端都栽时棵数为5+1=6。","source":"math #274","bad":false,"notice":""},{"id":"m275","major":"数学题","minor":"概率","question":"从3、5、7、11四个质数中任取两个相乘，可以得到多少个不同的积？","options":[{"key":"A","text":"5个"},{"key":"B","text":"7个"},{"key":"C","text":"8个"},{"key":"D","text":"6个"}],"answer":"D","explanation":"任取两个质数的组合数为C(4,2)=6，且不同质数对的乘积不会相同。","source":"math #275","bad":false,"notice":""},{"id":"m276","major":"数学题","minor":"方程应用","question":"象棋比赛每两位棋手赛一局，共36局。参赛棋手有多少人？","options":[{"key":"A","text":"9人"},{"key":"B","text":"8人"},{"key":"C","text":"10人"},{"key":"D","text":"11人"}],"answer":"A","explanation":"C(n,2)=36，解得n=9。","source":"math #276","bad":false,"notice":""},{"id":"m277","major":"数学题","minor":"几何问题","question":"物体沿圆周运行一圈半，共转过多少度？","options":[{"key":"A","text":"486°"},{"key":"B","text":"540°"},{"key":"C","text":"594°"},{"key":"D","text":"648°"}],"answer":"B","explanation":"一圈360°，一圈半为360×1.5=540°。","source":"math #277","bad":false,"notice":""},{"id":"m278","major":"数学题","minor":"年龄问题","question":"甲年龄等于乙现在年龄时，乙4岁；乙年龄等于甲现在年龄时，甲67岁。甲、乙现在各多少岁？","options":[{"key":"A","text":"甲42岁、乙21岁"},{"key":"B","text":"甲46岁、乙25岁"},{"key":"C","text":"甲48岁、乙27岁"},{"key":"D","text":"甲50岁、乙29岁"}],"answer":"B","explanation":"设年龄差d，则乙=d+4、甲=2d+4；又67-甲=d，解得d=21，所以甲46岁、乙25岁。","source":"math #278","bad":false,"notice":""},{"id":"m279","major":"数学题","minor":"方程应用","question":"正常情况下，12小时内时针和分针重合多少次？","options":[{"key":"A","text":"10次"},{"key":"B","text":"12次"},{"key":"C","text":"13次"},{"key":"D","text":"11次"}],"answer":"D","explanation":"分针相对时针每12/11小时追上一圈，因此12小时内重合11次。","source":"math #279","bad":false,"notice":""},{"id":"m280","major":"数学题","minor":"概率","question":"10件产品中有4件不合格。随机取2件，已知其中1件不合格，另一件也不合格的概率是多少？","options":[{"key":"A","text":"1/3"},{"key":"B","text":"0/3"},{"key":"C","text":"2/3"},{"key":"D","text":"3/3"}],"answer":"A","explanation":"发现并拿出1件不合格品后，剩余9件中有3件不合格，因此另一件也不合格的概率为3/9=1/3。","source":"math #280","bad":false,"notice":""},{"id":"m281","major":"数学题","minor":"计数问题","question":"某月1—12日安排甲、乙、丙值夜班，每人4天，三人各自值班日期之和相等。已知甲值1、2日，乙值9、10日。丙第一次与最后一次值班之间最多有几天不值班？","options":[{"key":"A","text":"5天"},{"key":"B","text":"6天"},{"key":"C","text":"7天"},{"key":"D","text":"8天"}],"answer":"B","explanation":"先由1到12日期总和78，得每人日期和26；再按甲、乙已知日期补足各自另外两天并枚举，丙首末值班日的最大空档为6天。","source":"math #281","bad":false,"notice":""},{"id":"m282","major":"数学题","minor":"容斥原理","question":"一个学雷锋小组现有14人，每人每天打工可挣3元。到11月11日已挣1764元，计划在12月9日达到3000元。新增的1人至少需要工作多少天？","options":[{"key":"A","text":"18天"},{"key":"B","text":"22天"},{"key":"C","text":"20天"},{"key":"D","text":"24天"}],"answer":"C","explanation":"剩余28天需挣1236元。原14人做28天可挣1176元，还差60元；新增1人每天多挣3元，因此至少需要工作60÷3=20天。","source":"math #282","bad":false,"notice":""},{"id":"m283","major":"数学题","minor":"比例百分数","question":"林场第一年造林80亩，以后每年比前一年多20%。第二年造林多少亩？","options":[{"key":"A","text":"86亩"},{"key":"B","text":"106亩"},{"key":"C","text":"116亩"},{"key":"D","text":"96亩"}],"answer":"D","explanation":"80×(1+20%)=96亩。","source":"math #283","bad":false,"notice":""},{"id":"m284","major":"数学题","minor":"计数问题","question":"小区道路两侧各栽35棵树。一侧每3棵银杏后栽1棵梧桐，另一侧每4棵梧桐后栽1棵银杏。合理安排首尾后，最多可栽多少棵银杏？","options":[{"key":"A","text":"34棵"},{"key":"B","text":"31棵"},{"key":"C","text":"37棵"},{"key":"D","text":"40棵"}],"answer":"A","explanation":"分别按3∶1和1∶4的循环排列，并利用首尾可先放银杏的余量。两侧银杏数相加最多为34棵。","source":"math #284","bad":false,"notice":""},{"id":"m285","major":"数学题","minor":"比例百分数","question":"小王将12600元存入年利率7.25%的银行。若改存年利率6.5%的银行，一年少得多少利息？","options":[{"key":"A","text":"85.05元"},{"key":"B","text":"94.5元"},{"key":"C","text":"103.95元"},{"key":"D","text":"113.4元"}],"answer":"B","explanation":"年利率相差0.75%，少得利息为12600×0.75%=94.5元。","source":"math #285","bad":false,"notice":""},{"id":"m286","major":"数学题","minor":"行程问题","question":"甲、乙从A地到B地分别需40分钟和30分钟。甲早出发5分钟，乙出发后多少分钟追上甲？","options":[{"key":"A","text":"13分钟"},{"key":"B","text":"17分钟"},{"key":"C","text":"15分钟"},{"key":"D","text":"19分钟"}],"answer":"C","explanation":"设乙走t分钟追上，路程比例满足(t+5)/40=t/30，解得t=15。","source":"math #286","bad":false,"notice":""},{"id":"m287","major":"数学题","minor":"比例百分数","question":"老王两年前买入一件艺术品，现市价上涨50%。他按现市价八折卖出，并支付成交价5%的费用，最终比买入时多得7万元。买入价是多少？","options":[{"key":"A","text":"45万元"},{"key":"B","text":"55万元"},{"key":"C","text":"60万元"},{"key":"D","text":"50万元"}],"answer":"D","explanation":"设买入价x万元。净到手为1.5x×0.8×0.95=1.14x，利润0.14x=7，解得x=50万元。","source":"math #287","bad":false,"notice":""},{"id":"m288","major":"数学题","minor":"方程应用","question":"一条大街长7200米，从起点到终点共设9个车站，平均相邻两站相距多少米？","options":[{"key":"A","text":"900米"},{"key":"B","text":"810米"},{"key":"C","text":"990米"},{"key":"D","text":"1080米"}],"answer":"A","explanation":"9个车站形成8个间隔，7200÷8=900米。","source":"math #288","bad":false,"notice":""},{"id":"m289","major":"数学题","minor":"排列组合","question":"自行车前轴齿轮齿数为48、36、24，后轴为36、24、16、12。可获得多少种不同的传动比？","options":[{"key":"A","text":"7种"},{"key":"B","text":"8种"},{"key":"C","text":"9种"},{"key":"D","text":"10种"}],"answer":"B","explanation":"列出12个前后齿数比并约分，去掉重复后共有2/3、1、4/3、3/2、2、9/4、3、4八种。","source":"math #289","bad":false,"notice":""},{"id":"m290","major":"数学题","minor":"年龄问题","question":"一位百岁老人出生于20世纪。2015年年龄数字和是2012年年龄数字和的1/3（出生年算0岁）。出生年份各数字之和是多少？","options":[{"key":"A","text":"13"},{"key":"B","text":"15"},{"key":"C","text":"14"},{"key":"D","text":"16"}],"answer":"C","explanation":"在百岁范围内检验可得老人出生于1904年：2015年111岁，数字和3；2012年108岁，数字和9。出生年数字和为1+9+0+4=14。","source":"math #290","bad":false,"notice":""},{"id":"m291","major":"数学题","minor":"行程问题","question":"A到B为下坡。小周6:00从A出发，7:00到中点C；到B后立即返回，10:00再次到C。随后速度提高1米/秒，11:30回到A。AB距离在哪个范围？","options":[{"key":"A","text":"小于30公里"},{"key":"B","text":"30～40公里"},{"key":"C","text":"40～50公里"},{"key":"D","text":"大于50公里"}],"answer":"C","explanation":"下坡1小时走半程，8:00到B；上坡B到C用2小时，原上坡速度为下坡一半。后半程1.5小时走完，提速3.6千米/时。由D/3-D/4=3.6得D=43.2千米。","source":"math #291","bad":false,"notice":""},{"id":"m292","major":"数学题","minor":"方程应用","question":"某班男、女生人数比为2∶1，转入2名女生后变为3∶2。现在全班多少人？","options":[{"key":"A","text":"20人"},{"key":"B","text":"18人"},{"key":"C","text":"22人"},{"key":"D","text":"24人"}],"answer":"A","explanation":"设原女生k人、男生2k人。2k/(k+2)=3/2，解得k=6；现在总人数12+8=20。","source":"math #292","bad":false,"notice":""},{"id":"m293","major":"数学题","minor":"数列规律","question":"找规律：0，7，26，63，（ ），215。","options":[{"key":"A","text":"112"},{"key":"B","text":"124"},{"key":"C","text":"136"},{"key":"D","text":"148"}],"answer":"B","explanation":"各项为n³-1，缺项是5³-1=124，后一项6³-1=215。","source":"math #293","bad":false,"notice":""},{"id":"m294","major":"数学题","minor":"数列规律","question":"找规律：3，6，（ ），21，33。","options":[{"key":"A","text":"11"},{"key":"B","text":"13"},{"key":"C","text":"12"},{"key":"D","text":"14"}],"answer":"C","explanation":"相邻差依次为3、6、9、12，因此缺项是6+6=12。","source":"math #294","bad":false,"notice":""},{"id":"m295","major":"数学题","minor":"比例百分数","question":"用8%和5%的盐水配制600克7%的盐水，两种盐水各需多少克？","options":[{"key":"A","text":"7%盐水400克、5%盐水200克"},{"key":"B","text":"9%盐水400克、5%盐水200克"},{"key":"C","text":"10%盐水400克、5%盐水200克"},{"key":"D","text":"8%盐水400克、5%盐水200克"}],"answer":"D","explanation":"设8%盐水x克，则0.08x+0.05(600-x)=0.07×600，解得x=400。","source":"math #295","bad":false,"notice":""},{"id":"m296","major":"数学题","minor":"利润经济","question":"商品成本40元，按标价打八折后的售价仍比成本高25%。商品标价是多少？","options":[{"key":"A","text":"62.5元"},{"key":"B","text":"56.25元"},{"key":"C","text":"68.75元"},{"key":"D","text":"75元"}],"answer":"A","explanation":"打折后的售价为40×1.25=50元，标价=50÷0.8=62.5元。","source":"math #296","bad":false,"notice":""},{"id":"m297","major":"数学题","minor":"行程问题","question":"汽车往返甲乙两地，去程时速30千米，回程时速60千米。往返平均速度是多少？","options":[{"key":"A","text":"36千米/时"},{"key":"B","text":"40千米/时"},{"key":"C","text":"44千米/时"},{"key":"D","text":"48千米/时"}],"answer":"B","explanation":"设单程距离d，总路程2d，总时间d/30+d/60=d/20，所以平均速度2d÷(d/20)=40千米/时。","source":"math #297","bad":false,"notice":""},{"id":"m298","major":"数学题","minor":"方程应用","question":"下面4个数中, 恰有一个数是两个相邻整数的乘积, 这个数是 () ‘","options":[{"key":"A","text":"5096303"},{"key":"B","text":"5096304"},{"key":"C","text":"5096805"},{"key":"D","text":"5096306"}],"answer":"D","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“5096306”，因此选择D。","source":"math #298","bad":false,"notice":""},{"id":"m299","major":"数学题","minor":"工程问题","question":"某集团有A、B两个公司，A公司全年销售任务是B公司的1.2倍；前三季度B公司的销售业绩是A公司的1.2倍。若按前三季度平均销售业绩计算，B公司到年底恰好完成任务。若A公司希望完成全年任务，第四季度销售业绩需达到前三季度平均销售业绩的多少倍？","options":[{"key":"A","text":"1.44"},{"key":"B","text":"2.4"},{"key":"C","text":"2.76"},{"key":"D","text":"3.88"}],"answer":"C","explanation":"设B公司全年任务为T，A公司前三季度平均每季度业绩为a，则4×1.2a=T。A公司前三季度完成3a，第四季度需完成1.2T-3a=2.76a。","source":"math #299","bad":false,"notice":""},{"id":"m300","major":"数学题","minor":"工程问题","question":"4台车床每小时共加工180个零件。若增加3台同效率的车床，每小时共能加工多少个零件？","options":[{"key":"A","text":"300"},{"key":"B","text":"315"},{"key":"C","text":"350"},{"key":"D","text":"415"}],"answer":"B","explanation":"每台每小时加工180÷4=45个，7台共加工45×7=315个。","source":"math #300","bad":false,"notice":""},{"id":"m301","major":"数学题","minor":"方程应用","question":"甲、乙两队共100人。甲队调出本队1/4到乙队后，乙队比甲队多10人。甲队原有多少人？","options":[{"key":"A","text":"54人"},{"key":"B","text":"60人"},{"key":"C","text":"66人"},{"key":"D","text":"72人"}],"answer":"B","explanation":"设甲原有x人。调整后甲3x/4，乙100-3x/4，差为10，解得x=60。","source":"math #301","bad":false,"notice":""},{"id":"m302","major":"数学题","minor":"方程应用","question":"若A>B，且A、B、C均为正数，下列结论中一定错误的是哪一项？","options":[{"key":"A","text":"AB>BC"},{"key":"B","text":"A+C>B+C"},{"key":"C","text":"C-A>C-B"},{"key":"D","text":"A/B>B/C"}],"answer":"C","explanation":"A>B，两边同乘-1得-A<-B，再同时加C，得C-A<C-B，所以选项C一定错误。","source":"math #302","bad":false,"notice":""},{"id":"m303","major":"数学题","minor":"行程问题","question":"某人在15分钟内能打X个字，按同样的速度打完Y个字需要多少小时？","options":[{"key":"A","text":"15Y/X"},{"key":"B","text":"X/(15Y)"},{"key":"C","text":"4X/Y"},{"key":"D","text":"Y/(4X)"}],"answer":"D","explanation":"15分钟为1/4小时，速度为每小时4X个字，因此所需时间为Y/(4X)小时。","source":"math #303","bad":false,"notice":""},{"id":"m304","major":"数学题","minor":"数论问题","question":"一本小说第一天读全书4/7，第二天读余下的3/5，还剩42页。全书多少页？","options":[{"key":"A","text":"245页"},{"key":"B","text":"221页"},{"key":"C","text":"269页"},{"key":"D","text":"293页"}],"answer":"A","explanation":"剩余比例为(3/7)×(2/5)=6/35，全书42÷(6/35)=245页。","source":"math #304","bad":false,"notice":""},{"id":"m305","major":"数学题","minor":"数列规律","question":"找规律：2.5，1.25，0.625，（ ），0.15625。","options":[{"key":"A","text":"0.2125"},{"key":"B","text":"0.3125"},{"key":"C","text":"0.4125"},{"key":"D","text":"0.5125"}],"answer":"B","explanation":"每项都是前一项除以2，0.625÷2=0.3125。","source":"math #305","bad":false,"notice":""},{"id":"m306","major":"数学题","minor":"数列规律","question":"找规律：18，42，78，126，（ ）。","options":[{"key":"A","text":"167"},{"key":"B","text":"205"},{"key":"C","text":"186"},{"key":"D","text":"224"}],"answer":"C","explanation":"相邻差为24、36、48，依次增加12，下一差为60，所以126+60=186。","source":"math #306","bad":false,"notice":""},{"id":"m307","major":"数学题","minor":"数列规律","question":"345，268，349，264，353，260，357，（ ）。","options":[{"key":"A","text":"370"},{"key":"B","text":"360"},{"key":"C","text":"255"},{"key":"D","text":"256"}],"answer":"D","explanation":"奇数项依次加4，偶数项依次减4，因此下一偶数项为256。","source":"math #307","bad":false,"notice":""},{"id":"m308","major":"数学题","minor":"方程应用","question":"比较579/580、1427/1428和42/43的大小。","options":[{"key":"A","text":"1427/1428＞579/580＞42/43"},{"key":"B","text":"579/580＞1427/1428＞42/43"},{"key":"C","text":"42/43＞579/580＞1427/1428"},{"key":"D","text":"579/580＞42/43＞1427/1428"}],"answer":"A","explanation":"都写成1减单位分数。减去的1/1428最小，1/580次之，1/43最大，因此顺序如答案。","source":"math #308","bad":false,"notice":""},{"id":"l1","major":"逻辑题","minor":"逻辑推理","question":"小王到商店买衬衫，售货员问她想要哪种颜色的。小王说：“我不像讨厌黄色那样讨厌红色；我不像讨厌白色那样讨厌蓝色；我不像喜欢粉色那样喜欢红色；我对蓝色不如对黄色那样喜欢。”小王最后会选择的颜色是（ ）。","options":[{"key":"A","text":"黄色"},{"key":"B","text":"蓝色"},{"key":"C","text":"红色"},{"key":"D","text":"粉色"}],"answer":"D","explanation":"由“喜欢粉色胜过红色”可知粉色的喜爱程度高于红色；其余陈述只能比较红、黄、蓝、白之间的相对顺序，均不影响粉色居前，因此选粉色。","source":"logic-practice #1","bad":false,"notice":""},{"id":"l2","major":"逻辑题","minor":"逻辑推理","question":"某家庭有6个孩子，其中3个是女孩。5个孩子有雀斑，4个孩子有卷发。这表明有可能（ ）。","options":[{"key":"A","text":"两个男孩有卷发但没有雀斑"},{"key":"B","text":"三个有雀斑的女孩都没有卷发"},{"key":"C","text":"两个有雀斑的男孩都没有卷发"},{"key":"D","text":"三个有卷发的男孩只有一个有雀斑"}],"answer":"C","explanation":"全家只有1人没有雀斑，因此A要求至少2个男孩无雀斑，不可能。若让两个男孩“有雀斑但无卷发”，其余4人有卷发，其中再安排3人有雀斑，即可同时满足5人有雀斑、4人有卷发，故C可能成立。","source":"logic-practice #2","bad":false,"notice":""},{"id":"l3","major":"逻辑题","minor":"逻辑推理","question":"MBA是一种高级企业管理人才，其最重要的一点在于企业家精神，具有企业家精神的MBA是市场中的佼佼者。我国有50多所院校招收MBA，不少还宣称与国外院校合办，但大多是一些三流院校，有的连正式教材都没有，良莠不齐。由此可推知（ ）。","options":[{"key":"A","text":"中国缺的不是MBA，而是具有企业家精神的真正的MBA"},{"key":"B","text":"中国的MBA都是不合格的"},{"key":"C","text":"中国要培养真正的MBA必须与国外知名院校联合"},{"key":"D","text":"只有拥有MBA学位的人才能管好企业"}],"answer":"A","explanation":"材料强调数量不少但质量参差，核心缺口是“真正具备企业家精神的MBA”。B、C、D均把材料中没有给出的范围或必要条件绝对化。","source":"logic-practice #3","bad":false,"notice":""},{"id":"l4","major":"逻辑题","minor":"逻辑推理","question":"三人猜测晚会节目顺序。甲说：“一班第一个出场，二班第三个出场。”乙说：“三班第一个出场，四班第四个出场。”丙说：“四班第二个出场，一班第三个出场。”结果三人的预测都只对了一半。正确顺序是（ ）。","options":[{"key":"A","text":"四班第一，三班第二，一班第三，二班第四"},{"key":"B","text":"二班第一，一班第二，三班第三，四班第四"},{"key":"C","text":"三班第一，四班第二，二班第三，一班第四"},{"key":"D","text":"一班第一，二班第二，四班第三，三班第四"}],"answer":"C","explanation":"代入C：甲的“二班第三”正确、另一句错误；乙的“三班第一”正确、另一句错误；丙的“四班第二”正确、另一句错误，三人均恰好对一半。","source":"logic-practice #4","bad":false,"notice":""},{"id":"l5","major":"逻辑题","minor":"逻辑推理","question":"某电视综艺节目播出后，导演声称该节目达到当前同类节目的最高水准，因为该节目收视率比同类节目高。以下哪项如果为真，最能削弱上述论证？","options":[{"key":"A","text":"参与该节目的嘉宾对节目评价不一"},{"key":"B","text":"观众本身就非常喜欢看电视综艺节目"},{"key":"C","text":"该导演的微博有几十万条批评此节目的评论"},{"key":"D","text":"节目的水准和收视率并无必然关联"}],"answer":"D","explanation":"论证把“高收视率”当作“高水准”的依据。D直接切断收视率与节目水准之间的联系，削弱力度最强。","source":"logic-practice #5","bad":false,"notice":""},{"id":"l6","major":"逻辑题","minor":"逻辑推理","question":"某网购平台报告显示，亚洲女性在网购服饰、化妆品方面的决定权为88%，在网购家居用品方面的决定权为85%。研究者据此认为，喜爱网购的亚洲女性在家庭中拥有更大的控制权。以下哪项最能反驳？","options":[{"key":"A","text":"喜爱网购的亚洲女性的网购支出只占其家庭消费支出的25%"},{"key":"B","text":"亚洲女性中习惯网购者只占女性总人数的30%左右"},{"key":"C","text":"亚洲女性购买贵重商品时往往会与丈夫共同决定"},{"key":"D","text":"一些亚洲女性经济不独立，对家庭收入没有贡献"}],"answer":"A","explanation":"网购消费若只占家庭总消费的一小部分，就不能由网购中的决定权推出其对整个家庭拥有更大控制权，A直接质疑样本事项的代表性。","source":"logic-practice #6","bad":false,"notice":""},{"id":"l7","major":"逻辑题","minor":"逻辑推理","question":"调查显示，丧偶和离婚人群的总标化死亡率明显高于有配偶人群。由此可以得出的正确推论是（ ）。","options":[{"key":"A","text":"丧偶的人比离婚的人多"},{"key":"B","text":"健康的婚姻有利于人的身心健康"},{"key":"C","text":"有配偶人数是离婚人数的3倍"},{"key":"D","text":"人的平均寿命越来越高"}],"answer":"B","explanation":"材料比较的是不同婚姻状况人群的死亡率，只能支持婚姻状态与身心健康相关。A、C涉及人数，D涉及时间趋势，均无数据支持。","source":"logic-practice #7","bad":false,"notice":""},{"id":"l8","major":"逻辑题","minor":"逻辑推理","question":"牛顿、达尔文、高尔基等人在早年曾被认为学习或智力表现不佳，陶行知也提醒教师不要轻视学生。因此可以推出（ ）。","options":[{"key":"A","text":"小时候成绩越差，长大后的成就越大"},{"key":"B","text":"人的才能表现有早晚之别"},{"key":"C","text":"一个人的成就与受教育多少无关"},{"key":"D","text":"名人小时候的学习成绩都不好"}],"answer":"B","explanation":"多个例子共同说明早期表现不能完全代表后来的才能，人的发展存在早晚差异。其余选项都作了过度概括。","source":"logic-practice #8","bad":false,"notice":""},{"id":"l9","major":"逻辑题","minor":"逻辑推理","question":"陈先生认为北欧人的长寿是其乐观精神的重要原因。贾女士反驳说，这最多只能解释北欧老年人为何乐观。贾女士的反驳最可能假设（ ）。","options":[{"key":"A","text":"北欧青年人不知道北欧人均寿命历来最高"},{"key":"B","text":"只有已经长寿的人，才具备产生上述乐观精神的条件"},{"key":"C","text":"北欧国家都有完善的老年福利制度"},{"key":"D","text":"成熟的人生哲学只有老年人才可能具有"}],"answer":"B","explanation":"若“已经长寿”才会产生这种乐观，那么长寿无法解释尚未长寿的青年人的乐观，正好支撑贾女士的反驳。","source":"logic-practice #9","bad":false,"notice":""},{"id":"l10","major":"逻辑题","minor":"逻辑推理","question":"春节期间铁路在两个城市之间增开临时客车，但实施初期原车次的拥堵仍未缓解。最有说服力的原因是（ ）。","options":[{"key":"A","text":"临时客车乘坐时间太长"},{"key":"B","text":"大多数人喜欢乘坐固定车次"},{"key":"C","text":"人们暂时不了解新增临时客车的停车站和运行时间"},{"key":"D","text":"原车次比临时客车票价便宜很多"}],"answer":"C","explanation":"题干强调“刚实施的一段时间”，C能解释乘客尚未分流的暂时性现象；其余选项缺少题干依据。","source":"logic-practice #10","bad":false,"notice":""},{"id":"l11","major":"逻辑题","minor":"逻辑推理","question":"2000年报考博士生的女性考生录取比例为30%，2004年升为45%，且两年报考者中男女比例基本不变。为了评价“博士研究生中女生比例显著增长”，最重要的比较数据是（ ）。","options":[{"key":"A","text":"两年男性考生的录取比例"},{"key":"B","text":"两年报考博士生的考生总数"},{"key":"C","text":"两年女性考生总数"},{"key":"D","text":"两年男性考生总数"}],"answer":"A","explanation":"女生在最终录取者中的占比还取决于男性录取比例。在报考男女比例稳定的条件下，比较男性录取比例最能判断女生占比是否确实上升。","source":"logic-practice #11","bad":false,"notice":""},{"id":"l12","major":"逻辑题","minor":"逻辑推理","question":"小黄、小白、小蓝三人各提白、黄、蓝色手提包中的一种，且包的颜色都与本人姓氏不同。提白包的人说完后，小黄表示赞同。护士小蓝的提包是什么颜色？","options":[{"key":"A","text":"黄色"},{"key":"B","text":"白色"},{"key":"C","text":"蓝色"}],"answer":"B","explanation":"提白包者既不是小白，也不是随后发言的小黄，所以只能是小蓝。","source":"logic-practice #12","bad":true,"notice":"原题选项残缺、条件矛盾或答案存在歧义，暂不计分。"},{"id":"l13","major":"逻辑题","minor":"逻辑推理","question":"有人用“每个苹果都咬一口”形容毕加索涉猎素描、油画、雕塑、版画、舞台设计、小说、剧本和散文诗等。由此可以推论（ ）。","options":[{"key":"A","text":"毕加索吃苹果时每个只咬一口"},{"key":"B","text":"很多人都像毕加索一样涉猎多种艺术"},{"key":"C","text":"毕加索在艺术领域的许多方面进行过创作尝试"},{"key":"D","text":"毕加索涉及了所有艺术领域"}],"answer":"C","explanation":"“苹果”是比喻，列举内容表明他在多个艺术门类尝试创作；不能扩大为所有艺术领域，也不能作字面理解。","source":"logic-practice #13","bad":false,"notice":""},{"id":"l14","major":"逻辑题","minor":"逻辑推理","question":"在接受检疫的猴子中有1%感染狂犬病，但只有与人及其宠物接触的猴子才接受检疫。专家推测该地猴子总体感染比例远小于1%。哪项最有力地支持该推测？","options":[{"key":"A","text":"与人及宠物接触的猴子不到猴子总数的10%"},{"key":"B","text":"感染狂犬病的宠物约占宠物总数的0.1%"},{"key":"C","text":"健康猴子比其他猴子更愿与宠物接触"},{"key":"D","text":"感染狂犬病的猴子比健康猴子更愿与人及其宠物接触"}],"answer":"D","explanation":"若染病猴更容易进入被检疫样本，样本中的1%就会高估总体感染率，直接支持专家的推测。","source":"logic-practice #14","bad":false,"notice":""},{"id":"l15","major":"逻辑题","minor":"逻辑推理","question":"某理发师只给村里所有不给自己理发的人理发，而且村里所有不为自己理发的人都找他理发。则这位理发师（ ）。","options":[{"key":"A","text":"给自己理发"},{"key":"B","text":"别人为他理发"},{"key":"C","text":"从不理发"},{"key":"D","text":"不存在这样的人"}],"answer":"D","explanation":"若他给自己理发，就不属于“不给自己理发者”，按规则他不该给自己理；若他不给自己理发，又必须由自己给自己理。两种情况均矛盾，因此此人不存在。","source":"logic-practice #15","bad":false,"notice":""},{"id":"l16","major":"逻辑题","minor":"逻辑推理","question":"某公司A、B、C、D、E五辆车周一至周五各限行一天，周末不限行，每天至少四车可上路。已知E周四限行，B昨天限行；从今天起A、C连续四天可上路；D明天可上路。一定正确的是（ ）。","options":[{"key":"A","text":"今天是周六"},{"key":"B","text":"今天是周四"},{"key":"C","text":"A车周三限行"},{"key":"D","text":"C车周五限行"}],"answer":"B","explanation":"E周四限行；若今天为周四，则B昨天（周三）限行，A、C从周四起连续四天可上路，D周五可上路，全部条件吻合。其他日期会与已知限行日或连续可上路条件冲突。","source":"logic-practice #16","bad":false,"notice":""},{"id":"l17","major":"逻辑题","minor":"逻辑推理","question":"某理发店所有理发师都是北方人，所有女员工都是南方人，所有已婚者都是女员工，因此所有已婚者都不是理发师。哪项为真可证明至少一个前提为假？","options":[{"key":"A","text":"店内有一位北方未婚男理发师"},{"key":"B","text":"店内有一位不是理发师的未婚女员工"},{"key":"C","text":"店内有一位南方女理发师"},{"key":"D","text":"店内有一位南方已婚女员工"}],"answer":"C","explanation":"南方女理发师同时满足“理发师”与“南方人”，直接反驳“所有理发师都是北方人”（按题干把南、北作为互斥），所以至少一个前提为假。","source":"logic-practice #17","bad":false,"notice":""},{"id":"l18","major":"逻辑题","minor":"逻辑推理","question":"“任何一条鱼都比任何一条比它小的鱼游得快，所以有一条最大的鱼就有一条游得最快的鱼。”哪项推理模式最相似？","options":[{"key":"A","text":"任何父母都有孩子，所以任何孩子都只有一对父母"},{"key":"B","text":"关于最大偶数与最大奇数的推理"},{"key":"C","text":"关于自然数后继与正奇数的推理"},{"key":"D","text":"任何职位高者都比职位低者权力大，所以有职位最高者就有权力最大者"}],"answer":"D","explanation":"题干结构是“某属性随排序位置单调增加，因此排序最大者也是该属性最大者”。D把体量换成职位、速度换成权力，结构完全一致。","source":"logic-practice #18","bad":false,"notice":""},{"id":"l19","major":"逻辑题","minor":"逻辑推理","question":"“将军总在为上一次战争作准备”；类似地，公务员常在解决几年前已经以某种方式解决的问题，当公众问题引起足够注意时，政府常已无力施加重大影响。以下均为该论证的假设，除了（ ）。","options":[{"key":"A","text":"大多数公众问题常发展到政府难以控制的地步"},{"key":"B","text":"政治、军事领导人常对各自领域的变化反应迟缓"},{"key":"C","text":"问题得到许多公民关心时才对公务员具有重要意义"},{"key":"D","text":"仅以过去经验制定政策很可能无效"},{"key":"E","text":"政府官员对公众政策方针的直接影响很小"}],"answer":"A","explanation":"论证需要领导反应迟缓、问题获得关注较晚以及旧经验可能失效等桥梁；A把“常常失控”直接扩大成大多数问题的普遍状态，并非论证成立所必需。","source":"logic-practice #19","bad":false,"notice":""},{"id":"l20","major":"逻辑题","minor":"逻辑推理","question":"材料认为科幻小说围绕科技幻想及其社会影响展开，因此科幻小说的蓬勃发展是科技发展的结果。哪项最能削弱？","options":[{"key":"A","text":"科幻小说经历了初创、成熟和鼎盛三个时期"},{"key":"B","text":"科技拓展科幻想象空间，科幻也为科技提供人文视角"},{"key":"C","text":"科技只是科幻小说的背景元素，科幻本质仍是完整故事"},{"key":"D","text":"科幻小说展现人类愿望，并推动科技把梦想变为现实"}],"answer":"D","explanation":"D提出反向因果：科幻也可能推动科技发展，从而削弱“科技单向导致科幻蓬勃”的结论。","source":"logic-practice #20","bad":false,"notice":""},{"id":"l21","major":"逻辑题","minor":"逻辑推理","question":"某工厂有些管理人员取得硕士学位，因此有些工科背景大学毕业生取得硕士学位。哪项最能保证论证成立？","options":[{"key":"A","text":"有些管理人员是工科背景大学毕业生"},{"key":"B","text":"有些取得硕士学位的管理人员不是工科背景大学毕业生"},{"key":"C","text":"该工厂所有管理人员都是工科背景大学毕业生"},{"key":"D","text":"该工厂所有工科背景大学毕业生都是管理人员"}],"answer":"C","explanation":"已知至少有一名“管理人员且有硕士学位”。若所有管理人员都是工科背景毕业生，则该人也必为工科背景，从而推出结论。","source":"logic-practice #21","bad":false,"notice":""},{"id":"l22","major":"逻辑题","minor":"逻辑推理","question":"四个班各有正、副班长。三次会议出席者分别为：①小张、小马、小刘、小林；②小马、小陈、小林、小朱；③小宋、小陈、小马、小张；小徐三次均未参加。哪些人在同一班？","options":[{"key":"A","text":"小张与小朱、小马与小徐、小刘与小陈、小林与小宋"},{"key":"B","text":"小张与小陈、小马与小朱、小刘与小徐、小林与小宋"},{"key":"C","text":"小张与小宋、小马与小徐、小刘与小陈、小林与小朱"},{"key":"D","text":"小张与小刘、小马与小宋、小林与小朱、小陈与小徐"}],"answer":"A","explanation":"同一班每次只能出席一人，因此同班两人不能在任何一次会议同时出现。逐一比较出席记录，只有题答中的四组始终不同时出现，并恰好覆盖八人。","source":"logic-practice #22","bad":false,"notice":"根据现有题干重编选项，非原卷选项。"},{"id":"l23","major":"逻辑题","minor":"逻辑推理","question":"公交车失窃，嫌疑人甲说“不是我”，乙说“是丁”，丙说“是乙”，丁说“乙在诬陷”。若四人中只有一人说谎，小偷是谁？","options":[{"key":"A","text":"甲"},{"key":"B","text":"乙"},{"key":"C","text":"丙"},{"key":"D","text":"丁"}],"answer":"B","explanation":"假设乙是小偷：甲“不是我”为真，乙指认丁为假，丙指认乙为真，丁称乙在诬陷也为真，恰好只有乙一人说谎。","source":"logic-practice #23","bad":false,"notice":"根据现有题干重编选项，非原卷选项。"},{"id":"l24","major":"逻辑题","minor":"逻辑推理","question":"旅游团在A、B、C、D、E五城中选择：去A则必须去B；C和D要么都去要么都不去；去E则必须去D；A、B、C中只能去一个。最多可去几个城市？","options":[{"key":"A","text":"1个"},{"key":"B","text":"2个"},{"key":"C","text":"3个"},{"key":"D","text":"4个"}],"answer":"C","explanation":"A若去则B也去，与“A、B、C中只能去一个”矛盾；选B时C、D均不能去，E也不能去；选C时必须同时选D，且还可选E，因此最多为C、D、E三个城市。原资料答案栏写作“CD”，与题问不匹配，此处按条件校正。","source":"logic-practice #24","bad":false,"notice":"根据现有题干重编选项，非原卷选项。"},{"id":"l25","major":"逻辑题","minor":"逻辑推理","question":"六种礼物为H、Z、J、K、L、M，条件为：①只有选择L和J，才能选择H；②若选择L，就不能选J，也不能选K；③只有选择L，才可选择M。已知赵先生选择H，哪项可能是其选择的其他礼物？","options":[{"key":"A","text":"Z和M"},{"key":"B","text":"Z和L"},{"key":"C","text":"J和L"},{"key":"D","text":"J和K"}],"answer":"D（原资料答案）","explanation":"按原资料给出的答案为D。但若严格按题面把①解释为“H→L且J”，就会与②“L→非J”直接矛盾，题目无可行解，说明原题条件疑似缺字或连接词有误。本题在文档中保留原答案并标注该瑕疵。","source":"logic-practice #25","bad":true,"notice":"原题选项残缺、条件矛盾或答案存在歧义，暂不计分。"},{"id":"l26","major":"逻辑题","minor":"逻辑推理","question":"某市今年上半年空气质量整体优良，严重污染天数不足15天，污染天数比去年同期少4天，因而认为今年空气质量好于去年。最能质疑的是（ ）。","options":[{"key":"A","text":"该市去年关停了几家重污染企业"},{"key":"B","text":"该市今年开展了植树造林活动"},{"key":"C","text":"该市严重污染时段一般在下半年"},{"key":"D","text":"该市环保部门今年更新了监测设备"}],"answer":"C","explanation":"题干只比较上半年，却得出全年结论。若严重污染通常集中在下半年，上半年数据就不足以说明全年优于去年。","source":"logic-practice #26","bad":false,"notice":""},{"id":"l27","major":"逻辑题","minor":"逻辑推理","question":"邀请A、B、C、D、E、F六人参会：①A、B至少一人参加；②A、E、F中有两人参加；③B、C要么都去要么都不去；④A、D只有一人参加；⑤C、D只有一人参加；⑥若D不去，E也不去。最后参加的是（ ）。","options":[{"key":"A","text":"A、B、C、F"},{"key":"B","text":"A、C、D、F"},{"key":"C","text":"B、D、E、F"},{"key":"D","text":"B、C、E、F"}],"answer":"A","explanation":"代入A：A、B至少一人；A、E、F中恰有A和F两人；B、C同去；A、D恰一人；C、D恰一人；D不去时E也不去，全部满足。其余选项至少违反一项条件。","source":"logic-practice #27","bad":false,"notice":""},{"id":"l28","major":"逻辑题","minor":"逻辑推理","question":"某学术会议甲组8人。仅1人认识组内3人，3人认识组内2人，4人认识组内1人。若统计属实，最可能的结论是（ ）。","options":[{"key":"A","text":"组长认识人数最多，其他人相互认识较少"},{"key":"B","text":"会议首次举行，大家都是新面孔"},{"key":"C","text":"有些人所说的认识只是曾在电视或报告会上见过"},{"key":"D","text":"组内原来的熟人不多，但原来认识的却是至交"}],"answer":"D","explanation":"“认识”关系应当相互，认识人数总和为1×3+3×2+4×1=13，是奇数，不可能等于无向关系边数的2倍，说明统计口径存在特殊含义。原资料给D，但从严格图论看题目本身存在统计矛盾，结论并不能唯一推出。","source":"logic-practice #28","bad":false,"notice":""},{"id":"l29","major":"逻辑题","minor":"逻辑推理","question":"公交车盗窃案中，甲说“不是我”，乙说“是丁”，丙说“是乙”，丁说“乙在诬陷”。他们中只有三人说真话，扒手是谁？","options":[{"key":"A","text":"甲"},{"key":"B","text":"乙"},{"key":"C","text":"丙"},{"key":"D","text":"丁"}],"answer":"B","explanation":"若乙作案，甲、丙、丁为真，乙为假，恰好三人说真话；其他人作案均不能满足真话人数。","source":"logic-practice #29","bad":false,"notice":""},{"id":"l30","major":"逻辑题","minor":"逻辑推理","question":"研究发现每天久坐超过5小时与大脑内侧颞叶缩小相关，即使其他时间运动量很高也不能改变该趋势，因而认为久坐会影响记忆力。需要补充的前提是（ ）。","options":[{"key":"A","text":"记忆力差的人更喜欢宅在家里"},{"key":"B","text":"帕金森患者常出现记忆衰退和颞叶缩小"},{"key":"C","text":"大脑内侧颞叶包含海马回，而海马回与记忆形成有关"},{"key":"D","text":"久坐对年轻人的影响大于中老年人"}],"answer":"C","explanation":"题干从“颞叶缩小”跳到“记忆力受影响”，C补足颞叶与记忆之间的联系。","source":"logic-practice #30","bad":false,"notice":""},{"id":"l31","major":"逻辑题","minor":"逻辑推理","question":"一项9年追踪研究把6.3万人按烤肉食用量分为5组，208名胰腺癌患者大多集中在烤肉量最高的两组，因此认为大量食用烤肉更易患胰腺癌。最能削弱的是（ ）。","options":[{"key":"A","text":"父母一方患胰腺癌会提高子女患病率"},{"key":"B","text":"长期食用焯食肉类者与长期食用烤肉者患病比例相当"},{"key":"C","text":"大量吃烤肉者中98%喜欢同时喝啤酒且经常如此"},{"key":"D","text":"偏好半熟烤肉者患病比例比偏好全熟者高约60%"}],"answer":"C","explanation":"C指出“喝啤酒”这一与大量吃烤肉高度伴随的混杂变量，患病增加可能由饮酒而非烤肉造成。","source":"logic-practice #31","bad":false,"notice":""},{"id":"l32","major":"逻辑题","minor":"逻辑推理","question":"《不让一个孩子落后》法案实施后，四、八年级英语阅读和数学平均分提高，因此认为改革法案取得惊人成就。以下质疑力度最弱的是（ ）。","options":[{"key":"A","text":"同期十二年级英语阅读平均分明显下降"},{"key":"B","text":"只看英语阅读和数学成绩评价改革很片面"},{"key":"C","text":"改进庞大教育体制需要大量金钱、努力和时间"},{"key":"D","text":"四、八年级相关成绩早在法案通过前就按相同比例逐年提高"}],"answer":"C","explanation":"C只说明改革困难，并不否认该法案已经取得效果；A、B、D分别从年级代表性、评价指标和原有趋势质疑结论。","source":"logic-practice #32","bad":false,"notice":""},{"id":"l33","major":"逻辑题","minor":"逻辑推理","question":"研究人员未在接触过贫铀弹的退伍老兵血细胞中发现染色体异常，因而认为低放射性贫铀弹不会影响健康。最能削弱的是（ ）。","options":[{"key":"A","text":"某地居民起诉军队试验贫铀弹影响健康"},{"key":"B","text":"很多专家致力于解决贫铀弹放射性问题"},{"key":"C","text":"这些退伍老兵后代先天性缺陷率高于正常值"},{"key":"D","text":"未接触贫铀弹者也会患肿瘤或癌症"}],"answer":"C","explanation":"C给出接触者后代存在异常的实证，说明健康影响可能以题干检测没有覆盖的方式表现。","source":"logic-practice #33","bad":false,"notice":""},{"id":"l34","major":"逻辑题","minor":"逻辑推理","question":"不能吸收光电磁波的物体一般透明；半透明物体吸收部分光，又叫滤色体；不透明物体吸收全部光，又叫黑体。透明动物无色、隐蔽性强。因此（ ）。","options":[{"key":"A","text":"有些隐形动物身体透明但可能有色"},{"key":"B","text":"不透明动物能吸收可见光，有明显色彩，隐蔽性差"},{"key":"C","text":"透明且能吸收光电磁波的物体可称为白体"},{"key":"D","text":"红色金鱼属于滤色体"}],"answer":"B","explanation":"按题干分类，不透明物体吸收光，透明动物则无色且隐蔽性强，因此不透明动物相对更有明显色彩、隐蔽性较差。其余选项无依据或与定义冲突。","source":"logic-practice #34","bad":false,"notice":""},{"id":"l35","major":"逻辑题","minor":"逻辑推理","question":"长期饮用高山和火山地带的温泉水，会摄入含氟量较高的水；长期饮用高氟水，牙齿会有白斑。所以（ ）。","options":[{"key":"A","text":"山里人牙齿一定有白斑"},{"key":"B","text":"牙齿有白斑者必是山里人"},{"key":"C","text":"其他地区的人不可能有白斑"},{"key":"D","text":"长期饮用温泉水的山里人牙齿肯定有白斑"}],"answer":"D","explanation":"条件链为“长期饮用该温泉水→摄入高氟水→牙齿白斑”，D完整沿链条推出；A、B、C均扩大了范围或倒置条件。","source":"logic-practice #35","bad":false,"notice":""},{"id":"l36","major":"逻辑题","minor":"逻辑推理","question":"甲一会说种小麦，一会说不种小麦。乙说甲的两种意见都不同意。丙主张种小麦，丁主张种油菜，乙又说丙、丁的意见都不同意。正确判断是（ ）。","options":[{"key":"A","text":"甲的说法正确"},{"key":"B","text":"乙对甲的说法正确"},{"key":"C","text":"乙对丙、丁两人的说法正确"},{"key":"D","text":"乙的两次回答都正确"}],"answer":"C","explanation":"“种小麦”与“不种小麦”互为矛盾，乙不可能同时反对两者，所以对甲的回答错误。丙“种小麦”和丁“种油菜”可以同时被反对（还可选择其他作物），故C正确。","source":"logic-practice #36","bad":false,"notice":""},{"id":"l37","major":"逻辑题","minor":"逻辑推理","question":"小李、小刘、小张分别考上重点大学、一般大学和落榜，且三人的预言只有一个正确，另两个与事实恰好相反。小李说自己考上重点；小刘说自己考不上重点；小张说自己肯定考上。结果是（ ）。","options":[{"key":"A","text":"小李落榜，小刘一般，小张重点"},{"key":"B","text":"小李一般，小刘落榜，小张重点"},{"key":"C","text":"小李落榜，小刘重点，小张一般"},{"key":"D","text":"小李一般，小刘重点，小张落榜"}],"answer":"C","explanation":"代入C：小李预言错误，小刘预言错误，小张预言正确，且三种结果各一人，完全满足。","source":"logic-practice #37","bad":false,"notice":""},{"id":"l38","major":"逻辑题","minor":"逻辑推理","question":"已知：所有纺织工都是工会成员；部分梳毛工是女工；部分纺织工是女工；所有工会成员都投了健康保险；没有梳毛工投健康保险。下列推不出来的是（ ）。","options":[{"key":"A","text":"所有纺织工都投了健康保险"},{"key":"B","text":"有些女工投了健康保险"},{"key":"C","text":"有些女工没有投健康保险"},{"key":"D","text":"工会的部分成员没有投健康保险"}],"answer":"D","explanation":"纺织工→工会成员→投保，且部分纺织工是女工，可得A、B；部分梳毛工是女工且梳毛工均未投保，可得C。无法推出存在未投保的工会成员，故D。","source":"logic-practice #38","bad":false,"notice":""},{"id":"l39","major":"逻辑题","minor":"逻辑推理","question":"周、吴、郑、王四人中仅一人登上卓奥友峰。周说是郑；郑说自己未参加过登山；吴说参加但未登顶；王说自己是吴的候补，若吴未登顶就是王登顶。若只有一人说假话，一定为真的是（ ）。","options":[{"key":"A","text":"社团其他队员也登顶"},{"key":"B","text":"吴或周登顶"},{"key":"C","text":"郑登顶"},{"key":"D","text":"王登顶"}],"answer":"D","explanation":"若郑登顶，则周真、郑假、吴真，而王的条件句因吴未登顶推出王登顶，与“仅一人登顶”冲突。逐项检验后，只有王登顶能使周、郑、吴三句为真而王的表述为唯一假话。","source":"logic-practice #39","bad":false,"notice":""},{"id":"l40","major":"逻辑题","minor":"逻辑推理","question":"很多大公司的新上岗人员没有很好掌握文件写作、数据处理及办事能力，据此批评当前大学课程设置。该论证的前提是（ ）。","options":[{"key":"A","text":"大学没有基本技能课程"},{"key":"B","text":"基本技能对胜任工作很重要"},{"key":"C","text":"公司新上岗人员基本代表当前毕业大学生水平"},{"key":"D","text":"过去大学生接受了更多基本技能教育"}],"answer":"C","explanation":"要从“公司新上岗人员”推到“当前大学课程设置”，必须假定这些新员工能代表当代大学毕业生，C补足样本代表性。","source":"logic-practice #40","bad":false,"notice":""},{"id":"l41","major":"逻辑题","minor":"逻辑推理","question":"合成色素几乎不能提供营养，有些还会危害健康，因此应使用天然色素代替合成色素。最能削弱的是（ ）。","options":[{"key":"A","text":"人体可消解合成色素中的一些毒素"},{"key":"B","text":"天然色素成分复杂，加工中可能生成有害物质"},{"key":"C","text":"天然色素着色力较弱、易褪色"},{"key":"D","text":"天然色素提取困难、成本高"}],"answer":"B","explanation":"结论默认天然色素更安全。B指出天然色素也可能产生有害物质，直接动摇替代方案的安全性依据。","source":"logic-practice #41","bad":false,"notice":""},{"id":"l42","major":"逻辑题","minor":"逻辑推理","question":"教授说，在长子继承原则下，男人第一个妻子生下的第一个男性婴儿首先有继承权。学生用休斯敦夫人的例子反驳：她是父亲唯一妻子的唯一存活孩子并继承全部遗产。学生误解为（ ）。","options":[{"key":"A","text":"男人可以是孩子的父亲"},{"key":"B","text":"女儿不能算第一个出生的孩子"},{"key":"C","text":"只有儿子才能继承财产"},{"key":"D","text":"私生子女不能继承财产"}],"answer":"C","explanation":"教授只说男性长子具有“优先”继承权，并没说女性绝对不能继承。学生把优先条件误解成了排他条件。","source":"logic-practice #42","bad":false,"notice":""},{"id":"l43","major":"逻辑题","minor":"逻辑推理","question":"甲、乙、丙分别是大学、中学、小学教师。大学教师比甲学历高；乙的学历与小学教师不同；小学教师学历比丙低。可以推出（ ）。","options":[{"key":"A","text":"甲是小学教师，乙是中学教师，丙是大学教师"},{"key":"B","text":"甲是中学教师，乙是小学教师，丙是大学教师"},{"key":"C","text":"甲是大学教师，乙是小学教师，丙是中学教师"},{"key":"D","text":"甲是大学教师，乙是中学教师，丙是小学教师"}],"answer":"A","explanation":"大学教师学历高于甲，所以甲不是大学教师；小学教师学历低于丙，所以丙不是小学教师；乙与小学教师学历不同，乙也不是小学教师。因此甲只能是小学教师，丙大学、乙中学。","source":"logic-practice #43","bad":false,"notice":""},{"id":"l44","major":"逻辑题","minor":"逻辑推理","question":"闪电 对于（ ）相当于（ ）对于 看病。","options":[{"key":"A","text":"冰雹—病人"},{"key":"B","text":"暴雨—出院"},{"key":"C","text":"输液—一天"},{"key":"D","text":"打雷—挂号"}],"answer":"D","explanation":"闪电与打雷是通常相伴的先后现象；挂号与看病也是通常相伴的先后环节。","source":"logic-practice #44","bad":false,"notice":""},{"id":"l45","major":"逻辑题","minor":"逻辑推理","question":"贝尔：电话：发明，与之关系相同的是（ ）。","options":[{"key":"A","text":"编辑：编纂：校对"},{"key":"B","text":"工人：汽车：电脑"},{"key":"C","text":"种植：蔬菜：水果"},{"key":"D","text":"司马迁：《史记》：创作"}],"answer":"D","explanation":"贝尔是主体，电话是成果，发明是行为；司马迁、《史记》、创作对应“主体—成果—行为”。","source":"logic-practice #45","bad":false,"notice":""},{"id":"l46","major":"逻辑题","minor":"逻辑推理","question":"“蓝色革命”指人类向水域索取食物的现代农业技术革命。下列与其不符的是（ ）。","options":[{"key":"A","text":"创造鱼类产卵环境并放流幼鱼"},{"key":"B","text":"利用科技在海水中养鱼、长成后捕捞"},{"key":"C","text":"围海造田，大力发展畜产饲料工业"},{"key":"D","text":"改造滩涂、种植海底饲料、建立海底牧场"}],"answer":"C","explanation":"C把水域改为陆地并发展畜产，不是向水域索取食物；其余均属于水产增养殖。","source":"logic-practice #46","bad":false,"notice":""},{"id":"l47","major":"逻辑题","minor":"逻辑推理","question":"若天气晴朗，小刘就去郊游；若妻子不同行、单位有急事或今天不是星期六，小刘就不去郊游。若小刘去郊游，不能判定哪项正确？","options":[{"key":"A","text":"妻子同行"},{"key":"B","text":"天气晴朗"},{"key":"C","text":"单位没有急事"},{"key":"D","text":"今天是星期六"}],"answer":"B","explanation":"由“去郊游”可对后三个否定条件作逆否，推出妻子同行、单位无急事、当天是星期六；但“晴朗→郊游”不能反推“郊游→晴朗”。","source":"logic-practice #47","bad":false,"notice":""},{"id":"l48","major":"逻辑题","minor":"逻辑推理","question":"专家称贫铀弹粉尘只会沉降在爆炸点150米内，因此不会影响200米外的士兵。哪项最能反驳？","options":[{"key":"A","text":"贫铀弹会诱发多种肿瘤"},{"key":"B","text":"当地风很大，粉尘可被吹到40公里外"},{"key":"C","text":"150米内吸入粉尘的士兵出现不适"},{"key":"D","text":"路过居民未出现明显不适"}],"answer":"B","explanation":"专家结论依赖粉尘不会超出150米。B直接否定这一关键前提，使200米外士兵仍可能接触粉尘。","source":"logic-practice #48","bad":false,"notice":""},{"id":"l49","major":"逻辑题","minor":"逻辑推理","question":"校园小树已被浇水。甲说“乙干的”，乙说“不是我干的”，丙说“不是我干的”。三人中两假一真，浇树的是（ ）。","options":[{"key":"A","text":"甲"},{"key":"B","text":"乙"},{"key":"C","text":"丙"},{"key":"D","text":"其他人"}],"answer":"C","explanation":"若丙浇水，则甲指认乙为假、乙否认自己为真、丙否认为假，恰好两假一真。","source":"logic-practice #49","bad":false,"notice":""},{"id":"l50","major":"逻辑题","minor":"逻辑推理","question":"流行病学研究必须对人群进行直接观察，因此它不需要从动物实验跨物种推论到人类。由此最恰当的结论是（ ）。","options":[{"key":"A","text":"在流行病学中，生物间推论只是辅助工具"},{"key":"B","text":"流行病学是一种精确科学"},{"key":"C","text":"在流行病学中，人类可直接作为研究主体"},{"key":"D","text":"动物毒素研究得出结论的速度比流行病学慢"}],"answer":"C","explanation":"题干强调流行病学可直接观察人群，C准确概括。原资料标注A，但“辅助工具”并未由题干推出，故按题意校正为C。","source":"logic-practice #50","bad":false,"notice":""},{"id":"l51","major":"逻辑题","minor":"逻辑推理","question":"若派甲且不派乙参加谈判，就必须至少派丙或丁中的一人。现已确定不派甲。下列哪项安排最能说明原条件不能反推出其他安排？","options":[{"key":"A","text":"派乙，不派丙、丁"},{"key":"B","text":"不派乙，派丙、丁"},{"key":"C","text":"乙、丙、丁都不派"},{"key":"D","text":"乙、丙、丁都派"}],"answer":"C","explanation":"原命题只约束“派甲且不派乙”的情形。不派甲时前件为假，乙、丙、丁可任意安排；C尤其说明不能据此强制派出任何一人。","source":"logic-practice #51","bad":false,"notice":""},{"id":"l52","major":"逻辑题","minor":"逻辑推理","question":"如果“有人发现了外星人造访地球”是真的，则下列哪项最可能是该判断所包含的必要背景？","options":[{"key":"A","text":"外星人原本并不存在"},{"key":"B","text":"外星人造访一定会留下肉眼可见的痕迹"},{"key":"C","text":"地球不适合外星生命停留"},{"key":"D","text":"外星人具有进行星际旅行或探索的能力与行为"}],"answer":"D","explanation":"既然发生了“造访地球”，至少要具备星际旅行或探索行为。A、B、C都不是该事实成立的必要条件。","source":"logic-practice #52","bad":false,"notice":""},{"id":"l53","major":"逻辑题","minor":"逻辑推理","question":"英国一家酒馆让顾客用餐后自行决定付款金额。多数顾客按公平或慷慨的态度结账，实际付款比原价高20%，该酒馆利润也显著高于老板的其他酒馆。哪项最能解释这一营销策略成功？","options":[{"key":"A","text":"部分顾客希望自己显得有教养，愿意付足甚至多付"},{"key":"B","text":"顾客付款低于成本时会被提醒补足差价"},{"key":"C","text":"对过分吝啬的顾客，老板常常无可奈何"},{"key":"D","text":"顾客常不知道菜品实际价格，不知道该付多少"}],"answer":"A","explanation":"顾客为维持公平、体面或慷慨的自我形象，可能按正常价格甚至更高金额付款，直接解释了平均付款和利润上升。","source":"logic-practice #53","bad":false,"notice":""},{"id":"l54","major":"逻辑题","minor":"逻辑推理","question":"老年人常因血脂高出现慢性病。对此，有人完全不理会、随意进食；有人又过度敏感，拒绝所有油分和肉类，反而造成营养不足和失衡。由此可推测（ ）。","options":[{"key":"A","text":"老年人普遍虚弱，应多吃高营养食物补身体"},{"key":"B","text":"保持健康应合理搭配和调节饮食，过与不及都不可取"},{"key":"C","text":"老年人应完全避免含脂类食物"},{"key":"D","text":"老年人难免有慢性病，既不能忽视也不能过分关注"}],"answer":"B","explanation":"材料批评饮食上的两个极端，B准确概括为合理搭配、适度调节。","source":"logic-practice #54","bad":false,"notice":""},{"id":"l55","major":"逻辑题","minor":"逻辑推理","question":"配方奶受阪崎肠杆菌污染可能来自奶粉本身，也可能来自环境、器具或双手。世界卫生组织因此建议用不低于70℃的水冲调婴儿配方奶。该结论的前提是（ ）。","options":[{"key":"A","text":"婴幼儿腹泻的主要原因是阪崎肠杆菌"},{"key":"B","text":"70℃以上的水可杀死阪崎肠杆菌"},{"key":"C","text":"水温低于70℃不会影响奶粉营养"},{"key":"D","text":"绝大多数细菌无法在沸水中存活"}],"answer":"B","explanation":"只有70℃以上的水能杀灭目标细菌，使用这一温度冲调才具有降低污染风险的作用。","source":"logic-practice #55","bad":false,"notice":""},{"id":"l56","major":"逻辑题","minor":"逻辑推理","question":"当前大学课程设置存在一定问题，很多大公司的新上岗人员没有很好掌握文件写作、数据处理和办事能力等基本工作技能。上述论证以下列哪项为前提？","options":[{"key":"A","text":"现在的大学课程没有任何基本技能课程"},{"key":"B","text":"文件写作、数据处理和办事能力对胜任工作很重要"},{"key":"C","text":"公司新上岗人员基本代表当前大学毕业生的水平"},{"key":"D","text":"过去大学生比现在接受了更多基本技能教育"}],"answer":"C","explanation":"要用新上岗人员技能不足评价“当前大学课程设置”，必须假定这些人员能代表当前大学毕业生的总体水平。","source":"logic-practice #56","bad":false,"notice":""},{"id":"l57","major":"逻辑题","minor":"逻辑推理","question":"雄孔雀漂亮的羽毛主要用于吸引雌孔雀，但没人知道漂亮羽毛为何能在求偶中形成竞争优势。一种解释是：雌孔雀更愿意与拥有漂亮羽毛的雄孔雀为偶。该推论的错误是（ ）。","options":[{"key":"A","text":"把人类典型特征归于动物"},{"key":"B","text":"把个别种类结论推广到一类事物的所有种类"},{"key":"C","text":"使用了原则上无法证实或证伪的前提"},{"key":"D","text":"把需要解释的现象本身当作对该现象的解释"}],"answer":"D","explanation":"“漂亮羽毛有竞争优势”与“雌孔雀更愿选择漂亮羽毛者”实质是同一现象的两种表述，没有提供独立原因。","source":"logic-practice #57","bad":false,"notice":""},{"id":"l58","major":"逻辑题","minor":"逻辑推理","question":"MBA应是高级企业管理人才，最重要的是企业家精神。我国很多MBA办学院校条件和质量参差不齐。由此可推知（ ）。","options":[{"key":"A","text":"中国缺的不是MBA数量，而是真正具有企业家精神的MBA"},{"key":"B","text":"中国的MBA都不合格"},{"key":"C","text":"培养真正的MBA必须与国外知名院校联合"},{"key":"D","text":"只有拥有MBA学位的人才能管好企业"}],"answer":"A","explanation":"材料强调数量不少但质量、企业家精神不足，A是适度概括；其余均作了绝对化推断。","source":"logic-practice #58","bad":false,"notice":""},{"id":"l59","major":"逻辑题","minor":"逻辑推理","question":"学界正涌动“亚洲热”，但有关概念并未平等涵盖所有国家和民族：汉语共同体中的“亚洲”常以中国为中心，“世界”又常被描绘成发达国家组成的图景。因此（ ）。","options":[{"key":"A","text":"中国学者的研究水平太低"},{"key":"B","text":"中国就是亚洲，西方就是世界"},{"key":"C","text":"有关亚洲的研究没有必要"},{"key":"D","text":"中国学人做研究时，往往不深究亚洲而讲中华，不计较世界而关注西方"}],"answer":"D","explanation":"D完整对应题干批评的两种以偏概全倾向。","source":"logic-practice #59","bad":false,"notice":""},{"id":"l60","major":"逻辑题","minor":"逻辑推理","question":"在全厂职工大会上，领导驳斥了“谁也不会否认提高产量不是努力工作的结果”这一观点。领导对“提高产量是努力工作的结果”的观点持何态度？","options":[{"key":"A","text":"表示反对"},{"key":"B","text":"表示同意"},{"key":"C","text":"既不同意也不反对"},{"key":"D","text":"讲话与该观点无关"}],"answer":"B","explanation":"原句经多重否定后主张“提高产量不是努力工作的结果”；领导驳斥它，即赞同“提高产量是努力工作的结果”。","source":"logic-practice #60","bad":false,"notice":""},{"id":"l61","major":"逻辑题","minor":"逻辑推理","question":"某市晨曦路两侧几乎全是老年疗养院，居民住宅很少，但附近经营儿童用品的商店很多且生意火爆。哪项最能解释？","options":[{"key":"A","text":"儿童用品物美价廉"},{"key":"B","text":"来疗养的老人多有子女带着孩子陪同，需要购买儿童用品"},{"key":"C","text":"附近居民孩子之间经常互赠物品"},{"key":"D","text":"商店购物环境良好"}],"answer":"B","explanation":"陪同疗养老人的家庭成员带来了大量儿童用品需求，直接解释了居住儿童少而商店兴旺。","source":"logic-practice #61","bad":false,"notice":""},{"id":"l62","major":"逻辑题","minor":"逻辑推理","question":"我国森林覆盖率逐年下降，同时洪涝灾害逐年严重，由此认为森林破坏是洪灾原因。以下哪项使用的方法与之最类似？","options":[{"key":"A","text":"棉花和积雪都疏松多孔且能保温，因此疏松多孔是保温原因"},{"key":"B","text":"两组鸡分别喂精白米和带壳稻米，前者患病、后者不患病，进而发现维生素B₁"},{"key":"C","text":"对装肉鱼的瓶子分别封闭和敞开，只有苍蝇可进入者生蛆，故苍蝇产卵是生蛆原因"},{"key":"D","text":"玻璃罩内逐渐抽出空气，铃声随空气减少而变小，空气抽尽后无声，故声音靠空气传播"}],"answer":"D","explanation":"题干与D都通过两个变量随程度变化而同步变化来作因果推断；B、C是对照实验，A更接近共同属性归因。","source":"logic-practice #62","bad":false,"notice":""},{"id":"l63","major":"逻辑题","minor":"逻辑推理","question":"甲、乙、丙三名学生分别出生在北京、上海、武汉，分别学国际金融、工商管理、外语。已知甲不学国际金融；乙不学外语；学国际金融者不出生在上海；学外语者出生在北京；乙不出生在武汉。甲的专业是（ ）。","options":[{"key":"A","text":"国际金融"},{"key":"B","text":"工商管理"},{"key":"C","text":"外语"},{"key":"D","text":"三种专业都可能"}],"answer":"C","explanation":"若甲学工商管理，则乙、丙须分别学国际金融、外语；外语者出生北京，且乙不在武汉、国际金融者不在上海，会导致出生地分配冲突。故甲只能学外语。","source":"logic-practice #63","bad":false,"notice":""},{"id":"l64","major":"逻辑题","minor":"逻辑推理","question":"甲、乙、丙、丁、戊五人各自就1—5号队员来自哪个洲作两项判断，每人恰有一项正确：甲称3号来自欧洲、2号来自美洲；乙称4号来自亚洲、2号来自大洋洲；丙称1号来自亚洲、5号来自非洲；丁称4号来自非洲、3号来自大洋洲；戊称2号来自欧洲、5号来自美洲。下列哪项一定正确？","options":[{"key":"A","text":"1号来自亚洲，2号来自欧洲"},{"key":"B","text":"2号来自大洋洲，3号来自非洲"},{"key":"C","text":"3号来自欧洲，4号来自非洲"},{"key":"D","text":"4号来自美洲，5号来自非洲"}],"answer":"C","explanation":"逐组代入并满足“每人两项中恰一真”，可得到3号来自欧洲、4号来自非洲；C同时满足各人的真假约束。","source":"logic-practice #64","bad":false,"notice":""},{"id":"l65","major":"逻辑题","minor":"逻辑推理","question":"七个盒子可能装有现金、钻石、黄金、支票中的一种或多种。盒上依次写着：①有些盒子没有现金；②4号盒有钻石；③所有盒子都有黄金；④本盒无钻石；⑤有些盒子没有黄金；⑥本盒有支票；⑦所有盒子都有现金。已知七句话中四句为假。哪项一定正确？","options":[{"key":"A","text":"1号盒有现金"},{"key":"B","text":"2号盒有黄金"},{"key":"C","text":"4号盒有钻石"},{"key":"D","text":"6号盒有支票"}],"answer":"D","explanation":"①与⑦互为矛盾，③与⑤互为矛盾，②与④互为矛盾，这三对各一真一假，共三假。已知共有四假，剩余第⑥句必须为真，因此6号盒有支票。","source":"logic-practice #65","bad":false,"notice":""},{"id":"l66","major":"逻辑题","minor":"逻辑推理","question":"旅行者从旅馆出发到十字路口，东南西北四个方向分别通往饭店、旅馆、书店和火车站。书店在饭店东北方，饭店在火车站西北方。旅行者应往哪个方向去火车站？","options":[{"key":"A","text":"东"},{"key":"B","text":"西"},{"key":"C","text":"南"},{"key":"D","text":"北"}],"answer":"C","explanation":"饭店位于火车站西北方，所以火车站在饭店东南方；结合书店位于饭店东北方和四向唯一分配，可确定火车站在十字路口南侧。","source":"logic-practice #66","bad":false,"notice":""},{"id":"l67","major":"逻辑题","minor":"逻辑推理","question":"法国作家雨果说：“人有了物质才能生存，有了理想才谈得上生活。”这句话强调的是（ ）。","options":[{"key":"A","text":"理想受社会存在制约"},{"key":"B","text":"理想源于现实又高于现实"},{"key":"C","text":"不同的人有不同理想"},{"key":"D","text":"人既要有物质生活，更要有精神生活"}],"answer":"D","explanation":"引文把“生存”与“生活”区分开，强调物质基础之外还需要理想和精神追求。","source":"logic-practice #67","bad":false,"notice":""},{"id":"l68","major":"逻辑题","minor":"逻辑推理","question":"在与外界没有热交换的房间内打开冰箱门，让冰箱正常工作一段时间，房间温度将（ ）。","options":[{"key":"A","text":"降低"},{"key":"B","text":"升高"},{"key":"C","text":"不变"},{"key":"D","text":"无法确定"}],"answer":"B","explanation":"冰箱向房间排出的热量等于从箱内吸收的热量加压缩机做功，净热量增加，故室温升高。","source":"logic-practice #68","bad":false,"notice":""},{"id":"l69","major":"逻辑题","minor":"逻辑推理","question":"顾客不像通常描述的那样容易被操纵，他们知道自己需要什么；他们需要的东西与别人认为其需要的东西可能差别很大。据此可知（ ）。","options":[{"key":"A","text":"广告投资与商品销售不一定成正比"},{"key":"B","text":"大多数人多年只认一个品牌"},{"key":"C","text":"顾客进店前大都知道要买哪个牌子"},{"key":"D","text":"顾客购物时一般不喜欢他人介绍或建议"}],"answer":"A","explanation":"若顾客不易被外部意见操纵，增加广告投入并不必然带来相同比例的销售增长。原资料提示有人选C，但“大都知道具体品牌”比题干更强。","source":"logic-practice #69","bad":false,"notice":""},{"id":"l70","major":"逻辑题","minor":"逻辑推理","question":"一定强度的飓风能吹倒篱笆。昨天刮了一场飓风，但邻居的篱笆依然直立着。所以（ ）。","options":[{"key":"A","text":"邻居今天早上不用修理篱笆"},{"key":"B","text":"邻居的篱笆比你的结实"},{"key":"C","text":"邻居的篱笆能抵抗飓风"},{"key":"D","text":"昨天的风力没有达到足以吹倒篱笆的强度"}],"answer":"D","explanation":"题目预设达到某一强度会吹倒篱笆；既未吹倒，按逆否可推知风力未达到该阈值。其他选项需额外信息。","source":"logic-practice #70","bad":false,"notice":""},{"id":"l71","major":"逻辑题","minor":"逻辑推理","question":"旅行社为三位旅客订票：荷兰人比尔、加拿大人伯托、英国人丹皮，三人分别去荷兰、加拿大、英国。比尔不去荷兰，丹皮不去英国，伯托既不去加拿大也不去英国。正确安排是（ ）。","options":[{"key":"A","text":"伯托去荷兰，丹皮去英国，比尔去加拿大"},{"key":"B","text":"伯托去荷兰，丹皮去加拿大，比尔去英国"},{"key":"C","text":"伯托去英国，丹皮去荷兰，比尔去加拿大"},{"key":"D","text":"伯托去加拿大，丹皮去英国，比尔去荷兰"}],"answer":"B","explanation":"伯托只能去荷兰；剩余加拿大、英国中，丹皮不去英国，只能去加拿大；比尔去英国。","source":"logic-practice #71","bad":false,"notice":""},{"id":"l72","major":"逻辑题","minor":"逻辑推理","question":"A、B、C三位小学教师各教两门且互不重复，共教语文、算术、政治、地理、音乐、美术。已知政治与算术老师是邻居；地理老师比语文老师年长；B最年轻；A常给地理和算术老师讲文学作品；B常与音乐和语文老师一起游泳。三人各教什么？","options":[{"key":"A","text":"A语文政治；B算术美术；C地理音乐"},{"key":"B","text":"A语文美术；B算术政治；C地理音乐"},{"key":"C","text":"A政治音乐；B算术美术；C语文地理"},{"key":"D","text":"A政治美术；B语文算术；C地理音乐"}],"answer":"A","explanation":"A与地理、算术老师均不是同一人，B与音乐、语文老师也不同；结合B最年轻和地理老师年长于语文老师逐项排除，得到唯一分工。","source":"logic-practice #72","bad":false,"notice":"根据现有题干重编选项，非原卷选项。"},{"id":"l73","major":"逻辑题","minor":"逻辑推理","question":"甲、乙、丙会打字，丙、丁会开车，丁、戊会操作电脑。单位需要具备这三项技术，若选人最少，应选（ ）。","options":[{"key":"A","text":"丙、丁"},{"key":"B","text":"甲、丙"},{"key":"C","text":"乙、丙"},{"key":"D","text":"丁、戊"}],"answer":"A","explanation":"丙同时会打字、开车，丁同时会开车、操作电脑；选丙、丁两人即可覆盖全部三项技能，且一人无法覆盖三项。","source":"logic-practice #73","bad":false,"notice":""},{"id":"l74","major":"逻辑题","minor":"逻辑推理","question":"甲、乙、丙、丁四名盗窃嫌疑人中只有一人说真话。甲说“我们四人都偷了手表”；丙说“我没有偷手表”；丁说“有人没有偷手表”。可以推出（ ）。","options":[{"key":"A","text":"四人都偷了手表"},{"key":"B","text":"只有甲偷了手表"},{"key":"C","text":"只有一人没有偷手表"},{"key":"D","text":"丙没有偷手表"}],"answer":"C（按原资料）","explanation":"原资料给C，并提示有人选A。本题题面“每人各偷了一种东西”是否暗含所偷物品不同存在歧义：若至少有人偷的不是表，则丁为唯一真话者，C成立；若允许四人都偷表，则A也可形成一真。为忠于原卷保留C，并注明歧义。","source":"logic-practice #74","bad":true,"notice":"原题选项残缺、条件矛盾或答案存在歧义，暂不计分。"},{"id":"l75","major":"逻辑题","minor":"逻辑推理","question":"某商场失窃，员工甲、乙、丙、丁四人涉案。甲说“是丙作的案”；乙说“我和甲、丁三人至少有一人作案”；丙说“我没作案”；丁说“我们四人都没作案”。若四人中只有一人说真话，可得（ ）。","options":[{"key":"A","text":"甲说真话，作案的是丙"},{"key":"B","text":"乙说真话，作案的是乙"},{"key":"C","text":"丙说真话，作案的是甲"},{"key":"D","text":"丁说真话，四人中无人作案"}],"answer":"A","explanation":"若丙作案，则甲真、乙假、丙假、丁假，恰好一真；其他选项均无法同时满足四句话只有一句为真。","source":"logic-practice #75","bad":false,"notice":""},{"id":"l76","major":"逻辑题","minor":"逻辑推理","question":"黄先生、蓝先生、白先生分别系黄、蓝、白三种颜色的领带，且无人佩戴与自己姓氏同色的领带。结合三人的对话，可确定（ ）。","options":[],"answer":"黄先生系白领带，蓝先生系黄领带，白先生系蓝领带","explanation":"三人均不能佩戴本姓颜色；再结合对话中说话者与被指认颜色不相同的限制，唯一排列为黄—白、蓝—黄、白—蓝。","source":"logic-practice #76","bad":true,"notice":"原题选项残缺、条件矛盾或答案存在歧义，暂不计分。"},{"id":"l77","major":"逻辑题","minor":"逻辑推理","question":"农场中的每个人都是李明的亲戚；李明的唯一孩子是男孩；王林生活在农场里；刘安是李明的丈夫。由此可知（ ）。","options":[{"key":"A","text":"王林是李明的女儿"},{"key":"B","text":"李明生活在农场里"},{"key":"C","text":"王林是李明的亲戚"},{"key":"D","text":"刘安生活在农场里"}],"answer":"C","explanation":"王林生活在农场，而农场中的每个人都是李明的亲戚，因此可直接推出王林是李明的亲戚。","source":"logic-practice #77","bad":false,"notice":""},{"id":"l78","major":"逻辑题","minor":"逻辑推理","question":"小王、小宋、小罗进行乒乓球比赛，约定输者下场。已知小王打了8局，小宋打了5局，小罗有2局没有参加。第9局由谁比赛？","options":[{"key":"A","text":"小王与小宋"},{"key":"B","text":"小宋与小罗"},{"key":"C","text":"小王与小罗"},{"key":"D","text":"无法确定"}],"answer":"C","explanation":"根据总参赛局数和每局两人上场的计数关系，并结合输者下一局下场的轮换规则，可确定第9局为小王对小罗。","source":"logic-practice #78","bad":false,"notice":"根据现有题干重编选项，非原卷选项。"},{"id":"l79","major":"逻辑题","minor":"逻辑推理","question":"按题干设定，纽约时间比香港快13小时。香港时间为6月1日20时，纽约时间为（ ）。","options":[{"key":"A","text":"6月1日7时"},{"key":"B","text":"6月1日9时"},{"key":"C","text":"6月2日7时"},{"key":"D","text":"6月2日9时"}],"answer":"D","explanation":"严格按照题干给定的“快13小时”计算：6月1日20时加13小时，得到6月2日9时。","source":"logic-practice #79","bad":false,"notice":""},{"id":"l80","major":"逻辑题","minor":"逻辑推理","question":"某人把“只有正式党员才可以举手表决”理解为“所有正式党员都可以举手表决”。这一理解（ ）。","options":[{"key":"A","text":"正确，因为充分条件和必要条件可以互换"},{"key":"B","text":"正确，因为二者表达完全相同"},{"key":"C","text":"错误，把必要条件误当成了充分条件"},{"key":"D","text":"错误，把充分条件误当成了必要条件"}],"answer":"C","explanation":"“只有正式党员才可表决”表示“可表决→正式党员”，正式党员只是必要条件，不能反推所有正式党员都有表决资格。","source":"logic-practice #80","bad":false,"notice":""},{"id":"l81","major":"逻辑题","minor":"逻辑推理","question":"甲、乙、丙、丁决定是否去郊游。规则为：若乙去则甲去；若丙去则乙不去；丙一定去；若甲、乙至少一人去则丁去。下列哪种参加组合可能成立？","options":[{"key":"A","text":"甲、乙、丙"},{"key":"B","text":"乙、丙、丁"},{"key":"C","text":"甲、丙、丁"},{"key":"D","text":"甲、乙、丁"}],"answer":"C","explanation":"丙一定去，由“丙去→乙不去”得乙不去。若甲去，则甲、乙至少一人去，丁也去，所以甲、丙、丁可以成立。","source":"logic-practice #81","bad":false,"notice":""},{"id":"l82","major":"逻辑题","minor":"逻辑推理","question":"某地植物病害增多，有人认为是空气污染造成的。下列哪项最能支持这一判断？","options":[{"key":"A","text":"污染较重地区的同类植物发病率明显更高，且排除品种、土壤等因素"},{"key":"B","text":"植物病害有很多种类"},{"key":"C","text":"当地居民也喜欢种植这些植物"},{"key":"D","text":"有些无污染地区也存在少量植物病害"}],"answer":"A","explanation":"A显示污染程度与病害发生存在稳定关联，并控制了替代原因，对因果判断支持最强。","source":"logic-practice #82","bad":false,"notice":""},{"id":"l83","major":"逻辑题","minor":"逻辑推理","question":"土豆在某些条件下会发芽并产生有害物质。由此最合理的生活常识结论是（ ）。","options":[{"key":"A","text":"所有土豆都不能食用"},{"key":"B","text":"土豆一经烹煮就一定无毒"},{"key":"C","text":"发芽、变绿较严重的土豆不宜食用"},{"key":"D","text":"土豆只能在冰箱冷冻保存"}],"answer":"C","explanation":"题干所述风险发生在发芽、变绿等特定状态，C是适度且安全的结论。","source":"logic-practice #83","bad":false,"notice":""},{"id":"l84","major":"逻辑题","minor":"逻辑推理","question":"一项对某市大学生运动会的调查看似矛盾：百米决赛运动员中，60%的受访者说自己的成绩位居该项比赛前20%。若受访者均说真话，哪项解释最合理？","options":[{"key":"A","text":"并不是所有未回答者的名次都在前20%以外"},{"key":"B","text":"其余40%的受访者成绩都在前20%之外"},{"key":"C","text":"参加百米决赛的运动员有80%成绩不理想"},{"key":"D","text":"百米决赛中成绩较差的运动员没有参加调查"}],"answer":"D","explanation":"若调查样本偏向成绩较好的运动员，受访者中“前20%”所占比例便可高达60%，并不与全体名次比例矛盾。","source":"logic-practice #84","bad":false,"notice":""},{"id":"l85","major":"逻辑题","minor":"逻辑推理","question":"文学院有学生为优秀奖学金获得者。除非各学院有学生为优秀奖学金获得者，否则任何学院都不能从学校领取奖学金。计算机学院可以从学校领取奖学金。由此可推出（ ）。","options":[{"key":"A","text":"文学院可以从学校领取奖学金"},{"key":"B","text":"文学院有的学生不是优秀奖学金获得者"},{"key":"C","text":"计算机学院有的学生是优秀奖学金获得者"},{"key":"D","text":"计算机学院有的学生不是优秀奖学金获得者"}],"answer":"C","explanation":"“学院能领取奖学金”以“该学院有优秀奖学金获得者”为必要条件。计算机学院能领取，故其有学生是优秀奖学金获得者。","source":"logic-practice #85","bad":false,"notice":""},{"id":"l86","major":"逻辑题","minor":"逻辑推理","question":"科室就选派小郑、小周谁去基层蹲点有三种意见：①只要小郑去，小周就不去；②只要小周不去，小郑就去；③小郑去。领导同意一种、否定两种。据此可推出（ ）。","options":[{"key":"A","text":"小郑、小周都去"},{"key":"B","text":"小郑、小周都不去"},{"key":"C","text":"小郑去而小周不去"},{"key":"D","text":"小周去而小郑不去"}],"answer":"B","explanation":"若小郑、小周都不去，则①真（前件假），②假，③假，恰好一真。其余安排不能满足“一种意见为真、两种为假”。","source":"logic-practice #86","bad":false,"notice":""},{"id":"l87","major":"逻辑题","minor":"逻辑推理","question":"点煤油灯时，因煤油中的碳原子较多、容易燃烧不完全，煤油灯会冒烟；酒精中碳原子少、着火点低，因此酒精灯（ ）。","options":[{"key":"A","text":"价格比煤油灯便宜"},{"key":"B","text":"比较受欢迎"},{"key":"C","text":"燃烧时不冒烟"},{"key":"D","text":"性能比煤油灯好"}],"answer":"C","explanation":"材料从成分与燃烧状况比较，指向酒精燃烧更充分、少烟或不冒烟；价格、受欢迎程度和总体性能均无法推出。","source":"logic-practice #87","bad":false,"notice":""},{"id":"l88","major":"逻辑题","minor":"逻辑推理","question":"在一种网络游戏中，若玩家在A地拥有旅馆，就必须同时拥有A地和B地；若在C花园拥有旅馆，就必须拥有C花园以及A地、B地两者之一；若拥有B地，还拥有C花园。假如该玩家不拥有B地，可推出（ ）。","options":[{"key":"A","text":"该玩家在A地不拥有旅馆"},{"key":"B","text":"该玩家在C花园拥有一家旅馆"},{"key":"C","text":"该玩家拥有C花园和A地"},{"key":"D","text":"该玩家在A地拥有一家旅馆"}],"answer":"A","explanation":"“A地有旅馆→拥有B地”。已知不拥有B地，由逆否推出A地没有旅馆。","source":"logic-practice #88","bad":false,"notice":""},{"id":"l89","major":"逻辑题","minor":"逻辑推理","question":"“并不是所有的人都不愿意拒绝别人善意的邀请。”这句话是说（ ）。","options":[{"key":"A","text":"有的人不愿意拒绝别人善意的邀请"},{"key":"B","text":"所有人都不愿意拒绝别人善意的邀请"},{"key":"C","text":"所有人都喜欢拒绝别人善意的邀请"},{"key":"D","text":"有些人会拒绝别人善意的邀请"}],"answer":"D","explanation":"“并非所有人都不愿拒绝”等值于“有些人不是不愿拒绝”，即有些人会拒绝。","source":"logic-practice #89","bad":false,"notice":""},{"id":"l90","major":"逻辑题","minor":"逻辑推理","question":"作为世界杯仅存的南美球队，巴西下一场将迎战淘汰了丹麦的英格兰。主帅斯科拉里不愿谈如何与英格兰较量；击败比利时后，他说现在只想好好放松。根据上文，无法知道的是（ ）。","options":[{"key":"A","text":"巴西本届世界杯中不会再与南美球队比赛"},{"key":"B","text":"斯科拉里因准备不充分而不愿谈如何与英格兰较量"},{"key":"C","text":"与比利时的比赛很艰苦，所以赛后斯科拉里如释重负"},{"key":"D","text":"英格兰在与巴西比赛前战胜了丹麦"}],"answer":"B","explanation":"材料只说他不愿谈论，并未说明原因是准备不充分；B属于无依据的原因推断。","source":"logic-practice #90","bad":false,"notice":""},{"id":"l91","major":"逻辑题","minor":"逻辑推理","question":"学校收到两笔匿名捐款，可断定是周、吴、郑、王中的两人所捐。周说“不是我捐的”；吴说“是王捐的”；郑说“是吴捐的”；王说“我肯定没有捐”。已知恰有两人说真话，哪项可能为真？","options":[{"key":"A","text":"吴和王捐"},{"key":"B","text":"周和王捐"},{"key":"C","text":"郑和王捐"},{"key":"D","text":"郑和吴捐"}],"answer":"C","explanation":"若郑和王捐款，则周说“不是我”真，吴说“王捐了”真，郑说“吴捐了”假，王说“我没捐”假，恰好两真两假。因此C可能为真；其余组合不满足恰好两人说真话。","source":"logic-practice #91","bad":false,"notice":""},{"id":"l92","major":"逻辑题","minor":"逻辑推理","question":"某宿舍住四名留学生，分别来自美国、加拿大、韩国、日本，分别在中文、国际金融、法律三个系就学。日本学生单独在国际金融系；韩国学生不在中文系；美国学生与另一人同系；加拿大学生不与美国学生同系。美国学生所在系为（ ）。","options":[{"key":"A","text":"中文系"},{"key":"B","text":"国际金融系"},{"key":"C","text":"法律系"},{"key":"D","text":"中文系或法律系"}],"answer":"D","explanation":"日本学生单独在国际金融系，所以美国学生不在该系；美国学生可以与韩国或其他学生同在中文系或法律系，无法在二者中唯一确定。","source":"logic-practice #92","bad":false,"notice":""},{"id":"l93","major":"逻辑题","minor":"逻辑推理","question":"“科学不是宗教；宗教都主张信仰；所以主张信仰的都不科学。”以下哪项与上述推理同样不成立？","options":[{"key":"A","text":"所有渴望成功的人都努力工作；我不渴望成功；所以我不必努力"},{"key":"B","text":"商品都有使用价值；空气有使用价值；所以空气是商品"},{"key":"C","text":"不刻苦学习的人都成不了技术骨干；小张刻苦学习；所以小张能成为技术骨干"},{"key":"D","text":"台湾人不是北京人；北京人都说汉语；所以说汉语的都不是台湾人"}],"answer":"D","explanation":"题干由两个类别关系不当地推出“凡有共同属性者都不属另一类”。D同样因共享“说汉语”这一属性而作出无效的类别排斥。","source":"logic-practice #93","bad":false,"notice":""},{"id":"l94","major":"逻辑题","minor":"逻辑推理","question":"“小张是百事可乐公司在中国的高级雇员之一。”“那么很可能，小张只喝百事可乐。”第二句话隐含的前提是（ ）。","options":[{"key":"A","text":"百事可乐公司是可口可乐的分公司"},{"key":"B","text":"小张是公司一名并不重要的职员"},{"key":"C","text":"各种可乐喝起来味道非常相近"},{"key":"D","text":"一般而言，所有高级职员只喝本公司的产品"}],"answer":"D","explanation":"从“高级雇员”推出“只喝本公司产品”，需有D所述一般规则作为桥梁。","source":"logic-practice #94","bad":false,"notice":""},{"id":"l95","major":"逻辑题","minor":"逻辑推理","question":"根据人体必需营养元素含量高低评价营养价值：含水量特别高的蔬菜营养价值都低；山药含水量低，所以山药营养价值高。哪项推理与其形式相同？","options":[{"key":"A","text":"恒星都自身发光；金星不是恒星；所以金星不自身发光"},{"key":"B","text":"商品都有使用价值；空气有使用价值；所以空气是商品"},{"key":"C","text":"渴望成功的人都努力；他不努力；所以他不渴望成功"},{"key":"D","text":"欺诈订立的合同都无效；无效合同无约束力；所以无约束力的合同都由欺诈订立"}],"answer":"A","explanation":"题干与A都属于“若P则Q；非P；所以非Q”的否定前件错误。","source":"logic-practice #95","bad":false,"notice":""},{"id":"l96","major":"逻辑题","minor":"逻辑推理","question":"研究发现，一些服饰能否流行，常取决于异性群体对它的评价。由此最能推出（ ）。","options":[{"key":"A","text":"人们选择服饰从不考虑自己感受"},{"key":"B","text":"所有服饰都只为取悦异性"},{"key":"C","text":"同性评价完全不起作用"},{"key":"D","text":"异性的态度可能是服饰采用与流行的重要影响因素"}],"answer":"D","explanation":"D保持“可能、重要影响”的适度表述；A、B、C均把影响因素夸大成唯一决定因素。","source":"logic-practice #96","bad":false,"notice":""},{"id":"l97","major":"逻辑题","minor":"逻辑推理","question":"Jane说：文章指出孩子长时间看电视会使手眼协调变差，因此必须限制Jacqueline和Mildred看电视。Alan反驳：文章只说3岁以下孩子会受影响，而两人均为10岁，所以不必限制。Alan的论证犯了什么错误？","options":[{"key":"A","text":"所依赖根据与Jane的根据完全相同"},{"key":"B","text":"把“削弱支持某结论的论据”与“证明该结论本身为假”混为一谈"},{"key":"C","text":"没有涉及Jane的主要论点，只关注枝节"},{"key":"D","text":"诉诸了不相关的权威"}],"answer":"B","explanation":"年龄信息削弱了Jane援引文章的支持力度，但不能证明“完全不必限制看电视”；Alan把论据不足当成结论必假。","source":"logic-practice #97","bad":false,"notice":""},{"id":"l98","major":"逻辑题","minor":"逻辑推理","question":"对穿鞋来说，合脚的鞋比过大的鞋好；但寒冷天气里，尺寸稍大的毛衣与合身毛衣区别并不大。这意味着（ ）。","options":[{"key":"A","text":"不合脚的鞋不能御寒"},{"key":"B","text":"毛衣大小只是式样问题，与功能无关"},{"key":"C","text":"不合身的衣物有时仍有穿用价值"},{"key":"D","text":"买礼物时式样不如用途重要"}],"answer":"C","explanation":"稍大的毛衣虽然不完全合身，仍能发挥保暖功能，故C是恰当概括。","source":"logic-practice #98","bad":false,"notice":""},{"id":"l99","major":"逻辑题","minor":"逻辑推理","question":"名字固然只是符号，姓氏也只是符号。姓氏可作为传统习惯保留，但宗法社会对姓氏的神秘主义错误观念必须彻底戳穿。这意味着（ ）。","options":[{"key":"A","text":"名字和姓氏没有任何意义"},{"key":"B","text":"姓名是代表一个人的符号"},{"key":"C","text":"儿子应该跟父亲姓"},{"key":"D","text":"名字好坏会影响人的命运"}],"answer":"B","explanation":"材料明确把姓名界定为符号，同时反对赋予姓氏神秘意义，B符合。","source":"logic-practice #99","bad":false,"notice":""},{"id":"l100","major":"逻辑题","minor":"逻辑推理","question":"甲部落的人总说真话，乙部落的人总说假话。旅行者遇到土著A，A说自己来自甲部落。后来A去问土著B属于哪个部落，回来转述：“B说自己来自甲部落。”可判断（ ）。","options":[{"key":"A","text":"A来自甲，B来自乙"},{"key":"B","text":"A来自乙，B来自甲"},{"key":"C","text":"A来自甲，B所属部落不明"},{"key":"D","text":"A所属不明，B来自乙"},{"key":"E","text":"A、B所属部落均不明"}],"answer":"C","explanation":"A若来自乙便不能如实转述“B说自己来自甲”，而无论B属于哪部落，对“你是否来自甲”都可能回答“是”。因此A来自甲，B无法确定。","source":"logic-practice #100","bad":false,"notice":""},{"id":"l101","major":"逻辑题","minor":"逻辑推理","question":"要详尽了解社会现象、探索规律，即使是地区性研究也要走进现实社会搜集资料；要明白因果、建立理论，也需要实质资料验证。由此可得（ ）。","options":[{"key":"A","text":"社会研究者一定同时从事实践工作"},{"key":"B","text":"从事社会研究不能不从实际工作中收集资料"},{"key":"C","text":"依据实质资料的社会研究不具有理论性"},{"key":"D","text":"社会研究只需有实质资料即可"}],"answer":"B","explanation":"材料反复强调实地收集资料是社会研究的必要环节，B概括恰当。","source":"logic-practice #101","bad":false,"notice":""},{"id":"l102","major":"逻辑题","minor":"逻辑推理","question":"林肯说：“最高明的骗子，可能在某个时刻欺骗所有人，也可能在所有时刻欺骗某些人，但不可能在所有时刻欺骗所有人。”若此断定为真，下列哪项为假？","options":[{"key":"A","text":"林肯可能在某个时刻受骗"},{"key":"B","text":"林肯可能在任何时候都不受骗"},{"key":"C","text":"骗子也可能在某个时刻受骗"},{"key":"D","text":"不存在某个时刻所有的人都必然不受骗"},{"key":"E","text":"不存在某一时刻有人可能不受骗"}],"answer":"D","explanation":"原资料答案标为D。本题量词表述较绕，D与引文“某个时刻可能欺骗所有人”的可能性关系存在冲突，故按原卷保留。","source":"logic-practice #102","bad":false,"notice":""},{"id":"l103","major":"逻辑题","minor":"逻辑推理","question":"甲、乙、丙、丁、戊五个学习小组，每组至少有一人学法律。下列哪项必然正确？","options":[{"key":"A","text":"某一小组的人都学法律"},{"key":"B","text":"五个小组中至少有五人学法律"},{"key":"C","text":"对每个人而言，同组其余人中至少有人学法律"},{"key":"D","text":"没有法律专业学生的小组至少有一个"}],"answer":"B","explanation":"五个不同小组每组至少一名法律专业学生，所以总计至少五名。","source":"logic-practice #103","bad":false,"notice":""},{"id":"l104","major":"逻辑题","minor":"逻辑推理","question":"对优秀企业家来说，金银价值再高也比不上高回报的投资机会，因此在市场经济发达时代，信息是最有价值的商品。该论证作出的假设是（ ）。","options":[{"key":"A","text":"金银并非最有价值的商品"},{"key":"B","text":"信息的价值高不可估"},{"key":"C","text":"企业家比一般人更注重把握投资机会"},{"key":"D","text":"若能获得投资机会的信息，就可能带来丰厚利润"}],"answer":"D","explanation":"要由投资机会的高价值推出信息价值，必须假设有关机会的信息能帮助获得回报。扫描件答案残缺，本整理按论证结构确定为D。","source":"logic-practice #104","bad":false,"notice":""},{"id":"l105","major":"逻辑题","minor":"逻辑推理","question":"研究显示，在舒适环境工作的人员比在不舒适环境工作的人员生产效率高25%，于是认为改善工作环境可提高生产率。哪项最能削弱？","options":[{"key":"A","text":"生产率低者每天在工作场所的时间通常更少"},{"key":"B","text":"舒适环境更能激励员工努力"},{"key":"C","text":"生产率高的员工通常把舒适办公场所作为奖励"},{"key":"D","text":"生产率高者认识错误的时间不比低者长"}],"answer":"C","explanation":"C表明因果方向可能相反：并非舒适环境导致高效率，而是高效率者获得了舒适环境。","source":"logic-practice #105","bad":false,"notice":""},{"id":"l106","major":"逻辑题","minor":"逻辑推理","question":"某国调查发现近三年中学生吸烟人数逐年下降，调查组据此断言吸烟的青少年人数正逐渐减少。哪项若真，会使结论受到怀疑？","options":[{"key":"A","text":"下一年因经费紧张不再调查中学生"},{"key":"B","text":"国际香烟进入国内市场，价格下降"},{"key":"C","text":"大部分吸烟青少年不是中学生"},{"key":"D","text":"近三年反对吸烟的中学生增加"}],"answer":"C","explanation":"调查样本只涵盖中学生，而结论推广到全部青少年。若大部分吸烟青少年不在样本中，样本缺乏代表性。","source":"logic-practice #106","bad":false,"notice":""},{"id":"l107","major":"逻辑题","minor":"逻辑推理","question":"白处长说：“缺乏自律的人不能被录取为X学校的老师。”对这句话理解正确的是（ ）。","options":[{"key":"D","text":"某某以前是X学校的老师，所以某某是自律的"}],"answer":"D","explanation":"“缺乏自律→不能录取”逆否为“被录取为老师→并非缺乏自律”，即被录取者具有自律性。扫描件仅保留D项。","source":"logic-practice #107","bad":true,"notice":"原题选项残缺、条件矛盾或答案存在歧义，暂不计分。"},{"id":"l108","major":"逻辑题","minor":"逻辑推理","question":"可以驳倒“凡是植物都是绿色的”这一假判断的是（ ）。","options":[{"key":"A","text":"凡是植物都不是绿色的"},{"key":"B","text":"有的植物是绿色的"},{"key":"C","text":"有些植物不是绿色的"},{"key":"D","text":"有些绿色的东西是植物"}],"answer":"C","explanation":"一个反例“有些植物不是绿色的”即可否定全称命题。原资料标注B，属明显误标，故校正为C。","source":"logic-practice #108","bad":false,"notice":""},{"id":"l109","major":"逻辑题","minor":"逻辑推理","question":"如果“鱼和熊掌不可兼得”是不可改变的事实，那么哪项一定为真？","options":[{"key":"A","text":"鱼可得但熊掌不可得"},{"key":"B","text":"熊掌可得但鱼不可得"},{"key":"C","text":"鱼和熊掌都不可得"},{"key":"D","text":"如果鱼不可得，那么熊掌可得"},{"key":"E","text":"如果鱼可得，那么熊掌不可得"}],"answer":"E","explanation":"“不可兼得”表示不能同时得到二者，等值于“若得到鱼，则得不到熊掌”（也等值于其逆否）。","source":"logic-practice #109","bad":true,"notice":"原题选项残缺、条件矛盾或答案存在歧义，暂不计分。"},{"id":"l110","major":"逻辑题","minor":"逻辑推理","question":"并非小张既高又胖。如果这一断定为真，则下列哪项一定为真？","options":[{"key":"A","text":"小张高但不胖"},{"key":"B","text":"小张胖但不高"},{"key":"C","text":"如果小张不高，那么他一定胖"},{"key":"D","text":"如果小张高，那么他一定不胖"}],"answer":"D","explanation":"“并非既高又胖”等值于“不高或不胖”，也等值于“如果高，那么不胖”。","source":"logic-practice #110","bad":false,"notice":""},{"id":"l111","major":"逻辑题","minor":"逻辑推理","question":"本届运动会上，所有参加4×100米比赛的运动员都参加了100米比赛。再加入哪项，可有效推出“有些参加200米比赛的田径运动员没有参加4×100米比赛”？","options":[{"key":"A","text":"有些参加200米比赛的运动员也参加了100米比赛"},{"key":"B","text":"有些参加4×100米比赛的运动员没有参加200米比赛"},{"key":"C","text":"有些没有参加100米比赛的运动员参加了200米比赛"},{"key":"D","text":"有些没有参加200米比赛的运动员也没有参加100米比赛"}],"answer":"C","explanation":"4×100米参赛者都参加100米。若某200米参赛者没有参加100米，则按逆否必未参加4×100米，正好推出题目结论。","source":"logic-practice #111","bad":false,"notice":""},{"id":"l112","major":"逻辑题","minor":"逻辑推理","question":"艾艾把新房卧室改成大书房，平时在书房画设计图，并在阳台设健身区。冬夜，除非下雪或者刮风，否则她会在阳台做瑜伽。根据以上陈述，艾艾在无风的冬夜会怎样？","options":[{"key":"A","text":"一定在画设计图"},{"key":"B","text":"一定在阳台做瑜伽"},{"key":"C","text":"如果没有下雪，她就在画设计图"},{"key":"D","text":"如果没有下雪，她就在阳台做瑜伽"}],"answer":"D","explanation":"“除非下雪或刮风，否则做瑜伽”即“既不下雪也不刮风→做瑜伽”。已知无风，再加无雪即可推出做瑜伽。","source":"logic-practice #112","bad":false,"notice":""},{"id":"l113","major":"逻辑题","minor":"逻辑推理","question":"“喜欢”“棒极了”等有意义词语可引起积极反应，“邪恶”“卑鄙”等可引起消极反应。实验又发现许多无意义词语也能引起积极或消极反应，由此认为人们对词语的反应不仅受词义影响，也受词语发音影响。“许多无意义的词语能引起积极或消极反应”在论证中的作用是（ ）。","options":[{"key":"A","text":"它是结论，唯一证据是词义和发音都会产生影响"},{"key":"B","text":"它是前提，用来支持反应不仅受词义影响，也受发音影响"},{"key":"C","text":"它是前提，用来支持所有词语都能引起积极或消极反应"}],"answer":"B","explanation":"无意义词没有通常词义却仍能引起反应，这一实验事实作为前提，支持“除词义外，发音等形式也会产生影响”的结论。","source":"logic-practice #113","bad":true,"notice":"原题选项残缺、条件矛盾或答案存在歧义，暂不计分。"},{"id":"l114","major":"逻辑题","minor":"逻辑推理","question":"调查显示，某市近三年的严重刑事案件中60%为已记录在案的350名惯犯所为；同时，严重刑事案件作案者半数以上是吸毒者。若均为真，哪项一定或可能成立？","options":[{"key":"A","text":"350名惯犯中一定有吸毒者"},{"key":"B","text":"350名惯犯中大多数是吸毒者"},{"key":"C","text":"350名惯犯中可能没有吸毒者"},{"key":"D","text":"吸毒者大多数在350名惯犯中"}],"answer":"C","explanation":"60%是案件比例，“半数以上”是作案者比例，两者分母不同，无法保证350名惯犯与吸毒者必有重合；在不违反题干的模型中，二者可能不重合。","source":"logic-practice #114","bad":false,"notice":""},{"id":"l115","major":"逻辑题","minor":"逻辑推理","question":"平反，是对处理错误的案件进行纠正。哪项最确切地说明该定义不严格？","options":[{"key":"A","text":"对平反的客体应具体分析，平反不等于没有错误"},{"key":"B","text":"对原来重罪轻判的案件进行纠正不应称为平反"},{"key":"C","text":"对案件是否处理错误，应有明确标准"},{"key":"D","text":"应说明平反的主体及其权威性"}],"answer":"B","explanation":"“纠正处理错误的案件”外延过宽：纠正重罪轻判也是纠错，但通常不叫平反。B给出反例，最直接揭示定义外延不当。","source":"logic-practice #115","bad":false,"notice":""},{"id":"l116","major":"逻辑题","minor":"逻辑推理","question":"一次数学测验后，老师说第一名是A、B、C、D、E、F六位同学中的一位。甲说“第一名要么是A，要么是C”；乙说“第一名肯定不是D”；丙说“第一名不可能是B和E”；丁说“第一名如果不是D，就不是F”。老师说只有一人猜对。可以推出（ ）。","options":[{"key":"A","text":"甲对了"},{"key":"B","text":"乙对了"},{"key":"C","text":"丙对了"},{"key":"D","text":"丁对了"}],"answer":"B","explanation":"把六个候选人逐一代入四人的判断，只有满足“乙真、其余三人假”的情形符合“恰一人猜对”，故选B。","source":"logic-practice #116","bad":false,"notice":""},{"id":"l117","major":"逻辑题","minor":"逻辑推理","question":"职业成功不仅受能力制约，也与兴趣、爱好密切相关。取得卓越成就者不仅有一定能力，而且往往对所从事的工作有强烈兴趣和执着。由此可得（ ）。","options":[{"key":"A","text":"执着的兴趣往往是职业成功的重要条件"},{"key":"B","text":"职业成功的人都是具有卓越能力的人"},{"key":"C","text":"职业能否成功关键只看机会"},{"key":"D","text":"职业成功的人一定不是能力最强的人"}],"answer":"A","explanation":"材料直接强调兴趣与执着对成功的重要作用。B、C、D都作了材料未支持的绝对化推断。","source":"logic-practice #117","bad":false,"notice":""},{"id":"l118","major":"逻辑题","minor":"逻辑推理","question":"南极某种鱼的血液和体液中有防冻蛋白，使其得以在冰冷海水中存活。如今该鱼类生存面临挑战，有人认为是海水升温导致的。哪项最能支持？","options":[{"key":"A","text":"海水温度上升会使溶氧量下降，缺氧使防冻蛋白变性、易积于血管并缩短鱼的寿命"},{"key":"B","text":"防冻蛋白可防止水分子凝结；气候变暖使其变得不再必要"},{"key":"C","text":"南极鱼在低温稳定海水中可持续演化，温暖海水不利于其多样性"},{"key":"D","text":"并非所有南极物种都具有防冻蛋白"}],"answer":"A","explanation":"A给出“升温→溶氧下降→蛋白异常→寿命缩短”的完整因果机制，直接支持海水升温造成生存挑战。","source":"logic-practice #118","bad":false,"notice":""},{"id":"l119","major":"逻辑题","minor":"逻辑推理","question":"胼胝体是连接大脑两半球的神经纤维束。音乐家的胼胝体平均比非音乐家大，且约7岁开始训练的成年音乐家差异尤其明显。因此，特别是幼年开始的音乐训练会导致大脑结构变化。该论证依赖的假设是（ ）。","options":[{"key":"A","text":"音乐家开始训练前，其胼胝体并不比同龄非音乐家大"},{"key":"B","text":"成年后进行音乐训练不会引起任何大脑结构变化"},{"key":"C","text":"所有约7岁开始训练的音乐家胼胝体体积都几乎相同"},{"key":"D","text":"成年非音乐家童年未参加过任何促进胼胝体发育的活动"}],"answer":"A","explanation":"要把相关性解释为训练导致变化，必须排除训练前就已存在结构差异的可能，A正是这一必要假设。","source":"logic-practice #119","bad":false,"notice":""},{"id":"l120","major":"逻辑题","minor":"逻辑推理","question":"H市交通管理部门称，今年市区道路通行比去年明显改善，是因为聘用了大量交通协管员。哪项最能削弱？","options":[{"key":"A","text":"今年初H市曾召开会议研究和整顿交通问题"},{"key":"B","text":"许多专家认为聘用大量协管员成本巨大、得不偿失"},{"key":"C","text":"今年初市区道路新建扩建工程刚刚结束"},{"key":"D","text":"今年H市严格限制车辆驶入市区，许多大货车、外地车在高峰期不能进入"}],"answer":"D","explanation":"D给出足以直接改善通行的强替代原因，削弱“改善源于协管员”的因果归因。原资料标注B，但成本高低不影响因果是否成立，故校正为D。","source":"logic-practice #120","bad":false,"notice":""},{"id":"l121","major":"逻辑题","minor":"逻辑推理","question":"肥皂由油脂和烧碱熬制而成，约含30%水分。晾晒会使水分蒸发、肥皂干裂，还会使油脂和烧碱分离并发生变化，导致去污能力降低。由此可推出（ ）。","options":[{"key":"A","text":"干裂肥皂加回30%水分就一定恢复去污能力"},{"key":"B","text":"纯碱完全没有去污能力"},{"key":"C","text":"肥皂缺少油脂或烧碱中的任何一种就绝对无法去污"},{"key":"D","text":"肥皂中的水分有助于使油脂和烧碱保持结合状态"}],"answer":"D","explanation":"水分蒸发与成分分离、去污力下降相伴，合理推出水分对维持两者结合状态有作用；A、B、C均过强。","source":"logic-practice #121","bad":false,"notice":""},{"id":"l122","major":"逻辑题","minor":"逻辑推理","question":"“酒醉吐真言”。小刘现在并没有喝酒。下列说法正确的是（ ）。","options":[{"key":"A","text":"小刘说的是假话"},{"key":"B","text":"小刘说的是真话"},{"key":"C","text":"小刘从不说真话"},{"key":"D","text":"小刘可能说真话，也可能说假话"}],"answer":"D","explanation":"“酒醉→说真话”不能由“未酒醉”推出真假；否定前件无法否定或肯定后件。","source":"logic-practice #122","bad":false,"notice":""},{"id":"l123","major":"逻辑题","minor":"逻辑推理","question":"某地出现严重雾霾，一些家长提议在学校安装空气净化器，但专家认为学校可能不太适合安装。哪项最能加强专家观点？","options":[{"key":"A","text":"空气净化器不能完全替代室内通风"},{"key":"B","text":"适合大空间的净化器功率很大，可能使学校电网超负荷"},{"key":"C","text":"市面上空气净化器质量参差不齐"},{"key":"D","text":"净化器噪音可能影响孩子学习"}],"answer":"B","explanation":"B指出学校安装满足大空间需求的设备会带来电网承载方面的系统性困难，最直接支持“不适合安装”。","source":"logic-practice #123","bad":false,"notice":""},{"id":"l124","major":"逻辑题","minor":"逻辑推理","question":"图书馆失窃，四名保管员供述：甲说“我们四人都没作案”；乙说“我们中有人作案”；丙说“乙和丁至少有一人没作案”；丁说“我没作案”。若两人真、两人假，成立的是（ ）。","options":[{"key":"A","text":"说真话的是甲和丁"},{"key":"B","text":"说真话的是乙和丙"},{"key":"C","text":"说真话的是甲和丙"},{"key":"D","text":"说真话的是乙和丁"}],"answer":"B","explanation":"甲与乙互为矛盾，必一真一假。代入丙、丁陈述并要求总计两真，可确定乙、丙为真，甲、丁为假。","source":"logic-practice #124","bad":false,"notice":""},{"id":"l125","major":"逻辑题","minor":"逻辑推理","question":"研究者提出：向台风形成区域上空喷洒海水水滴，增强云层对日光的反射，台风便不能聚集足够能量，从而可阻止其前进。该结论需补充的前提是（ ）。","options":[{"key":"A","text":"喷到空中的水滴能在云层之上重新聚集"},{"key":"B","text":"人工制造的云层会影响邻近地区降雨"},{"key":"C","text":"台风经过时常伴有大风和暴雨"},{"key":"D","text":"台风前进的动力来源于海面受日光照射产生的热能"}],"answer":"D","explanation":"只有台风能量确实来自日照加热海面，增强反射、减少日照才会切断其能量来源；D建立了措施与结论间的桥梁。","source":"logic-practice #125","bad":false,"notice":""},{"id":"l126","major":"逻辑题","minor":"逻辑推理","question":"教授认为，美国、加拿大早已招收写作学硕博，而我们还在争取授予权，这反映了对应用性、技能性学科的不同态度。哪一问题对评估该论证最重要？","options":[{"key":"A","text":"若允许招收写作学硕博，会有多少人报考"},{"key":"B","text":"我们的师资和研究水平是否具备招生条件"},{"key":"C","text":"我们在写作学之外的其他应用性、技能性学科是否招收硕博"},{"key":"D","text":"我们是否应该重视应用性、技能性学科硕博培养"}],"answer":"C","explanation":"教授把写作学个案上升为对整个应用性、技能性学科的态度。考察其他同类学科的做法，最能检验这一概括是否成立。","source":"logic-practice #126","bad":false,"notice":""},{"id":"l127","major":"逻辑题","minor":"逻辑推理","question":"某市学生足球赛第二轮有6支实力相当的队伍。此前甲胜乙、乙胜丙，明天甲与丙比赛。从逻辑上应怎样预测？","options":[{"key":"A","text":"甲肯定会赢"},{"key":"B","text":"丙肯定会赢"},{"key":"C","text":"两队一定战平"},{"key":"D","text":"甲很可能赢，但丙也有机会"}],"answer":"D","explanation":"比赛胜负不具有严格传递性。既往结果可提供有限倾向，却不能推出必然结果，D最审慎。","source":"logic-practice #127","bad":false,"notice":""},{"id":"l128","major":"逻辑题","minor":"逻辑推理","question":"有人认为人工智能以模拟人的思维为目标，就应深入研究思维的生理和物理机制。题干用“现代飞机的设计制造并不依赖对鸟的持续研究”作类比反驳。所作类比包括：Ⅰ把对人思维的模拟比作对鸟飞行的模拟；Ⅱ把人工智能研究比作飞机设计制造；Ⅲ把飞机飞行比作鸟的飞行。正确的是（ ）。","options":[{"key":"A","text":"只有Ⅰ"},{"key":"B","text":"只有Ⅱ"},{"key":"C","text":"只有Ⅲ"},{"key":"D","text":"只有Ⅰ和Ⅱ"}],"answer":"D","explanation":"类比的两个对应关系是“模拟人思维—模拟鸟飞行”和“人工智能研究—飞机设计制造”；Ⅲ只是被比较对象的现象，不是论证中的类比关系。","source":"logic-practice #128","bad":false,"notice":""},{"id":"l129","major":"逻辑题","minor":"逻辑推理","question":"A村人星期一、三、五说谎，B村人星期二、四、六说谎，其余日子说真话。一天，两村各一人都说“前天是我说谎的日子”。这一天最可能是（ ）。","options":[{"key":"A","text":"星期日或星期五"},{"key":"B","text":"星期六或星期三"},{"key":"C","text":"星期四或星期二"},{"key":"D","text":"星期三或星期一"}],"answer":"D","explanation":"逐日核对两人的当天真假及“前天是否为说谎日”，共同可行日包含星期一。按原题选项，D是唯一包含可行日的选项。","source":"logic-practice #129","bad":false,"notice":""},{"id":"l130","major":"逻辑题","minor":"逻辑推理","question":"食盐主要成分是氯化钠，还可能含易吸收空气中水分的氯化镁，因此粗盐容易受潮；精盐中氯化钠纯度较高，不易吸水。这意味着（ ）。","options":[{"key":"A","text":"精盐也一定会受潮"},{"key":"B","text":"精盐一定比粗盐价格高"},{"key":"C","text":"精盐不易受潮"},{"key":"D","text":"炼制精盐是今后盐业发展的唯一趋势"}],"answer":"C","explanation":"题干直接说明精盐较纯、吸水性较弱，因此不易受潮；价格和产业趋势均未涉及。","source":"logic-practice #130","bad":false,"notice":""},{"id":"l131","major":"逻辑题","minor":"综合逻辑","question":"甲、乙、丙一起打乒乓球，每局两人比赛、另一人休息，且每局输方下一局休息。比赛结束后，甲休息2局，乙共打8局，丙共打5局。参加第9局比赛的是（ ）。","options":[{"key":"A","text":"甲和乙"},{"key":"B","text":"甲和丙"},{"key":"C","text":"乙和丙"},{"key":"D","text":"甲，另一人不确定"},{"key":"E","text":"丙，另一人不确定"}],"answer":"A","explanation":"甲休息2局，说明乙、丙共同比赛2局；乙共打8局，所以甲、乙共同比赛6局；丙共打5局，所以甲、丙共同比赛3局。总计11局，丙共休息6局。因输者下一局休息，丙不能连续休息，所以第9局后丙休息，甲、乙比赛。","source":"logic-practice #131","bad":false,"notice":""},{"id":"l132","major":"逻辑题","minor":"综合逻辑","question":"若原有前提为“所有天鹅都是白的，澳洲黑天鹅是天鹅”，再加入“澳洲黑天鹅不是白的，但它们确实是天鹅”，下列陈述中仍不能确定真假的是：①并非所有天鹅都是白的；②有的天鹅是白的；③所有天鹅都不是白的；④有的天鹅不是白的；⑤所有天鹅都是白的。","options":[{"key":"A","text":"仅②"},{"key":"B","text":"仅③"},{"key":"C","text":"仅②和③"},{"key":"D","text":"仅①和②"},{"key":"E","text":"①②③④⑤"}],"answer":"C","explanation":"加入新前提后，④为真，因而①为真、⑤为假；但题干没有保证存在白天鹅，所以②不能确定，也不能排除除黑天鹅外还存在白天鹅，因此③也不能确定。原资料答案字样与解析不一致，本整理按解析和严格逻辑校正为C。","source":"logic-practice #132","bad":false,"notice":""},{"id":"l133","major":"逻辑题","minor":"综合逻辑","question":"共有10个小朋友玩丢手绢。只有1人给另外3人丢过手绢，有3人各给另外2人丢过手绢，其余每人各给另外1人丢过手绢。哪项正确？","options":[{"key":"A","text":"每个小朋友都被其他人丢过手绢"},{"key":"B","text":"每个小朋友都给其他人丢过手绢"},{"key":"C","text":"无法确定是否有人从未给别人丢过手绢"}],"answer":"B","explanation":"1人、3人和其余6人都被明确规定至少给别人丢过一次，所以每个小朋友都给别人丢过。至于是否每个人都收到过，题干不能保证。","source":"logic-practice #133","bad":true,"notice":"原题选项残缺、条件矛盾或答案存在歧义，暂不计分。"},{"id":"l134","major":"逻辑题","minor":"综合逻辑","question":"导演组终审六个节目：歌曲A、歌曲B、相声C、相声D、舞蹈E、魔术F。规则为：①A、B至少通过一个；②若C或D中任一个不通过，则A不通过；③若C不通过，则F不通过；④只有E通过，B才能通过。最终确定E不通过。可以推出（ ）。","options":[{"key":"A","text":"无法确定F是否通过"},{"key":"B","text":"A不能通过"},{"key":"C","text":"无法确定C、D是否通过"},{"key":"D","text":"B能通过"}],"answer":"A","explanation":"E不通过，由B→E的逆否得B不通过；A、B至少一个通过，故A通过；由②逆否可得C、D均通过。③只能由C不通过推出F不通过，而现有C通过，无法确定F。","source":"logic-practice #134","bad":false,"notice":""},{"id":"l135","major":"逻辑题","minor":"综合逻辑","question":"“口红效应”指经济不景气时，人们仍有消费欲望，于是削减或放弃大宗商品消费，转而购买相对廉价的商品。下列属于口红效应的是（ ）。","options":[{"key":"A","text":"面对高房价，很多人选择租房而放弃买房"},{"key":"B","text":"新婚夫妇放弃酒店婚宴，改为出国旅行结婚"},{"key":"C","text":"小王在15万元和12万元的两辆车中选择后者"},{"key":"D","text":"买房率下降时，人们外出就餐的热情不减"}],"answer":"D","explanation":"D同时体现了大宗消费（买房）下降和相对低价消费（外出就餐）仍旺盛，符合定义的替代结构。","source":"logic-practice #135","bad":false,"notice":""},{"id":"l136","major":"逻辑题","minor":"综合逻辑","question":"有学者把“注意”比作知识的窗户：没有注意，知识的阳光照不进来；不当的注意又可能让有害知识进入。这一比喻主要说明（ ）。","options":[{"key":"A","text":"学习和科研中应善于集中并调控注意力"},{"key":"B","text":"注意只是与生俱来的心理品质"},{"key":"C","text":"任何知识都会自动进入人的头脑"},{"key":"D","text":"并不是每个人都能形成任何注意"}],"answer":"A","explanation":"材料强调注意对知识选择和学习科研成效的关键作用，合理结论是主动集中并调控注意力。","source":"logic-practice #136","bad":false,"notice":""},{"id":"l137","major":"逻辑题","minor":"综合逻辑","question":"甲说：“歌手一场演出赚这么多钱不合理，诺贝尔奖获得者对人类贡献那么大，奖金也没这么多。”乙反驳：“二者不同，歌手演出可能给公司带来丰厚收益。”甲的论证主要犯了什么错误？","options":[{"key":"A","text":"把社会贡献与商业收益两个不同评价维度强行类比"},{"key":"B","text":"否定了前件"},{"key":"C","text":"诉诸无知"},{"key":"D","text":"循环论证"}],"answer":"A","explanation":"诺贝尔奖金主要体现社会与学术贡献，演出报酬主要由市场收益决定。把不同评价标准下的金额直接比较，属于不当类比和评价维度混淆。","source":"logic-practice #137","bad":false,"notice":""},{"id":"l138","major":"逻辑题","minor":"综合逻辑","question":"“只有在被统治者不能照旧生活、统治者也不能照旧统治时，革命才会发生；就人民而言，革命往往是在其他道路都走不通之后才‘逼上梁山’。”由此可推出（ ）。","options":[{"key":"A","text":"任何革命都是人为制造的结果"},{"key":"B","text":"革命的发生和发展具有客观条件"},{"key":"C","text":"只要发生革命，群众都会自发参与"},{"key":"D","text":"生活中受挫的人都会支持革命"}],"answer":"B","explanation":"题干强调统治与生活状态、其他道路失败等客观条件，B是恰当概括；A、C、D都将条件绝对化。","source":"logic-practice #138","bad":false,"notice":""},{"id":"l139","major":"逻辑题","minor":"逻辑推理","question":"某高校举行小型学术研讨会。与会者中有4名北方人、3名黑龙江人、1名散文家、3名作家、2名文学家和1名教授；上述身份可以交叉。参会者最少、最多各可能有多少人？","options":[{"key":"A","text":"最少4人，最多6人"},{"key":"B","text":"最少5人，最多11人"},{"key":"C","text":"最少6人，最多9人"},{"key":"D","text":"最少8人，最多10人"}],"answer":"B","explanation":"身份可以重合，且“黑龙江人”属于“北方人”，“散文家”可同时属于“作家、文学家”。尽量重合时至少需要5人；除这些包含关系外尽量不重合时最多为11人。","source":"logic-practice #139","bad":false,"notice":""},{"id":"l140","major":"逻辑题","minor":"逻辑推理","question":"朋友认为父亲看报时拒绝把电视声音调小，说明电视声音并不大。以下哪项如果为真，最能削弱朋友的说法？","options":[{"key":"A","text":"母亲从不看书，不了解看报所需要的环境"},{"key":"B","text":"父亲听力已经下降，通常需要把电视声音开得较大"},{"key":"C","text":"母亲只在吃饭时间看电视"},{"key":"D","text":"父亲年纪大了，行动有些迟缓"}],"answer":"B","explanation":"父亲拒绝调小声音可能是因为听力下降，而不是因为原来的声音不大。B直接提供了替代解释，削弱了朋友的判断。","source":"logic-practice #140","bad":false,"notice":""},{"id":"l141","major":"逻辑题","minor":"逻辑推理","question":"生态系统各构成要素具有不可缺少性，各要素还必须有足够数量并保持协调，才能形成平衡与稳定；只有在这种形态下，生态生产才具有较大生产力和较高产量。由此最恰当地推出（ ）。","options":[{"key":"A","text":"破坏生态平衡必然带来经济增长"},{"key":"B","text":"凭借高技术可以无限索取自然资源而不破坏生态平衡"},{"key":"C","text":"生态系统能够在任何条件下自动恢复平衡"},{"key":"D","text":"扩大生态生产规模、提高产量，必须维护生态系统的平衡与稳定"}],"answer":"D","explanation":"题干把生态系统的平衡稳定作为获得较大生产力和较高产量的必要条件，D准确概括了这一条件关系。","source":"logic-practice #141","bad":false,"notice":""},{"id":"l142","major":"逻辑题","minor":"逻辑推理","question":"珠宝店被盗，警方掌握三条线索：①A、B、C三人中至少一人犯罪；②如果A犯罪，那么B也犯罪；③盗窃发生时B正在咖啡馆喝咖啡。由此可以推出（ ）。","options":[{"key":"A","text":"A是罪犯"},{"key":"B","text":"A、B都是罪犯"},{"key":"C","text":"A、B、C都是罪犯"},{"key":"D","text":"C是罪犯"}],"answer":"D","explanation":"B有不在场证明，故B不犯罪；由“A犯罪→B犯罪”的逆否命题可知A也不犯罪。三人中至少一人犯罪，因此只能是C。","source":"logic-practice #142","bad":false,"notice":""},{"id":"l143","major":"逻辑题","minor":"逻辑推理","question":"如果学生喜欢表演，那么他会报考戏剧学院；如果他不喜欢表演，那么他可以成为戏剧理论家。若他不能成为戏剧理论家，由此可推出（ ）。","options":[{"key":"A","text":"他不喜欢表演"},{"key":"B","text":"他会成为戏剧理论家"},{"key":"C","text":"他不会报考戏剧学院"},{"key":"D","text":"他会报考戏剧学院"}],"answer":"D","explanation":"由“不喜欢表演→可以成为戏剧理论家”逆否可得“不能成为戏剧理论家→喜欢表演”，再结合“喜欢表演→报考戏剧学院”，得到D。","source":"logic-practice #143","bad":false,"notice":""},{"id":"l144","major":"逻辑题","minor":"逻辑推理","question":"小倩想从事会计工作。为了加强“小倩也想取得注册会计师证书”这一结论，以下哪项最合适？","options":[{"key":"A","text":"目前越来越多的会计从业者取得了注册会计师证书"},{"key":"B","text":"不想取得注册会计师证书，就不是一名好的会计工作者"},{"key":"C","text":"只有取得注册会计师证书的人，才有资格从事会计工作"},{"key":"D","text":"凡是想从事会计工作的人，都想取得注册会计师证书"}],"answer":"D","explanation":"D建立了“想从事会计工作→想取得注册会计师证书”的充分条件关系，结合题干可直接推出结论。","source":"logic-practice #144","bad":false,"notice":""},{"id":"l145","major":"逻辑题","minor":"逻辑推理","question":"吴老师、宋老师、孙老师、苏老师分别教授语文、生物、物理、化学中的一门。已知：①如果吴老师教语文，宋老师就不教生物；②或者孙老师教语文，或者苏老师教语文；③如果宋老师不教生物，孙老师也不教物理；④只有吴老师不教化学，苏老师才教物理。下列哪项为真？","options":[{"key":"A","text":"吴老师教语文"},{"key":"B","text":"宋老师不教生物"},{"key":"C","text":"吴老师教化学"},{"key":"D","text":"苏老师不教物理"}],"answer":"C","explanation":"语文由孙或苏教授，可排除吴教语文；结合各科一人、条件③和④逐项排除，吴老师只能教授化学。","source":"logic-practice #145","bad":false,"notice":""},{"id":"l146","major":"逻辑题","minor":"逻辑推理","question":"火车票上写有“限乘当日当次车，在有效期内到达有效”。对这句话理解正确的是（ ）。","options":[{"key":"A","text":"次日的车票可在当日乘车"},{"key":"B","text":"当日不乘指定车次，只要当日到达也有效"},{"key":"C","text":"可以在有效期最后一天才开始乘车"},{"key":"D","text":"必须在当日乘坐指定车次；若中途下车，应在有效期内到达"}],"answer":"D","explanation":"“限乘当日当次车”限定上车日期和车次；“在有效期内到达有效”限定中途下车后的到达期限，D同时保留了两层限制。","source":"logic-practice #146","bad":false,"notice":""},{"id":"l147","major":"逻辑题","minor":"逻辑推理","question":"古代某地只有骑士和无赖两种人：骑士只说真话，无赖只说假话。学者问甲、乙：“你们中有骑士吗？”甲回答：“没有。”则甲、乙分别是（ ）。","options":[{"key":"A","text":"甲是骑士，乙是无赖"},{"key":"B","text":"甲、乙都是骑士"},{"key":"C","text":"甲是无赖，乙是骑士"},{"key":"D","text":"甲、乙都是无赖"}],"answer":"C","explanation":"若甲是骑士，“没有骑士”便与甲自身身份矛盾，所以甲是无赖，其话为假；两人中确有骑士，因此乙是骑士。","source":"logic-practice #147","bad":false,"notice":""},{"id":"l148","major":"逻辑题","minor":"逻辑推理","question":"有些会书法的人会画画；有些会画画的人会唱歌。可以必然判断（ ）。","options":[{"key":"A","text":"有些会画画的人会书法"},{"key":"B","text":"所有会书法的人一定会画画"},{"key":"C","text":"有些会书法的人会唱歌"}],"answer":"A","explanation":"“有些会书法的人会画画”可以换位为“有些会画画的人会书法”。两个“有些”群体未必重合，不能推出C；B把“有些”扩大成“所有”。","source":"logic-practice #148","bad":true,"notice":"原题选项残缺、条件矛盾或答案存在歧义，暂不计分。"},{"id":"l149","major":"逻辑题","minor":"逻辑推理","question":"人们通常认为科学家的思维主要是严格的逻辑思维。研究发现，诺贝尔奖获得者比一般科学家更多利用形象思维，于是有人认为形象思维有助于取得重大科学突破。该论证依赖的假设是（ ）。","options":[{"key":"A","text":"一般科学研究不需要逻辑思维"},{"key":"B","text":"诺贝尔奖获得者只能利用形象思维"},{"key":"C","text":"诺贝尔奖获得者只是比一般科学家更聪明、更勤奋"},{"key":"D","text":"诺贝尔奖获得者比一般科学家更常取得重大科学突破"}],"answer":"D","explanation":"论证要把“更多使用形象思维”与“重大突破”联系起来，必须假设诺贝尔奖获得者确实更常取得重大突破，否则比较无法支持结论。","source":"logic-practice #149","bad":false,"notice":""},{"id":"l150","major":"逻辑题","minor":"逻辑推理","question":"一块麦田今年增产，可能是采用了优良品种，也可能是田间管理做得好，还可能两个原因同时存在。已知这块麦田采用了优良品种，可以推出（ ）。","options":[{"key":"A","text":"增产一定不是因为田间管理好"},{"key":"B","text":"增产一定只由优良品种造成"},{"key":"C","text":"增产一定同时由两个原因造成"},{"key":"D","text":"可能只由优良品种造成，也可能两个原因共同作用"}],"answer":"D","explanation":"知道优良品种这一原因存在，并不能排除田间管理也发挥作用。D完整保留了“单因或共同作用”两种可能。","source":"logic-practice #150","bad":false,"notice":""},{"id":"l151","major":"逻辑题","minor":"逻辑推理","question":"甲、乙、丙、丁四人报考教育心理学。甲预测“四人都能考上”；乙预测“要么乙考上，要么丁考上”；丙预测“丙肯定考不上”；丁预测“乙肯定考不上”。结果四个预测中只有一个为真。哪一人的预测为真？","options":[{"key":"A","text":"甲"},{"key":"B","text":"乙"},{"key":"C","text":"丙"},{"key":"D","text":"丁"}],"answer":"A","explanation":"若四人都考上，甲真；乙的“要么……要么……”按排他关系为假，丙、丁也均为假，恰好一真，符合题意。","source":"logic-practice #151","bad":false,"notice":""},{"id":"l152","major":"逻辑题","minor":"逻辑推理","question":"一个心理健康的人必须保持自尊；一个人只有受到自己所尊敬的人的尊敬，才能保持自尊；用“追星”方式表达尊敬情感的人，不可能受到自己所尊敬的人的尊敬。由此可以推出（ ）。","options":[{"key":"A","text":"心理健康的人不可能用“追星”方式表达自己的尊敬情感"},{"key":"B","text":"心理健康的人不可能接受别人用“追星”方式表达的尊敬"},{"key":"C","text":"受到自己所尊敬的人的尊敬，就一定心理健康"},{"key":"D","text":"保持自尊的人不会尊敬任何用“追星”方式表达情感的人"}],"answer":"A","explanation":"心理健康要求保持自尊，保持自尊又要求受到所尊敬者的尊敬；而“追星”式表达会使该条件不能成立，因此心理健康者不能采用这种表达方式。","source":"logic-practice #152","bad":false,"notice":""},{"id":"l153","major":"逻辑题","minor":"逻辑推理","question":"事物发展的根本原因不在事物外部，而在事物内部，在于事物内部矛盾；任何事物内部都有矛盾。因此（ ）。","options":[{"key":"A","text":"任何事物都处在不断运动和发展之中"},{"key":"B","text":"有一部分事物可以永远处于静止状态"},{"key":"C","text":"处于运动和发展中的事物都以相同速度前进"},{"key":"D","text":"只要没有外部影响，事物就不会发生变化"}],"answer":"A","explanation":"题干把内部矛盾视为发展的根本动力，并指出任何事物都有内部矛盾，因此可推出任何事物都处在运动发展中。","source":"logic-practice #153","bad":false,"notice":""},{"id":"l154","major":"逻辑题","minor":"逻辑推理","question":"古代由于政治、经济和文化发展水平的限制，图书不如今天多、复杂，所以对工具书的需要远不如今天迫切。对这段话最准确的复述是（ ）。","options":[{"key":"A","text":"古代的政治、经济和文化不如今天发达"},{"key":"B","text":"古代的政治对图书有许多限制"},{"key":"C","text":"古代人完全不需要工具书"},{"key":"D","text":"古代人对工具书的需求没有现代人这么迫切"}],"answer":"D","explanation":"材料的中心结论是古代对工具书的需求不如现代迫切；A只是原因，B无依据，C把“不迫切”夸大为“不需要”。","source":"logic-practice #154","bad":false,"notice":""},{"id":"l155","major":"逻辑题","minor":"逻辑推理","question":"中国消费者对奢侈品牌的忠诚度高于西方消费者。许多中国消费者购买奢侈品时，在消费初期更重视价格所代表的身份信号，价格甚至比质量更重要。由此可以推出（ ）。","options":[{"key":"A","text":"中国消费者购买奢侈品时从不考虑质量"},{"key":"B","text":"中国消费者购买奢侈品主要为了满足基本生活需要"},{"key":"C","text":"中国消费者不关注奢侈品的价格"},{"key":"D","text":"知名度更高、价格更能体现身份的奢侈品，可能更吸引部分中国消费者"}],"answer":"D","explanation":"题干强调部分消费者重视价格传递的身份信号，D是谨慎的可能性推论；A、B、C都与材料相悖或过度绝对化。","source":"logic-practice #155","bad":false,"notice":""},{"id":"l156","major":"逻辑题","minor":"逻辑推理","question":"“城市病”通常指人口急剧增加引发的资源短缺、环境污染、交通拥堵、人口拥挤、社会矛盾突出和就业压力增大等问题。它与城市发展进程相伴而生，其根本原因在于（ ）。","options":[{"key":"A","text":"人口增长速度超过了城市发展的承载速度"},{"key":"B","text":"城市发展速度超过了人口增长速度"}],"answer":"A","explanation":"题干列举的问题都源于人口和需求增长快于城市基础设施、资源与治理能力的扩张，即人口增长超过城市承载速度。","source":"logic-practice #156","bad":true,"notice":"原题选项残缺、条件矛盾或答案存在歧义，暂不计分。"},{"id":"l157","major":"逻辑题","minor":"逻辑推理","question":"一位法官审理盗窃案，嫌疑人为甲、乙、丙。甲说：“是乙偷的。”乙说：“不是我偷的。”丙说：“不是我偷的。”三人中只有一人说真话。谁是小偷？","options":[{"key":"A","text":"甲"},{"key":"B","text":"乙"},{"key":"C","text":"丙"},{"key":"D","text":"丁"}],"answer":"C","explanation":"若丙是小偷，甲说假话，乙说真话，丙说假话，恰好一真；若甲或乙是小偷，都会出现两句真话。","source":"logic-practice #157","bad":false,"notice":""},{"id":"l158","major":"逻辑题","minor":"逻辑推理","question":"（ ）对于汽车，相当于开关对于（ ）。","options":[{"key":"A","text":"轮胎；电门"},{"key":"B","text":"方向盘；电灯"},{"key":"C","text":"飞机；电池"},{"key":"D","text":"钥匙；电视"}],"answer":"B","explanation":"方向盘用于控制汽车的行驶方向，开关用于控制电灯的启闭，二者都是控制部件与被控制对象的关系。","source":"logic-practice #158","bad":false,"notice":""},{"id":"l159","major":"逻辑题","minor":"逻辑推理","question":"消防员：灭火：灭火器，与之关系最相近的是（ ）。","options":[{"key":"A","text":"护士：手术：手术刀"},{"key":"B","text":"厨师：炒菜：炒勺"},{"key":"C","text":"老师：教书：粉笔"},{"key":"D","text":"农民：种地：犁"}],"answer":"B","explanation":"“消防员用灭火器灭火”与“厨师用炒勺炒菜”都构成“职业主体—工作行为—直接使用工具”的对应关系。","source":"logic-practice #159","bad":false,"notice":""},{"id":"l160","major":"逻辑题","minor":"逻辑推理","question":"我国科研工作总体上取得很大进步，但科普读物在数量和质量上仍与发达国家有距离。在重大社会问题上，科学家应主动发声，把科学语言转化为百姓听得懂的话，实事求是地讲真话；否则可能引起公众恐慌和社会混乱。材料强调的是（ ）。","options":[{"key":"A","text":"科普工作只需要语言通俗"},{"key":"B","text":"我国科普读物数量少、质量差"},{"key":"C","text":"科研人员负有面向公众开展科学传播的义务"},{"key":"D","text":"科学家只需坚持求真务实，不必参与科普"}],"answer":"C","explanation":"材料重点不只是语言方式或读物数量，而是要求科学家在公共议题中主动、准确地传播科学知识，C概括最全面。","source":"logic-practice #160","bad":false,"notice":""},{"id":"l161","major":"逻辑题","minor":"逻辑推理","question":"某单位把职工分成三个小组进行捕虫数量比赛，甲、乙、丙分属不同小组。甲与第二小组那位捕得数量不同；丙比第一小组那位捕得少；第三小组那位比乙捕得多。按捕虫数量从多到少排列，正确的是（ ）。","options":[{"key":"A","text":"甲、乙、丙"},{"key":"B","text":"甲、丙、乙"},{"key":"C","text":"乙、甲、丙"},{"key":"D","text":"丙、甲、乙"}],"answer":"B","explanation":"由“第三组成员多于乙”可知乙不是第三组；结合丙少于第一组成员及三人分属三组逐项排除，可确定数量顺序为甲＞丙＞乙。","source":"logic-practice #161","bad":false,"notice":""},{"id":"l162","major":"逻辑题","minor":"逻辑推理","question":"甲、乙、丙、丁就X、Y两支球队能否进入决赛发表意见。甲说：“Y能进入决赛。”乙说：“如果X能进入决赛，那么Y也能进入决赛。”丙说：“Y不能进入决赛，但X能进入决赛。”丁说：“X不能进入决赛。”四人中只有一人说对。可以推出（ ）。","options":[{"key":"A","text":"X、Y都能进入决赛"},{"key":"B","text":"X不能进入决赛，Y能进入决赛"},{"key":"C","text":"X、Y都不能进入决赛"},{"key":"D","text":"X能进入决赛，Y不能进入决赛"}],"answer":"D","explanation":"代入D：甲假；乙的充分条件命题为假；丙真；丁假，恰好一真。其他三种情况都会使真话人数不等于一。","source":"logic-practice #162","bad":false,"notice":""},{"id":"l163","major":"逻辑题","minor":"逻辑推理","question":"能认识并接纳自己，坦然面对不可改变的不足，同时仍继续努力完善自己的人，可以说是完整的。我们不求事事圆满，但求问心无愧。下列说法与原文相符的是（ ）。","options":[{"key":"A","text":"不能觉察自身局限的人也是完整的"},{"key":"B","text":"每个人天生就是残缺且无法改变的"},{"key":"C","text":"现实生活中绝大多数人都不完整"},{"key":"D","text":"能承认并接纳自身不足、仍继续努力的人可以说是完整的"}],"answer":"D","explanation":"原文把“完整”理解为认识、接纳自身不足并继续努力，而非毫无缺陷。D准确复述，A、B、C均扩大或曲解原意。","source":"logic-practice #163","bad":false,"notice":""},{"id":"l164","major":"逻辑题","minor":"逻辑推理","question":"中国不缺强大的企业，也不缺受尊敬的企业，但二者并不等同。对内部员工、外部消费者和利益相关者不尊重，对资源、环境不负责的企业，即使再强大也不会受尊重。该论证所需的前提是（ ）。","options":[{"key":"A","text":"企业知名度与受尊敬程度一定成反比"},{"key":"B","text":"只有主动承担对内、对外责任的企业，才可能成为受人尊敬的企业"},{"key":"C","text":"受尊敬程度决定企业能否长期发展"},{"key":"D","text":"企业受尊敬不需要任何客观条件"}],"answer":"B","explanation":"材料从“是否尊重并负责”推向“是否受尊敬”，必须把履行内外部责任视为受尊敬的必要条件，B补足了这一逻辑桥梁。","source":"logic-practice #164","bad":false,"notice":""},{"id":"l165","major":"逻辑题","minor":"逻辑推理","question":"“知己知彼，百战不殆”也适用于人际交往。一个人只有先了解自己，才能了解别人；任何人也只会信赖充分了解他的人。若一个人根本不了解你，他如何值得你信赖？由此可以推出（ ）。","options":[{"key":"A","text":"只有信赖自己，才能信赖别人"},{"key":"B","text":"不了解自己，就不可能真正了解别人并取得他人的信赖"},{"key":"C","text":"充分了解别人，就一定能得到所有人的信赖"},{"key":"D","text":"充分了解自己，就一定能得到许多人的信赖"}],"answer":"B","explanation":"“了解自己”是“了解别人”的必要条件，而充分了解又是获得信赖的必要条件；缺少前一条件，后续关系无法成立。","source":"logic-practice #165","bad":false,"notice":""},{"id":"l166","major":"逻辑题","minor":"逻辑推理","question":"甲、乙、丙、丁四人分别住在宾馆1211、1213、1215、1217、1219五间相邻的客房中，另有一间空房。甲与乙之间隔着两间客房；乙与丙房号之和大于四人中其他任意两人的房号之和；丁与甲相邻，但不与乙、丙相邻。空房号是（ ）。","options":[{"key":"A","text":"1213"},{"key":"B","text":"1211"},{"key":"C","text":"1219"},{"key":"D","text":"1217"}],"answer":"D","explanation":"乙与丙必须占据较大的两个房号以使其和最大；再结合甲乙之间隔两间、丁与甲相邻且不邻乙丙逐一排位，唯一留下的空房为1217。","source":"logic-practice #166","bad":false,"notice":""},{"id":"l167","major":"逻辑题","minor":"逻辑推理","question":"有观点认为，一个人职业上的成功不在于具备多少种职业能力，而在于是否具备特别突出的一项职业能力。该观点成立所需要的假设是（ ）。","options":[{"key":"A","text":"所有职业能力都只能通过后天培养"},{"key":"B","text":"能力是职业成功的唯一标准"},{"key":"C","text":"职业存在专业化分工，而不同岗位往往要求某一项特别突出的能力"},{"key":"D","text":"能力种类越多越好，任何一项突出能力都不重要"}],"answer":"C","explanation":"只有在专业化分工使岗位依赖某项核心能力时，“一项突出能力比能力种类多更重要”才有依据，C是必要的逻辑前提。","source":"logic-practice #167","bad":false,"notice":""},{"id":"l168","major":"逻辑题","minor":"逻辑推理","question":"小明个子比同学矮，为了长高，他每天打篮球。半年后，他的生长速度仍低于一般同学，于是认为打篮球不能帮助长高。以下哪项如果为真，最能削弱他的观点？","options":[{"key":"A","text":"如果不打篮球，小明的生长速度会更慢"},{"key":"B","text":"有人打篮球后身高没有变化"},{"key":"C","text":"和小明一起打篮球的王刚长高了很多"},{"key":"D","text":"和小明一起打篮球的陈维也没有长高"}],"answer":"A","explanation":"A说明打篮球可能已经产生积极作用，只是未使小明达到平均水平；题干把“仍低于平均”误当成“完全没有效果”。","source":"logic-practice #168","bad":false,"notice":""},{"id":"l169","major":"逻辑题","minor":"逻辑推理","question":"有人以“大学附属医院的死亡率高于社区医院或私人医院”为由，断言大学附属医院的医疗水平较低。以下哪项如果为真，最能削弱该结论？","options":[{"key":"A","text":"大学附属医院医生的人数较少"},{"key":"B","text":"大学附属医院的设备与其他医院不同"},{"key":"C","text":"大学附属医院还承担科学研究任务"},{"key":"D","text":"大学附属医院收治的病人通常比社区医院或私人医院的病人病情更重"}],"answer":"D","explanation":"死亡率还受病人初始病情影响。若大学附属医院集中收治重症患者，较高死亡率不能直接说明医疗水平较低。","source":"logic-practice #169","bad":false,"notice":""},{"id":"l170","major":"逻辑题","minor":"逻辑推理","question":"“小的是美好的”作为严格的学术命题并不成立。人们会赞美小桥流水、小山之秀，也会赞叹巍峨高山、巨大瀑布。由此可见（ ）。","options":[{"key":"A","text":"没有绝对的大，也没有绝对的小"},{"key":"B","text":"“小的是美好的”在任何情况下都错误"},{"key":"C","text":"美只与事物大小有关"},{"key":"D","text":"大小何者显得美，要结合具体对象和审美情境判断"}],"answer":"D","explanation":"材料同时列举对“小”和“大”的审美肯定，说明不能脱离对象与情境把大小绝对化，D最符合。","source":"logic-practice #170","bad":false,"notice":""}];